window.DATA={"chapters": [{"id": "c1", "en": "Introduction to Biochemistry", "ar": "مقدمة الكيمياء الحيوية", "num": 1}, {"id": "c2", "en": "Amino Acids of Biological Importance", "ar": "الأحماض الأمينية", "num": 2}, {"id": "c3", "en": "Proteins of Biological Importance", "ar": "البروتينات", "num": 3}, {"id": "c4", "en": "Enzymes", "ar": "الإنزيمات", "num": 4}, {"id": "c5", "en": "Chemistry and Metabolism of Heme", "ar": "كيمياء وأيض الهيم", "num": 5}, {"id": "c6", "en": "Proteins of Extracellular Matrix", "ar": "بروتينات المصفوفة خارج الخلوية", "num": 6}, {"id": "c7", "en": "Carbohydrates of Biological Importance", "ar": "الكربوهيدرات", "num": 7}, {"id": "c8", "en": "Lipids of Biological Importance", "ar": "الدهون", "num": 8}, {"id": "c9", "en": "Chemistry and Metabolism of Nucleotides", "ar": "كيمياء وأيض النيوكليوتيدات", "num": 9}, {"id": "c10", "en": "Nucleic Acids and Genetic Structure", "ar": "الأحماض النووية والبنية الوراثية", "num": 10}, {"id": "c11", "en": "DNA Synthesis (Replication) and Repair", "ar": "تضاعف الـ DNA وإصلاحه", "num": 11}, {"id": "c12", "en": "Gene Expression", "ar": "التعبير الجيني (النسخ والترجمة)", "num": 12}, {"id": "c13", "en": "Regulation of Gene Expression", "ar": "تنظيم التعبير الجيني", "num": 13}, {"id": "c14", "en": "Cell Cycle, Apoptosis & Tumor Suppressor Genes", "ar": "دورة الخلية والموت المبرمج وجينات كبح الأورام", "num": 14}], "cards": [{"ch": "c1", "f": "01 WHAT IS BIOCHEMISTRY?", "b": "• Biochemistry is the study of the chemistry of biological organisms.<br>• It forms a bridge between biology &amp; chemistry by studying how complex chemical reactions and chemical structures give rise to life and life&#x27;s processes.", "p": 3}, {"ch": "c1", "f": "02 NUTRITION & DIETARY COMPONENTS (1/2)", "b": "• <b class=\"rd\">Nutrition:</b><br>&nbsp;&nbsp;&nbsp;– The sum of the processes involved in taking food, its digestion, absorption, metabolism &amp; their impact on health.<br>• <b class=\"rd\">Nutrients:</b><br>&nbsp;&nbsp;&nbsp;– Chemical substances in food which perform specific functions in the body.<br>&nbsp;&nbsp;&nbsp;– They include carbohydrates, lipids, proteins, vitamins, minerals, and water.<br>• <b class=\"rd\">Nutrients are categorized into:</b><br>&nbsp;&nbsp;&nbsp;– <b>Macronutrients:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They include carbohydrates, lipids, and proteins.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are required in grams, and they are energy producing nutrients.<br>&nbsp;&nbsp;&nbsp;– <b>Micronutrients:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They include vitamins and minerals.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are required in milligrams or micrograms<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are non-energy-producing nutrients.<br>&nbsp;&nbsp;&nbsp;– <b>Water:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is required in amounts of 2.5 liters/day.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Requirement can be met by water contained in many foods, vegetables, fruit juice, coffee, tea as well as natural water.", "p": 3}, {"ch": "c1", "f": "02 NUTRITION & DIETARY COMPONENTS (2/2)", "b": "• <b class=\"rd\">Nutrients have mainly the following functions in the body :</b><br>&nbsp;&nbsp;&nbsp;– Supply body with energy needed to carry out diverse functions.<br>&nbsp;&nbsp;&nbsp;– Tissue building and repair .<br>&nbsp;&nbsp;&nbsp;– Maintenance and regulation of body functions.", "p": 3}, {"ch": "c1", "f": "03 CHEMICAL BONDS · A COVALENT BONDS", "b": "&nbsp;&nbsp;&nbsp;– Covalent bond is formed by<b> sharing of a pair of electrons or more</b> between adjacent atoms.<br>&nbsp;&nbsp;&nbsp;– They are<b> strong bonds;</b> considerable energy must be expended to break covalent bonds.<br>• <b class=\"rd\">According to the polarity of covalent bonds, they are classified into:</b>", "p": 3}, {"ch": "c1", "f": "A COVALENT BONDS · 1 Nonpolar Covalent Bond", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Bond between 2 atoms that have the<b> same electronegativity</b> (Power to attract electrons)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Therefore have equal sharing of electrons.", "p": 4}, {"ch": "c1", "f": "A COVALENT BONDS · 2 Polar Covalent Bond", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Bond between 2 atoms that have different electronegativity<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Therefore have unequal sharing of electrons.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The shared electronsare attracted to the more electronegative atom.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Such covalent bond ispolar &amp; will have a dipole (One end is positive δ<sup>+</sup>&amp; the other end isnegative δ<sup>-</sup>) as in water molecules.", "p": 4}, {"ch": "c1", "f": "03 CHEMICAL BONDS · B NONCOVALENT BONDS OR FORCES", "b": "• These are weaker than covalent bonds.<br>• They play an important role in determining many of properties of biomolecules &amp; how these molecules interact with water and with each other.<br>• <b class=\"rd\">They include:</b>", "p": 4}, {"ch": "c1", "f": "B NONCOVALENT BONDS OR FORCES · 1 Hydrogen Bonds", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are weak noncovalent interaction between the hydrogen (δ+) of one molecule &amp; the more electronegative atom (δ-) of an acceptor molecule.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Examples of hydrogen bonding are:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hydrogen bonds between water molecules or between water &amp; other molecules.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hydrogen bonds responsible for<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Protein folding into three-dimensional forms<span class=\"rn\"> (Explained later with protein structure)</span><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– DNA stability<span class=\"rn\"> (Explained later with DNA structure).</span>", "p": 4}, {"ch": "c1", "f": "B NONCOVALENT BONDS OR FORCES · 2 Electrostatic Interactions (Salt Bridge or Ionic Bonds)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Ions are electrically charged particles formed when atoms lose or gain electrons.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Electrostatic interactions or ionic bonds occur between:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Oppositely charged ions (Na<sup>+</sup>&amp; Cl<sup>-</sup>)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Oppositely charged groups (NH<sub>3</sub><sup>+</sup>&amp; COO<sup>-</sup>).", "p": 4}, {"ch": "c1", "f": "B NONCOVALENT BONDS OR FORCES · 3 Van der Waals Forces", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are transient attraction between molecules at a distance →<b> Van der Waals distance.</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Van der Waal force is due to constant motion of electrons that will cause, atany instant, asymmetric distribution of electrons.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The attraction between molecules is greatest at the Van der Waals distance.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– If molecules approach each other more closely, a repulsive force develops, by the negative charges of their outer electron shells.", "p": 4}, {"ch": "c1", "f": "B NONCOVALENT BONDS OR FORCES · 4 Hydrophobic Interactions", "b": "• Hydrophobic interaction refers to the tendency of non polar compounds to cluster together in an aqueous medium, as in case of oil and water.", "p": 5}, {"ch": "c2", "f": "01 INTRODUCTION TO AMINO ACIDS", "b": "• Proteins are organic compounds with a high molecular weight.<br>• Twenty different amino acids are commonly required for synthesis of proteins.<br>• All are α-amino acids except proline which is an imino acid.<br>• These amino acids are organic acids, which have one or more amino groups (NH<sub>2</sub>).", "p": 7}, {"ch": "c2", "f": "02 CLASSIFICATION OF AMINO ACIDS (AAs)", "b": "• <b class=\"rd\">Amino acids can be classified into:</b><br>– <b>Chemical classification:</b> According to their chemical structure.<br>– <b>Polar or non-polar:</b> According to the polarity of the side chain.<br>– <b>Nutritional classification:</b> According to their nutritional importance.<br>– <b>Metabolic classification:</b> According to their metabolic fate.", "p": 7}, {"ch": "c2", "f": "A ALIPHATIC AMINO ACIDS · 1 Neutral Aliphatic Amino Acids", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Short Chain Amino Acids:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Branched Chain Amino Acids:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Hydroxyl Containing Amino Acids:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Sulfur Containing Amino Acids:</b>", "p": 8}, {"ch": "c2", "f": "2 Acidic Aliphatic Amino Acids · Note !!", "b": "• <b>Amides of Acidic Amino Acids:</b><br>&nbsp;&nbsp;&nbsp;– Including asparagine and glutamine<br>&nbsp;&nbsp;&nbsp;– They are neutral AAs derived from acidic AAs aspartic &amp; glutamic acids respectively.", "p": 8}, {"ch": "c2", "f": "C HETEROCYCLIC AMINO ACIDS · Note !!", "b": "• Hydroxylysine &amp; hydroxyproline are formed by hydroxylation of lysine &amp; proline respectively after the synthesis of the protein.<br>• Tyrosine is an aromatic hydroxyl containing amino acid.<br>• Tryptophan can be considered both aromatic and heterocyclic amino acid.<br>• Histidine is a basic heterocyclic amino acid.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <span class=\"rn\">AAs are classified according to polarity of Side Chain (R-Group) into 3 main groups:</span>", "p": 9}, {"ch": "c2", "f": "02 CLASSIFICATION OF AMINO ACIDS (AAs) · A AMINO ACIDS WITH NONPOLAR OR HYDROPHOBIC (R) GROUPS", "b": "&nbsp;&nbsp;&nbsp;– <b>They include the following:</b><br>• Glycine &nbsp;|&nbsp; Alanine &nbsp;|&nbsp; Valine<br>• Leucine &nbsp;|&nbsp; Isoleucine &nbsp;|&nbsp; Methionine<br>• Phenylalanine &nbsp;|&nbsp; Tryptophan &nbsp;|&nbsp; Proline", "p": 9}, {"ch": "c2", "f": "02 CLASSIFICATION OF AMINO ACIDS (AAs) · B AMINO ACIDS WITH UNCHARGED POLAR (R) GROUPS", "b": "&nbsp;&nbsp;&nbsp;– These are more soluble in water than the first group.<br>&nbsp;&nbsp;&nbsp;– Their (R) groups contain neutral polar functional groups → Form hydrogen bonds with water.<br>&nbsp;&nbsp;&nbsp;– <b>They include:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. Serine, threonine, tyrosine and hydroxyproline (Contain hydroxyl group).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. Cysteine (Contains SH group).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. Asparagine and glutamine (Contain amide group).", "p": 10}, {"ch": "c2", "f": "C AMINO ACIDS WITH CHARGED (R) GROUPS · 1 Basic Amino Acids (Diamino-monocarboxylic acids)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">They include the following:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. Lysine<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. Arginine<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. Histidine", "p": 10}, {"ch": "c2", "f": "C AMINO ACIDS WITH CHARGED (R) GROUPS · 2 Acidic Amino Acids (Monoamino-dicarboxylic acids)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">They include the following:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <span class=\"rn\">According to their requirement in diet, AAs are classified into 3 main groups:</span>", "p": 10}, {"ch": "c2", "f": "02 CLASSIFICATION OF AMINO ACIDS (AAs) · A ESSENTIAL AMINO ACIDS", "b": "&nbsp;&nbsp;&nbsp;– They are not formed in the body, and they are essential to be supplied in diet.<br>&nbsp;&nbsp;&nbsp;– Their deficiency decreases the rate of growth and protein synthesis.<br>&nbsp;&nbsp;&nbsp;– <b>There are 9 members:</b><br>• Valine &nbsp;|&nbsp; Leucine &nbsp;|&nbsp; Isoleucine<br>• Threonine &nbsp;|&nbsp; Methionine &nbsp;|&nbsp; Lysine<br>• Phenylalanine &nbsp;|&nbsp; Tryptophan &nbsp;|&nbsp; Histidine", "p": 10}, {"ch": "c2", "f": "02 CLASSIFICATION OF AMINO ACIDS (AAs) · B HALF-ESSENTIAL OR SEMI-ESSENTIAL AMINO ACIDS", "b": "&nbsp;&nbsp;&nbsp;– They are formed in the body at a rate enough for adults but not for growing children &amp; adolescents.<br>&nbsp;&nbsp;&nbsp;– <b>Arginine</b> is the only half-essential amino acid.", "p": 11}, {"ch": "c2", "f": "02 CLASSIFICATION OF AMINO ACIDS (AAs) · C NON-ESSENTIAL AMINO ACIDS", "b": "&nbsp;&nbsp;&nbsp;– These include the rest of the amino acids<br>&nbsp;&nbsp;&nbsp;– They are formed in the body mostly from CHO at a rate enough for adults, growing children, and adolescents.", "p": 11}, {"ch": "c2", "f": "C NON-ESSENTIAL AMINO ACIDS · Note !!", "b": "• Proteins that contain all the essential amino acids are of high biological value (Almost all animal-based proteins, e.g. milk, eggs, and meat).<br>• Proteins that are deficient in one or more of the essential amino acids are of low biological value (Most plant-based proteins, e.g. legumes, nuts, grains, and vegetables).<br>• A mixture of proteins of low biological value may give a protein diet of high biological value.<br>&nbsp;&nbsp;&nbsp;– <span class=\"rn\">According to their metabolic fate, amino acids can be classified into 3 main groups:</span>", "p": 11}, {"ch": "c2", "f": "02 CLASSIFICATION OF AMINO ACIDS (AAs) · A PURE GLUCOGENIC AMINO ACIDS", "b": "&nbsp;&nbsp;&nbsp;– These are amino acids which can give glucose inside the body<br>&nbsp;&nbsp;&nbsp;– Include all amino acids except the members of the other two groups.", "p": 11}, {"ch": "c2", "f": "02 CLASSIFICATION OF AMINO ACIDS (AAs) · B PURE KETOGENIC AMINO ACIDS", "b": "&nbsp;&nbsp;&nbsp;– Amino acids that can give ketone bodies inside body &amp; include leucine &amp; lysine.", "p": 11}, {"ch": "c2", "f": "02 CLASSIFICATION OF AMINO ACIDS (AAs) · C GLUCOGENIC AND KETOGENIC (MIXED) AMINO ACIDS", "b": "&nbsp;&nbsp;&nbsp;– These are amino acids which can give glucose &amp; ketone bodies inside the body<br>&nbsp;&nbsp;&nbsp;– Include phenylalanine, tyrosine, tryptophan, and isoleucine.", "p": 11}, {"ch": "c2", "f": "03 SOME IMPORTANT PROPERTIES OF AMINO ACIDS · A AMPHOTERIC PROPERTY", "b": "&nbsp;&nbsp;&nbsp;– Amino acids can react both with acids and bases, so they are ampholytes.<br>&nbsp;&nbsp;&nbsp;– <b>In acidic medium:</b> They are positively charged (R-NH<sup>+3</sup>).<br>&nbsp;&nbsp;&nbsp;– <b>In alkaline medium:</b> They are negatively charged (R-COO<sup>-</sup>).<br>&nbsp;&nbsp;&nbsp;– <b>At Iso Electric Point (IEP):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Carry equal negative &amp; positive charges, forming dipolar ions (Zwitterions)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Dipolar ions are at pH 6.02 for all monoamino-monocarboxylic amino acids.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– In this form, the amino acid cannot migrate in electric field.", "p": 11}, {"ch": "c2", "f": "03 SOME IMPORTANT PROPERTIES OF AMINO ACIDS · B PEPTIDE BOND FORMATION", "b": "&nbsp;&nbsp;&nbsp;– <b>Dipeptide</b> is formed by the condensation of the carboxylic group of one amino acid with the amino group of a second amino acid losing one molecule of water.<br>&nbsp;&nbsp;&nbsp;– Three amino acids will form<b> tripeptide</b> and so on.<br>&nbsp;&nbsp;&nbsp;– Proteins are formed of many amino acids linked together by peptide bonds.<br>&nbsp;&nbsp;&nbsp;– The term<b> polypeptide</b> means the presence of large number of peptide bonds.<br>&nbsp;&nbsp;&nbsp;– <b>Oligopeptides</b> contain from 2 to 10 amino acids.<br>&nbsp;&nbsp;&nbsp;– <b>Polypeptides</b> contain from 11 to 49 amino acids.<br>&nbsp;&nbsp;&nbsp;– <b>Protein molecules</b> are formed of 50 or more amino acids.", "p": 12}, {"ch": "c3", "f": "01 BIOLOGICAL IMPORTANCE AND FUNCTIONS OF PROTEINS (1/2)", "b": "• Provide the body with essential amino acids, nitrogen, and sulfur.<br>• Enzymes are mainly protein in nature.<br>• Many hormones are peptides or protein in nature (e.g., glucagon and insulin).<br>• The antibodies (Immunoglobulins) which play an important role in the body&#x27;s defensive mechanisms are protein in nature.<br>• Hemoglobin is a chromoprotein. It carries O<sub>2</sub>from the lungs to tissues.<br>• Plasma proteins are responsible for the most effective osmotic pressure of blood. This osmotic pressure plays a central role in many processes e.g., water distribution &amp; urine formation.<br>• Plasma proteins help the transport of many substances in the blood e.g., lipids, hormones (e.g., thyroid hormones) and minerals (e.g., calcium, iron, and copper).", "p": 14}, {"ch": "c3", "f": "01 BIOLOGICAL IMPORTANCE AND FUNCTIONS OF PROTEINS (2/2)", "b": "• Very important components of different types of cell membranes as receptors &amp; transporters.", "p": 14}, {"ch": "c3", "f": "02 STRUCTURE OF PROTEINS", "b": "• <b class=\"rd\">Different Levels of Protein Structure :</b><br>– Proteins in their native state are characterized by their three-dimensional structure.<br>– Proteins formed of one polypeptide chain have primary, secondary and tertiary structures.<br>– Proteins formed of two or more polypeptide chains have an additional quaternary structure.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Structure of proteins can be divided into four orders:</b>", "p": 14}, {"ch": "c3", "f": "02 STRUCTURE OF PROTEINS · A PRIMARY STRUCTURE", "b": "&nbsp;&nbsp;&nbsp;– <b>The primary structure refers to</b> the amino acid sequence of the polypeptide chain.<br>&nbsp;&nbsp;&nbsp;– The primary structure is stabilized by peptide bonds, which are made during the process of protein biosynthesis.<br>&nbsp;&nbsp;&nbsp;– The amino acid sequence of any protein is specific to that protein.<br>&nbsp;&nbsp;&nbsp;– The polypeptide chain starts on the left side by amino acid number 1, which contains a free terminal amino group and termed N-terminus amino acid.<br>&nbsp;&nbsp;&nbsp;– On the right side, at the end, the polypeptide chain contains an amino acid with a free terminal carboxylic group and termed C-terminus amino acid.<br>&nbsp;&nbsp;&nbsp;– The synthesis of the polypeptide chain starts from the N-terminus end toward the C-terminus.<br>&nbsp;&nbsp;&nbsp;– The amino acids sequence is determined by the genetic information present in the DNA.", "p": 14}, {"ch": "c3", "f": "02 STRUCTURE OF PROTEINS · B SECONDARY STRUCTURE", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Includes 2 main regular forms:</b>", "p": 15}, {"ch": "c3", "f": "B SECONDARY STRUCTURE · 1 Helix", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is the folding of the polypeptide chain along its longitudinal axis, into a specific coiled structure stabilized by hydrogen bonds.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Each hydrogen bond is formed between the NH group of an amino acid &amp; the C=O group of an amino acid located exactly four residues earlier in the sequence.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The R-groups of amino acids project outwards of the helix.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Folding can be right- or left-handed:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Right-handed in most proteins<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Left-handed in collagen", "p": 15}, {"ch": "c3", "f": "B SECONDARY STRUCTURE · 2 β -Pleated Sheet", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– If two or more segments of the single polypeptide chain are arranged side by side, β-pleated sheet will be formed and is stabilized by hydrogen bonds.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The R-groups of amino acids project above or below the plane of the sheet.", "p": 15}, {"ch": "c3", "f": "2 β -Pleated Sheet · N.B", "b": "• An individual protein may contain both types of secondary structure.", "p": 15}, {"ch": "c3", "f": "02 STRUCTURE OF PROTEINS · C TERTIARY STRUCTURE", "b": "• It is folding of polypeptide chain of a protein into a specific three-dimensional globular structure.<br>• <b class=\"rd\">This structure is stabilized by different types of of bonds or interactions as follows:</b>", "p": 15}, {"ch": "c3", "f": "C TERTIARY STRUCTURE · 1 Hydrophobic interactions", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Refer to the tendency of nonpolar compounds to cluster together in an aqueous medium.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The nonpolar side chains of neutral amino acids tend to associate together in proteins.", "p": 15}, {"ch": "c3", "f": "C TERTIARY STRUCTURE · 2 Electrostatic bonds (salt bridges or ionic bonds)", "b": "&nbsp;&nbsp;&nbsp;– They are formed between oppositely charged groups of amino acid side chains.<br>&nbsp;&nbsp;&nbsp;– <b>Example:</b> Lysine (positively charged) and aspartic acid (negatively charged) at physiological or body pH.", "p": 16}, {"ch": "c3", "f": "C TERTIARY STRUCTURE · 3 Disulfide Bonds", "b": "&nbsp;&nbsp;&nbsp;– They are present in many proteins, when two cysteine are connected to form cystine e.g., keratin and insulin.", "p": 16}, {"ch": "c3", "f": "C TERTIARY STRUCTURE · 4 Hydrogen bonds", "b": "&nbsp;&nbsp;&nbsp;– <b>Amino acid side chains are involved in hydrogen bonds formation:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The hydroxyl groups of some amino acids (e.g., serine, threonine),<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The amide groups of glutamine and asparagine<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The carboxyl groups of aspartic and glutamic acids<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The ring nitrogen of histidine participate in formation of internal hydrogen bonds.", "p": 16}, {"ch": "c3", "f": "C TERTIARY STRUCTURE · 5 Van der Waals interactions", "b": "&nbsp;&nbsp;&nbsp;– They are transient attractions between molecules at a distance called the<span class=\"rn\"> Van der</span> <span class=\"rn\">Waals distance.</span><br>&nbsp;&nbsp;&nbsp;– These weak interactions also contribute to the stability of proteins.", "p": 16}, {"ch": "c3", "f": "02 STRUCTURE OF PROTEINS · D QUATERNARY STRUCTURE", "b": "• This order is shown only by certain types of proteins which have two or more polypeptide chains (Several subunits or polymers).<br>• Each subunit has its own primary, secondary &amp; tertiary structure and the subunits combine forming the quaternary structure.<br>• High level of organization may be essential for activity of certain proteins (Enzymes &amp; hemoglobin).<br>• Forces that stabilize subunits of this structure are similar to those stabilizing tertiary structure.", "p": 16}, {"ch": "c3", "f": "03 PROTEIN FOLDING AND CHAPERONES · Protein folding", "b": "• The process by which a protein, after being synthesized by a ribosome as a linear chain of amino acids, changes from an unstable random coil into a more ordered &amp; functionally active 3D structure.<br>• The folding process is helped by a complex network of molecular proteins called “Chaperones”<br>• They use different mechanisms to promote efficient protein folding &amp; prevent their aggregation.<br>• An age-related decline in chaperones activity contributes to the development of various protein-aggregation diseases, including Alzheimer&#x27;s disease &amp; Parkinson&#x27;s disease.", "p": 16}, {"ch": "c3", "f": "04 DENATURATION OF PROTEINS", "b": "• <b>Denaturation</b> is a specific property of proteins.<br>• It involves the change of the natural state &quot;Native state&quot; of proteins.<br>• It is due to the rupture of chemical bonds that stabilize the secondary, tertiary, and quaternary structures leaving the protein in its primary structure.<br>• It may be reversible or irreversible and may result in protein coagulation as albumin coagulation by heat (Due to formation of disulfide cross linkage).", "p": 17}, {"ch": "c3", "f": "A FACTORS THAT PRODUCE DENATURATION · 1 Physical agents", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– As heat, mechanical agitation, sonication, ultraviolet irradiation, X-ray etc....", "p": 17}, {"ch": "c3", "f": "A FACTORS THAT PRODUCE DENATURATION · 2 Chemical agents", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– As acids, alkalis, alcohols, urea, salts of heavy metals like Pb<sup>+2</sup>, Ag<sup>+2</sup>, Cu<sup>+2</sup>etc....", "p": 17}, {"ch": "c3", "f": "04 DENATURATION OF PROTEINS · B EFFECTS OF DENATURATION ON PROTEINS", "b": "• <b>Loss of the secondary, tertiary, and quaternary structure</b> of proteins.<br>• <b>Increased viscosity.</b><br>• <b>Decreased solubility</b> due to exposure of nonpolar hydrophobic groups.<br>• <b>Increased digestibility by proteolytic enzymes</b> due to exposure of peptide bonds.<br>• <b>Loss of biologic activity</b> e.g., inactivation of enzymes.<br>• <b>Loss of antigenic property</b> as injection of denatured protein cannot induce antibody formation within the body, in contrast to the action of native proteins.", "p": 17}, {"ch": "c3", "f": "05 CONFORMATIONAL CLASSIFICATION OF PROTEINS", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <span class=\"rn\">Depending on their conformation, proteins are classified into 2 major classes</span>", "p": 18}, {"ch": "c3", "f": "05 CONFORMATIONAL CLASSIFICATION OF PROTEINS · A FIBROUS PROTEINS", "b": "&nbsp;&nbsp;&nbsp;– They consist of polypeptide chains that are arranged in a parallel form along a single axis to yield long fibers or sheets. e.g., collagen, elastin, and α-keratin.", "p": 18}, {"ch": "c3", "f": "05 CONFORMATIONAL CLASSIFICATION OF PROTEINS · B GLOBULAR PROTEINS", "b": "&nbsp;&nbsp;&nbsp;– They are tightly folded into compact spherical or globular shapes. e.g., most enzymes, hemoglobin, myoglobin, many hormones, immunoglobulins, and plasma proteins.", "p": 18}, {"ch": "c3", "f": "06 CHEMICAL CLASSIFICATION OF PROTEINS", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <span class=\"rn\">Depending on their chemical composition &amp; structural complexity,</span><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <span class=\"rn\">Proteins are classified into three main groups:</span>", "p": 18}, {"ch": "c3", "f": "06 CHEMICAL CLASSIFICATION OF PROTEINS · A SIMPLE PROTEINS", "b": "&nbsp;&nbsp;&nbsp;– On hydrolysis, they produce amino acids only, e.g. albumins.", "p": 18}, {"ch": "c3", "f": "06 CHEMICAL CLASSIFICATION OF PROTEINS · B CONJUGATED PROTEINS", "b": "&nbsp;&nbsp;&nbsp;– On hydrolysis, they produce amino acids &amp; other groups (Prosthetic groups) as hemoproteins are formed of protein part attached to heme.", "p": 18}, {"ch": "c3", "f": "06 CHEMICAL CLASSIFICATION OF PROTEINS · C DERIVED PROTEINS", "b": "&nbsp;&nbsp;&nbsp;– These are derived from the above mentioned groups by hydrolysis or denaturation.", "p": 18}, {"ch": "c4", "f": "01 INTRODUCTION TO ENZYMES · A DEFINITION", "b": "&nbsp;&nbsp;&nbsp;– Enzymes are biocatalysts that regulate the rate of biochemical reactions.", "p": 20}, {"ch": "c4", "f": "01 INTRODUCTION TO ENZYMES · B COMMON FEATURES", "b": "&nbsp;&nbsp;&nbsp;– All are produced by living cells and can act outside these cells.<br>&nbsp;&nbsp;&nbsp;– They are needed in very small amounts.<br>&nbsp;&nbsp;&nbsp;– They accelerate the reaction without affecting its equilibrium point.<br>&nbsp;&nbsp;&nbsp;– They are mainly protein in nature, but some RNAs have catalytic activity (e.g., ribozymes).<br>&nbsp;&nbsp;&nbsp;– They are not changed chemically by the end of the reaction.<br>&nbsp;&nbsp;&nbsp;– They are highly specific (act on a specific substrate or inter-related substrates).", "p": 20}, {"ch": "c4", "f": "01 INTRODUCTION TO ENZYMES · C NOMENCLATURE", "b": "&nbsp;&nbsp;&nbsp;– Most enzyme names have the suffix<b> “-ase”</b> attached to the substrate of the reaction (e.g. glucosidase, urease, sucrase).<br>&nbsp;&nbsp;&nbsp;– Some describe the action performed<b> (Lactate dehydrogenase &amp; adenylyl cyclase).</b><br>&nbsp;&nbsp;&nbsp;– Other enzymes retain their original names<b> (As trypsin &amp; pepsin).</b>", "p": 20}, {"ch": "c4", "f": "01 INTRODUCTION TO ENZYMES · D ENZYME SPECIFICITY", "b": "&nbsp;&nbsp;&nbsp;– Enzymes are highly specific in their action.<br>&nbsp;&nbsp;&nbsp;– <b>They interact with :</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– One substrate (e.g., lactase acts on lactose only) or few specific substrates<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Catalyze only 1 type of chemical reaction (e.g: hexokinase enzyme acts on hexoses).<br>&nbsp;&nbsp;&nbsp;– Specificity of enzymes is due to the nature &amp; arrangement of chemical groups at the active site.<br>&nbsp;&nbsp;&nbsp;– This allows the enzyme to bind and activate only one substrate or a small number of structurally related substrates.", "p": 20}, {"ch": "c4", "f": "01 INTRODUCTION TO ENZYMES · E CHEMICAL NATURE", "b": "&nbsp;&nbsp;&nbsp;– Enzymes are either simple or conjugated proteins<b> (Holoenzymes)</b><br>&nbsp;&nbsp;&nbsp;– <b>Holoenzyme =</b> Apoenzyme (Protein part) + Cofactor (Non-protein part).<br>&nbsp;&nbsp;&nbsp;– <b>Cofactors are molecules required for activity of holoenzymes &amp; they are:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Organic (e.g. NAD and FAD)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Inorganic (e.g. metals)", "p": 20}, {"ch": "c4", "f": "02 MECHANISM OF ENZYME ACTION", "b": "• <b>The catalytic action of an enzyme is explained by:</b><br>&nbsp;&nbsp;&nbsp;– Binding of the substrate to the active site of the enzyme.<br>&nbsp;&nbsp;&nbsp;– Lowering of the activation energy required for the reaction.", "p": 21}, {"ch": "c4", "f": "02 MECHANISM OF ENZYME ACTION · A BINDING OF THE SUBSTRATE TO THE ACTIVE SITE OF THE ENZYME", "b": "&nbsp;&nbsp;&nbsp;– The enzyme molecule contains a special pocket called the<b> “Active site”</b>.<br>&nbsp;&nbsp;&nbsp;– The amino acids at the active site are arranged in a very precise manner that creates a 3D surface complementary to the substrate.<br>&nbsp;&nbsp;&nbsp;– The<b> induced fit model</b> states that when a specific substrate binds to the active site of an enzyme forming an enzyme–substrate (ES) complex.<br>&nbsp;&nbsp;&nbsp;– It induces conformational changes of enzyme<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– allowing more fitting &amp; catalysis (Induction).", "p": 21}, {"ch": "c4", "f": "02 MECHANISM OF ENZYME ACTION · B LOWERING OF THE ACTIVATION ENERGY", "b": "&nbsp;&nbsp;&nbsp;– For the reactants to be converted into products, a minimum amount of energy called <b>“Activation energy”</b> is required.<br>&nbsp;&nbsp;&nbsp;– Enzyme accelerates the reaction by lowering the energy of activation without affecting the equilibrium of the reaction.<br>&nbsp;&nbsp;&nbsp;– <b>∆G is the change in the free energy of the reaction:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>∆G =</b> Energy of the products B – Energy of the reactants A<br>&nbsp;&nbsp;&nbsp;– The enzyme does not affect the free energy change of the reaction<b> (∆G)</b><br>&nbsp;&nbsp;&nbsp;– Therefore, does not change the equilibrium of the reaction.", "p": 21}, {"ch": "c4", "f": "03 FACTORS AFFECTING THE RATE (VELOCITY)", "b": "• When studying effect of any factor on enzyme catalysis, only one factor should be varied at a time, while all other factors are kept constant.<br>• The rate of the reaction should always be measured at the very beginning of the reaction<br>• The so-called initial velocity (V<sub>0</sub>or V<sub>i</sub>), to avoid by time decrease of substrate concentration, accumulation of products and equilibrium.", "p": 22}, {"ch": "c4", "f": "03 FACTORS AFFECTING THE RATE (VELOCITY) · A EFFECT OF SUBSTRATE CONCENTRATION [S]", "b": "&nbsp;&nbsp;&nbsp;– The velocity of the reaction increases as the substrate concentration [S] increases up to a point where the enzyme is said to be saturated.<br>&nbsp;&nbsp;&nbsp;– At this point enzyme concentration is the limiting factor.<br>&nbsp;&nbsp;&nbsp;– The measured initial velocity or V<sup>I</sup>increases to a maximum value V<sub>max</sub>.<br>&nbsp;&nbsp;&nbsp;– The substrate concentration that produces half the maximal velocity is termed Michaelis constant or K<sub>m</sub>.<br>&nbsp;&nbsp;&nbsp;– Smaller K<sup>M</sup>reflects higher affinity of the enzyme to its substrate (K<sub>m</sub>1 &lt; K<sub>m</sub>2 in diagram) and vice versa.", "p": 22}, {"ch": "c4", "f": "03 FACTORS AFFECTING THE RATE (VELOCITY) · B EFFECT OF ENZYME CONCENTRATION (E)", "b": "&nbsp;&nbsp;&nbsp;– The velocity of the reaction is<b> directly proportional</b> to the concentration of the enzyme.<br>&nbsp;&nbsp;&nbsp;– This is true up to a point when a further increase in the enzyme concentration is not accompanied by an increase in the velocity of the reaction.<br>&nbsp;&nbsp;&nbsp;– At this point the substrate is said to be the<b> limiting factor</b>.", "p": 22}, {"ch": "c4", "f": "03 FACTORS AFFECTING THE RATE (VELOCITY) · C EFFECT OF TEMPERATURE", "b": "&nbsp;&nbsp;&nbsp;– At 0°C enzyme action virtually stops due to the inhibition of movement and collision between the substrate and enzyme molecules.<br>&nbsp;&nbsp;&nbsp;– <b>As the temperature rises:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Velocity of the reaction increases due to increased kinetic energy of molecules &amp; increased collision between substrate &amp; enzyme molecules, increasing the formation of ES complex.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The increase in velocity of reaction continues up to a point<b> “The optimum temperature”</b>, beyond which any further increase in temperature causes a decrease in reaction rate.<br>&nbsp;&nbsp;&nbsp;– The optimum temperature for most animal enzymes is about 37°C.<br>&nbsp;&nbsp;&nbsp;– The optimum temperature for most plant enzymes is about 50°C.<br>&nbsp;&nbsp;&nbsp;– For most enzymes, the activity virtually stops at around 70°C., due to denaturation of the enzyme protein, disrupting the organization of the active site.", "p": 22}, {"ch": "c4", "f": "03 FACTORS AFFECTING THE RATE (VELOCITY) · D EFFECT OF PH", "b": "&nbsp;&nbsp;&nbsp;– Each enzyme has an optimum pH at which it shows maximal activity.<br>&nbsp;&nbsp;&nbsp;– Activity decreases as we go away from the optimum pH.<br>&nbsp;&nbsp;&nbsp;– It virtually stops at about 2 units of pH above or below this pH.<br>&nbsp;&nbsp;&nbsp;– Slight changes in pH cause marked changes in enzyme activity due to alteration of the charges on the substrate and the active site of the enzyme.<br>&nbsp;&nbsp;&nbsp;– Extreme changes of pH cause denaturation and irreversible inhibition of enzyme action.<br>&nbsp;&nbsp;&nbsp;– Most enzymes have an optimum pH between 5 and 9.<br>&nbsp;&nbsp;&nbsp;– <b>There are some exceptions, for example:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Pepsin, a digestive enzyme in the stomach, is maximally active at pH 2<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Whereas other enzymes, designed to work at neutral pH, are denatured by such an acidic environment.", "p": 23}, {"ch": "c4", "f": "04 REGULATION OF ENZYME ACTIVITY · A SHORT-TERM REGULATION", "b": "&nbsp;&nbsp;&nbsp;– <b class=\"rd\">It occurs within seconds by changing activity of the enzyme &amp; is achieved through:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Availability of cofactors or substrates<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Presence of enzyme inhibitors or activators<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Covalent modification:</b> Reversible phosphorylation/ dephosphorylation", "p": 23}, {"ch": "c4", "f": "04 REGULATION OF ENZYME ACTIVITY · B LONG-TERM REGULATION", "b": "&nbsp;&nbsp;&nbsp;– <b class=\"rd\">It takes hours or days to change amount of the enzyme &amp; is achieved through:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Increasing (or decreasing) degradation of the enzyme.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Increasing synthesis (Induction) or decreasing synthesis (Repression) of the enzyme by regulation of gene expression.", "p": 23}, {"ch": "c4", "f": "05 ENZYME INHIBITION", "b": "• Any substance that can diminish the velocity of enzyme-catalyzed reaction is called an inhibitor.<br>• Enzyme inhibition can be either<b> reversible</b> or<b> irreversible</b>.", "p": 24}, {"ch": "c4", "f": "A REVERSIBLE ENZYME INHIBITION · 1 Competitive Inhibitors (Substrate analogue inhibitors", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– A competitive inhibitor is structurally similar to the of substrate.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hence, it competes with the substrate to bind reversibly to the active site.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Thus, the degree of inhibition depends on ratio of concentration of inhibitor to that of the substrate and not on the absolute concentration of either of them.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Degree of inhibition also depends on relative affinity of substrate &amp; inhibitor to enzyme.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Effect on V</b><sub>max</sub><b class=\"rd\">and K</b><sub>m</sub><b class=\"rd\">:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>No effect on V</b><sub>max</sub><b>:</b> The effect of a competitive inhibitor is reversed by increasing [S] At a sufficiently high substrate concentration.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– the reaction velocity reaches the same V<sub>max</sub>observed in the absence of inhibitor.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>K</b><sub>m</sub><b>increases</b>: A competitive inhibitor increases apparent K<sub>m</sub>for a given substrate.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This means that, in the presence of a competitive inhibitor ,more substrate is needed to achieve ½V<sub>m</sub>.", "p": 24}, {"ch": "c4", "f": "A REVERSIBLE ENZYME INHIBITION · 2 Allosteric Inhibitors", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are small organic molecules that bind to a specific site away from the active site.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They produce conformational changes in enzyme structure that lead to decreased activity of the enzyme e.g., ATP for phosphofructokinase-1.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Effect on Vmax and Km:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Vmax decreases</b>: because they decrease the maximal catalytic activity.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Km increases</b>: because they decrease the affinity of the enzyme to its substrate.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Feedback Inhibition:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is the inhibition of the activity of an enzyme in a pathway by the end products of this pathway.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Occurs through binding of end product to allosteric site present on key enzyme.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This usually occurs at the earliest irreversible step unique to that pathway.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This prevents accumulation of unwanted amounts of metabolic end products.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– In the case of branched biosynthetic pathways,<b> multiple feedback loops</b> are more common for regulation of the enzymes of these pathways.<br>&nbsp;&nbsp;&nbsp;– In this model each of P1 and P2 produces feedback inhibition of a specific enzyme in its biosynthesis i.e. Enz-4 and 5 respectively.<br>&nbsp;&nbsp;&nbsp;– At the same time both produce inhibition of Enz-l (Common for both biosynthetic pathways)<br>&nbsp;&nbsp;&nbsp;– The inhibition of one enzyme by two or more products is additive as the enzyme contains more than one allosteric site (Cumulative feedback inhibition).", "p": 25}, {"ch": "c4", "f": "B IRREVERSIBLE ENZYME INHIBITION · 1 Inhibitors of cofactors (non-protein part)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. <b class=\"rd\">Fluoride:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Blocks the action of enzymes<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It require Ca<sup>+2</sup>&amp; Mg<sup>+2</sup>ions by chelating these ions in the form of salts<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Example:</b> Chelation of Mg<sup>+2</sup>in case of enolase (An enzyme of glucose oxidation), thus inhibiting the enzyme.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. <b class=\"rd\">Cyanide &amp; carbon monoxide:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Inhibit the activity of cytochrome oxidase, an enzyme of the respiratory chain, by blocking the iron of heme.", "p": 26}, {"ch": "c4", "f": "B IRREVERSIBLE ENZYME INHIBITION · 2 Inhibitors of the apoenzyme (Protein part)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These are inhibitors that either denature proteins or block chemical groups which are important for substrate binding and/ or catalysis.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. <b class=\"rd\">Antienzymes</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are specific to enzymes that bind with them and produce their inactivation<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– As antithrombin binds to thrombin and inhibits blood clotting.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. <b class=\"rd\">Inhibitors that denature proteins</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These include strong acids, alkalis, alcohols, and salts of heavy metals.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. <b class=\"rd\">Inhibitors that block chemical groups (enzyme poisons)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Inhibitors of the sulfhydryl groups</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The presence of free SH groups is important for the catalytic activity of many enzymes.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These inhibitors act by binding to or modifying the SH groups thus impairing enzyme function as in arsenic poisoning.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Inhibitors that block hydroxyl groups</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Aspirin produces acetylation of the hydroxyl group of serine at the active site of cyclooxygenase enzyme (Responsible for prostaglandin synthesis), explaining the anti-inflammatory and antipyretic actions of aspirin.", "p": 26}, {"ch": "c4", "f": "06 ENZYME ACTIVATION · A ALLOSTERIC ACTIVATORS", "b": "&nbsp;&nbsp;&nbsp;– The binding of an allosteric activator with the allosteric site produces conformational changes in the protein structure of the enzyme, which result in ↑↑ velocity of the reaction.<br>&nbsp;&nbsp;&nbsp;– Allosteric activator increases affinity of the enzyme to its substrate (Decrease K<sub>m</sub>value) and increases the maximal catalytic activity (Increase V<sub>max</sub>).<br>&nbsp;&nbsp;&nbsp;– <b>Many cellular metabolic reactions are controlled in this way e.g:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– AMP acts as an allosteric activator for the phosphofructokinase-1 (PFK-1).", "p": 27}, {"ch": "c4", "f": "06 ENZYME ACTIVATION · B ACTIVATION OF PROENZYMES (ZYMOGENS)", "b": "&nbsp;&nbsp;&nbsp;– Many enzymes are formed as<b> proenzymes</b> which are<b> inactive</b>.<br>&nbsp;&nbsp;&nbsp;– Activation requires proteolysis (Removal of a part of the polypeptide chain which masks the active site or substrate site).<br>&nbsp;&nbsp;&nbsp;– A good example is the formation of<b> digestive proteolytic enzymes</b> as zymogens inside the cells to prevent digestion of cellular proteins.<br>&nbsp;&nbsp;&nbsp;– When these zymogens are released into the gut, they are activated to digest food proteins<br>&nbsp;&nbsp;&nbsp;– Many of these enzymes after activation can activate their zymogens in a process termed autocatalytic activation<b> (Autocatalysis)</b>.", "p": 27}, {"ch": "c4", "f": "07 COVALENT MODIFICATIONS", "b": "• <b class=\"rd\">Reversible Phosphorylation / Dephosphorylation :</b><br>&nbsp;&nbsp;&nbsp;– Many enzymes are activated by phosphorylation and inactivated by dephosphorylation and vice versa.<br>&nbsp;&nbsp;&nbsp;– This means that the enzyme is present in two interconvertible forms (Phosphorylated &amp; dephosphorylated).<br>&nbsp;&nbsp;&nbsp;– The<b> phosphate</b> groups are usually attached to the<b> hydroxyl group</b> of amino acids<b> (Mainly</b> <b>serine or tyrosine)</b> present in the polypeptide chain of the enzyme.", "p": 27}, {"ch": "c4", "f": "08 CLASSIFICATION OF ENZYMES", "b": "• International Union of Biochemistry and Molecular Biology (IUBMB) developed a system of nomenclature in which enzymes are divided into six major classes, which are summarized in the following table.", "p": 28}, {"ch": "c5", "f": "01 HEMOPROTEINS", "b": "• These are conjugated proteins, containing heme as a “prosthetic group”.<br>• A prosthetic group is a tightly bound non-protein molecule that does not dissociate from the protein and is essential for its biological activity.<br>• <b class=\"rd\">Hemoproteins include:</b>", "p": 30}, {"ch": "c5", "f": "02 CHEMISTRY OF HEME", "b": "• Heme is a ferrous (Fe<sup>+2</sup>) protoporphyrin IX.<br>• Protoporphyrins contain the porphin ring.<br>• Porphin ring is formed of four pyrrole rings linked through methenyl bridges.<br>• The four pyrrole rings are labeled I, II, III, and IV.<br>• Substituent positions on the rings are labeled 7 ,6 ,5 ,4 ,3 ,2 ,1 and 8.<br>• The methenyl bridges are labeled β, α, γ and δ.<br>• <b>The chemical groups attached to porphin ring are of two types:</b><br>– Non-polar groups: four methyl groups (M) and Two vinyl groups (V).<br>– Polar groups: Two propionate groups (P).<br>• The ferrous iron (Fe<sup>+2</sup>) is held in the center of the heme molecule by bonds with four nitrogen atoms of the porphin ring.", "p": 30}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN", "b": "• Both conjugated proteins are formed of heme attached to a basic protein i.e., apomyoglobin in myoglobin and globin in hemoglobin.<br>• Myoglobin is formed of one heme attached to one polypeptide chain, while hemoglobin is formed of four heme groups attached to four polypeptide chains.", "p": 30}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · A GENERAL CHARACHTERS", "b": "&nbsp;&nbsp;&nbsp;– <b>Site</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Myoglobin is present in cardiac and skeletal muscles.<br>&nbsp;&nbsp;&nbsp;– <b>Function</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It functions in both tissues as a reservoir for oxygen, and as an oxygen carrier that increases the rate of release of oxygen within the muscle cell during severe muscular exercise when the partial pressure of oxygen (pO<sub>2</sub>) is reduced to 5mmHg.<br>&nbsp;&nbsp;&nbsp;– <b>Affinity to oxygen</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Myoglobin has a greater affinity to oxygen than hemoglobin, myoglobin is 90% saturated at pO<sub>2</sub>20mmHg", "p": 31}, {"ch": "c5", "f": "B STRUCTURE · 1 The protein part (Apomyoglobin)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Primary structure:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The protein contains 153 amino acids, forming a single polypeptide chain.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Secondary structure:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The chain is folded into eight α-helices named A, B, C, D, E, F, G &amp; H starting from the N -terminal end.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Every amino acid is given a letter to determine its helix and a number to localize its position from the N-terminal end of that helix e.g., His E7 is the amino acid number 7 at the E helix.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The loops in between the helices are given the letters of the two helices they connect e.g., EF connects the helix E with F<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Tertiary structure</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Apomyoglobin is further folded to form a globular protein with the polar amino acids toward the surface (So it is water soluble)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The nonpolar amino acids at the inner part except for the two amino acids histidine F8 and histidine E7 that have a role in oxygen binding.", "p": 31}, {"ch": "c5", "f": "B STRUCTURE · 2 The Heme ring", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is present inside the hydrophobic core of apomyoglobin polypeptide chain in a pocket between E and F helices.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Heme interacts with the chain through:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hydrophobic bonds between its nonpolar side chains and the nonpolar amino acids of the apomyoglobin chain.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Its iron that interacts with the<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– proximal histidine.", "p": 31}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · C INTERACTION OF IRON WITH HEME AND APOMYOGLOBIN", "b": "&nbsp;&nbsp;&nbsp;– <b>Iron in the ferrous state (Fe II) can form 6 coordinate bonds:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Four coordinations are formed between Fe II and the four nitrogen atoms of the porphyrin ring, which lie in the same plane of the ring.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The fifth coordination is for the proximal histidine (His F8)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The sixth coordination is for oxygen.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The latter lies between Fe II &amp; another molecule of histidine termed distal histidine (His E7).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is unoccupied in the absence of O<sub>2</sub>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Both the 5<sup>th</sup>&amp; 6<sup>th</sup>co-ordinations lie in an axis perpendicular to plane of porphyrin ring.", "p": 32}, {"ch": "c5", "f": "C INTERACTION OF IRON WITH HEME AND APOMYOGLOBIN · Biomedical Correlation", "b": "• Myoglobin is present in cardiac and skeletal muscles.<br>• During heart attack or severe muscle damage, myoglobin is released into blood .<br>• It increases in blood 2 to 3 hours after the first symptoms of muscle damage and usually peaks about 8 to 12 hours later.", "p": 32}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · A GENERAL CHARACHTERS", "b": "&nbsp;&nbsp;&nbsp;– <b>Site</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hemoglobin (Hb) is found exclusively in red blood cells<br>&nbsp;&nbsp;&nbsp;– <b>Function</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Transport oxygen from the lungs to all tissues.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Transports CO₂ and H⁺ back to lungs.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The oxy Hb/Hb system acts as a buffer in the RBCs.", "p": 32}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · B STRUCTURE", "b": "&nbsp;&nbsp;&nbsp;– Hemoglobin structure during embryonic and fetal life differs from adulthemoglobin.<br>&nbsp;&nbsp;&nbsp;– All are tetramers formed of different types of polypeptide chains encoded by different genes", "p": 32}, {"ch": "c5", "f": "B STRUCTURE · 1 Embryonic and Fetal Hemoglobin", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Embryonic Hemoglobin (Hb Gower)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The first hemoglobin formed during the first few weeks after conception.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>They include:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hemoglobin Gower-1, consisting of two zeta and two epsilon chains (ζ<sub>2</sub>ε<sub>2</sub>).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hemoglobin Gower-2, consisting of two alpha &amp; two epsilon chains (α<sub>2</sub>ε<sub>2</sub>).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Fetal hemoglobin (HbF)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is formed at the 3<sup>rd</sup>month of pregnancy and remains up to 6 months after birth.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It consists of two alpha and two gamma chains (α<sub>2</sub>γ<sub>2</sub>).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It has higher affinity to O<sub>2</sub>than adult Hb to allow more efficient transplacental transfer of oxygen from maternal to fetal hemoglobin", "p": 33}, {"ch": "c5", "f": "B STRUCTURE · 2 AdultHemoglobin", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is formed at the end of the late month of pregnancy and continues throughout life.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Adult Hb A1 (HbA1):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It forms about 98% of total adult Hb.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It consists of two alpha and two beta chains (α<sub>2</sub>β<sub>2</sub>)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Adult Hb A2 (HbA2):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It forms only 2% of total adult Hb.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It consists of two alpha and two delta chains (δ<sub>2</sub>α<sub>2</sub>).", "p": 33}, {"ch": "c5", "f": "2 AdultHemoglobin · Structure of Hemoglobin A1", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">(The major hemoglobin in adults)</b><br>• It is a tetramer composed of 4 polypeptide chains<br>&nbsp;&nbsp;&nbsp;– 2 identical α-chains<br>&nbsp;&nbsp;&nbsp;– 2 identical β-chains<br>• Each chain binds with one heme ring", "p": 33}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · THE PROTEIN PART (GLOBIN)", "b": "&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Primary structure:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Each α-chain has 7 helices, while each β-chain has 8 helices.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The names of the helices, the amino acids, and the loops between the helices are similar to those of apomyoglobin.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Secondary structure:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Each α-chain has 7 helices, while each β-chain has 8 helices.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The names of the helices, the amino acids, and the loops between the helices are similar to those of apomyoglobin.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Tertiary structure:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Each chain is further folded to form a globular structure with the polar amino acids toward the surface, and the nonpolar amino acids at the inner part.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Quaternary structure:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>The 4 polypeptide chains interact together as follows:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Each (α) and (β) chain are held together forming two identical dimers (αβ)<sub>1</sub>and (αβ)<sub>2</sub>in which the numbers refer to dimers one and two.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The two chains within a dimer are held together by hydrophobic interactions which prevent their movement relative to each other.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– However, the two dimers are linked with each other by non-covalent bonds (e.g., hydrogen and ionic bonds), so the two dimers can move freely during oxygenation and deoxygenation.", "p": 33}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · HEME RINGS", "b": "&nbsp;&nbsp;&nbsp;– Each globin polypeptide chain binds with one heme ring in a similar manner to that described for myoglobin.", "p": 34}, {"ch": "c5", "f": "HEME RINGS · 1c", "b": "• <b class=\"rd\">Hemoglobin A</b><sub>1c</sub><b class=\"rd\">(HbA</b><sub>1c</sub><b class=\"rd\">) (Glycated Hb):</b><br>&nbsp;&nbsp;&nbsp;– Part of adult hemoglobin can bind with blood glucose forming glycated Hb or HbA1c.<br>&nbsp;&nbsp;&nbsp;– Glucose forms a covalent bond with the (N-terminal valine of the β chain).<br>&nbsp;&nbsp;&nbsp;– It is a non-enzymatic reaction that depends on the exposure of RBCs to certain blood glucose levels throughout the life span of RBCs (120 days).<br>&nbsp;&nbsp;&nbsp;– HbA1c represents 4 to 5.7% of HbA in normal individuals.<br>&nbsp;&nbsp;&nbsp;– Higher levels are present in cases of diabetes mellitus, and HbA1c is used as a test to determine the diabetic control of the patients during the last 3 months.", "p": 34}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · C IMPORTANCE OF THE GLOBIN PROTEIN OF HEMOGLOBIN", "b": "&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Makes heme soluble:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Due to the presence of surface polar amino acids.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Prevents iron oxidation:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It prevents the oxidation of heme into hematin (Due to the nonpolar amino acids lining of heme pocket).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Also, it prevents the formation of heme-O<sub>2</sub>-heme complex.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Prevents diffusion of heme to plasma:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Due to its large size<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Reduces the affinity of heme to bind carbon monoxide (CO):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– CO can bind to isolated heme in its preferred orientation i.e., with all three atoms (Fe, C, and O) perpendicular to the plane of the heme, while in myoglobin and hemoglobin the distal histidine sterically hinders this orientation.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Binding at a less favored angle reduces the strength of the heme-CO bond.", "p": 34}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · D AFFINITY OF HEMOGLOBIN TO OXYGEN", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">2 forms of Hb exist depending on presence or absence of oxygen</b>", "p": 35}, {"ch": "c5", "f": "D AFFINITY OF HEMOGLOBIN TO OXYGEN · 1 T form", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The deoxy form of hemoglobin is called the &quot;T&quot; (tense) form.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– In the T form, the two dimers interact through a network of ionic bonds &amp; hydrogen bonds that constrain the movement of the polypeptide chains.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The T form is the low oxygen-affinity form of hemoglobin.", "p": 35}, {"ch": "c5", "f": "D AFFINITY OF HEMOGLOBIN TO OXYGEN · 2 R form", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The binding of oxygen to hemoglobin causes rupture of some of the noncovalent bonds between the two dimers, which allows the dimers to rotate ~15° relative to each other.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This leads to a structure called the &quot;R,&quot; or relaxed form, in which the polypeptide chains have more freedom of movement.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The R form is the high oxygen-affinity form of hemoglobin.", "p": 35}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · E FACTORS AFFECTING THE AFFINITY OF HEMOGLOBIN FOR OXYGEN", "b": "• <b>The ability of hemoglobin to perform its function is affected by:</b><br>• O<sub>2</sub>(Heme-heme interactions) &nbsp;|&nbsp; Bohr effect (pH)<br>• CO &nbsp;|&nbsp; CO<sub>2</sub><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– 2,3bisphosphoglycerate.", "p": 35}, {"ch": "c5", "f": "E FACTORS AFFECTING THE AFFINITY OF HEMOGLOBIN FOR OXYGEN · 1 Binding to oxygen (heme-heme interaction)", "b": "&nbsp;&nbsp;&nbsp;– Although it is more difficult for the first oxygen molecule to bind to hemoglobin<br>&nbsp;&nbsp;&nbsp;– The subsequent binding of oxygen occurs with high affinity.<br>&nbsp;&nbsp;&nbsp;– The net effect is that affinity of hemoglobin for the last oxygen bound is approximately 300 times greater than its affinity for the first oxygen bound.<br>&nbsp;&nbsp;&nbsp;– The cooperative binding of oxygen enhances the efficiency of hemoglobin as an oxygen transporter.", "p": 35}, {"ch": "c5", "f": "E FACTORS AFFECTING THE AFFINITY OF HEMOGLOBIN FOR OXYGEN · 2 Bohr effect (pH)", "b": "&nbsp;&nbsp;&nbsp;– Bohr effect is a physiological phenomenon that explains how hemoglobin&#x27;s oxygen binding affinity is inversely related both to acidity (High proton concentration) and to the concentration of carbon dioxide.<br>&nbsp;&nbsp;&nbsp;– <b>At the tissues:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Carbon dioxide generated in peripheral tissues combines with water to form carbonic acid, which dissociates into protons and bicarbonate ions.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Protons are added to the N-terminal amino groups of the imidazole rings of histidine 146 in the β chain in Hb stabilizing the T-form.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The affinity of Hb to O<sub>2</sub>decreases, which helps the release of O<sub>2</sub>to tissues.<br>&nbsp;&nbsp;&nbsp;– <b>At the lungs:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The reverse occurs and CO<sub>2</sub>is lost.The binding of O<sub>2</sub>to Hb releases 2 protons.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The liberated hydrogen ions combine with bicarbonate, forming carbonic acid, which is broken by carbonic anhydrase to CO<sub>2</sub>and water; then CO<sub>2</sub>is lost through the lungs.", "p": 36}, {"ch": "c5", "f": "E FACTORS AFFECTING THE AFFINITY OF HEMOGLOBIN FOR OXYGEN · 3 Binding to carbon monoxide (Carboxyhemoglobin)", "b": "&nbsp;&nbsp;&nbsp;– Carbon monoxide (CO) binds tightly (but reversibly) to hemoglobin iron, forming carboxyhemoglobin.<br>&nbsp;&nbsp;&nbsp;– When CO binds to one or more of the four heme sites, hemoglobin shifts to the relaxed conformation, causing the remaining heme bind oxygen with high affinity.<br>&nbsp;&nbsp;&nbsp;– As a result, the affected hemoglobin is unable to release oxygen to the tissues.<br>&nbsp;&nbsp;&nbsp;– Since, affinity of hemoglobin for CO is about 200 times greater than for oxygen, as a result even minute concentrations of CO in the environment can produce toxic concentrations of carboxyhemoglobin in the blood.<br>&nbsp;&nbsp;&nbsp;– Carbon monoxide poisoning is treated with 100 percent oxygen therapy, which facilitates the dissociation of CO from hemoglobin.", "p": 36}, {"ch": "c5", "f": "E FACTORS AFFECTING THE AFFINITY OF HEMOGLOBIN FOR OXYGEN · 4 Binding to carbon dioxide (carbamino-hemoglobin)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Most of the carbon dioxide molecules produced in metabolism are hydrated by carbonic anhydrase enzyme and transported as<b> “Bicarbonate ions”.</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– However, some CO<sub>2</sub>is carried as carbamate bound to the uncharged α-amino groups of hemoglobin as<b> “Carbamino-hemoglobin”, as follows:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>At tissues,</b> carbamino-hemoglobin with its negative charge stabilizes the T or deoxy form of hemoglobin, resulting in a decrease of its affinity for oxygen and thus helping the release of oxygen.", "p": 37}, {"ch": "c5", "f": "E FACTORS AFFECTING THE AFFINITY OF HEMOGLOBIN FOR OXYGEN · 5 Binding to -2,3Bisphosphoglycerate (-2,3BPG)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– 2,3-BPG is a by-product of glycolysis in red blood cells that reduces hemoglobin’s affinity for oxygen.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– One molecule of 2,3-BPG binds to a pocket, formed by the two β-globin chains, in the center of the deoxyhemoglobin.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This pocket contains several positively charged amino acid side chains that form ionic bonds with the negatively charged groups of 2,3-BPG.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Binding favors T form reducing the affinity of hemoglobin for oxygen and helps the release of oxygen to the tissues.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– At the lungs, O<sub>2</sub>binds to Hb; the pocket becomes small and BPG slips out.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This favors R form and helps oxygenation.", "p": 37}, {"ch": "c5", "f": "03 MYOGLOBIN AND HEMOGLOBIN · F ORGANIZATION OF GLOBIN GENES", "b": "• The globin genes, which direct the synthesis of the different globin chains, are structurally organized into gene families located on two different chromosomes.", "p": 37}, {"ch": "c5", "f": "F ORGANIZATION OF GLOBIN GENES · 1 α-Gene family", "b": "&nbsp;&nbsp;&nbsp;– <b>The α-gene cluster on chromosome 16 contains:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Two genes for the α-globin chains (α1 &amp; α2).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The zeta gene", "p": 38}, {"ch": "c5", "f": "F ORGANIZATION OF GLOBIN GENES · 2 β- Gene family", "b": "&nbsp;&nbsp;&nbsp;– <b>The β-gene cluster on chromosome 11 contains:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The single β-gene that encodes the β-chain.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Additional four genes:<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. The epsilon (ε) gene is expressed early in embryonic development.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. The δ gene that codes for globin chain is found in minor adult hemoglobin HbA2.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. Two γ-genes which are expressed in fetal hemoglobin.", "p": 38}, {"ch": "c5", "f": "04 HEMOGLOBINOPATHIES", "b": "• <b>Hemoglobinopathies are family of disorders caused by synthesis of:</b><br>&nbsp;&nbsp;&nbsp;– Structurally abnormal globin chains, e.g., Sickle-cell anemia (HbS)<br>&nbsp;&nbsp;&nbsp;– Abnormal reduced amount of α- or β- globin chains, e.g., thalassemias", "p": 39}, {"ch": "c5", "f": "04 HEMOGLOBINOPATHIES · A SICKLE CELL ANEMIA", "b": "• It is a genetic disorder common among black populations all over the world.<br>• <b>Cause:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is caused by a single nucleotide alteration (Point mutation) in the β-globin gene, leading to replacement of polar glutamate at position six with a nonpolar valine.<br>• <b>Mechanism and consequences of sickling:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The nonpolar amino acid generates a hydrophobic<span class=\"rn\"> “Sticky patch”</span> on the surface of the β subunit of both oxy-HbS and deoxy-HbS.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Both HbA and HbS contain a complementary hydrophobic<span class=\"rn\"> “Sticky receptor”</span> on the β subunits only in the deoxygenated state.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Thus<span class=\"rn\">, at low pO</span><sub>2</sub><span class=\"rn\">,</span> deoxy-HbS molecules can polymerize and form long insoluble fibers that distort the RBCs cytoskeleton and push against their membrane giving them the crescent<span class=\"rn\"> (Sickle)</span> shape.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Such sickled cells frequently block the flow of blood in the narrow capillaries leading to localized anoxia<span class=\"rn\"> (Oxygen deprivation)</span> in the tissue, causing pain and eventually death<span class=\"rn\"> (Infarction)</span> of the cells near the blockage.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The spleen removes sickle cells at a faster rate than normal cells<span class=\"rn\"> (Shorter life span)</span>, leading to hemolytic anemia.", "p": 39}, {"ch": "c5", "f": "04 HEMOGLOBINOPATHIES · B THALASSEMIA", "b": "• Thalassemia is a hereditary disease in which there is defective production of either α-chain (α-thalassemia) or the β- chain (β-thalassemia).<br>• Severity of disease depends on number of genes affected &amp; the symptoms vary from very mild to severe anemia and even death of the fetus before birth or immediately after birth.", "p": 39}, {"ch": "c5", "f": "05 METABOLISM OF HEME · A SITE", "b": "• <b>Organ site:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The erythrocyte-producing cells of the bone marrow.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The liver.<br>• <b>Intracellular site:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Some steps in the mitochondria and others in the cytosol.", "p": 40}, {"ch": "c5", "f": "B MAIN STEPS OF HEME SYNTHESIS · 1 Formation of δ-aminolevulinate (In mitochondria)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is formed by condensation of glycine &amp; succinyl-CoA catalyzed by<b> δ-aminolevulinate</b> <b>synthase (ALA synthase)</b>, which is the key regulatory enzyme of the heme biosynthetic pathway.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This enzyme needs pyridoxal phosphate<b> (PLP)</b> as a coenzyme.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– PLP is the active form of vitamin B6.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– ALA synthase is<b> allosterically inhibited by heme</b> (End-product feedback inhibition).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Heme also<b> represses</b> the synthesis of ALA synthase.", "p": 40}, {"ch": "c5", "f": "B MAIN STEPS OF HEME SYNTHESIS · 2 Formation of porphobilinogen (PBG) (In cytosol)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Two molecules of ALA condense forming porphobilinogen (PBG) catalyzed by <b>δ-aminolevulinate dehydratase (ALA dehydratase).</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This enzyme is<b> inhibited by lead</b> in cases of lead poisoning.", "p": 40}, {"ch": "c5", "f": "B MAIN STEPS OF HEME SYNTHESIS · 3 Formation of hydroxymethylbilane (In cytosol)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Four PBG molecules condense to form a linear tetrapyrrole (hydroxymethylbilane), by the enzyme<b> uroporphyrinogen I synthase.</b>", "p": 40}, {"ch": "c5", "f": "B MAIN STEPS OF HEME SYNTHESIS · 4 Formation of uroporphyrinogen III (In cytosol)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hydroxymethylbilane cyclizes to form uroporphyrinogen III by<b> uroporphyrinogen III</b> <b>synthase.</b>", "p": 40}, {"ch": "c5", "f": "B MAIN STEPS OF HEME SYNTHESIS · 5 Formation of coproporphyrinogen III (In cytosol)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The 4 acetate side chains (A) of uroporphyrinogen III are converted to 4 methyl groups (M) by<b> uroporphyrinogen decarboxylase.</b>", "p": 40}, {"ch": "c5", "f": "B MAIN STEPS OF HEME SYNTHESIS · 6 Formation of heme (In mitochondria)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Subsequent reactions by specific<b> oxidases</b> lead to formation of protoporphyrin IX.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Insertion of the ferrous iron into the center of the protoporphyrin ring catalyzed by <b>ferrochelatase (Heme synthase)</b> to form heme.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Ferrochelatase is inhibited by lead.", "p": 40}, {"ch": "c5", "f": "6 Formation of heme (In mitochondria) · Note !!", "b": "• In lead poisoning, lead inhibits ALA dehydratase and ferrochelatase enzyme<br>• Porphyrias are caused by inherited (or occasionally acquired) defects in heme synthesis<br>• Resulting in the accumulation of porphyrins or porphyrin precursors in the tissues and their increased excretion in urine.<br>• <b class=\"rd\">Two types of clinical manifestations can be observed in porphyrias:</b>", "p": 41}, {"ch": "c5", "f": "05 METABOLISM OF HEME · A NEUROPSYCHIATRIC MANIFESTATION (ACUTE PORPHYRIA)", "b": "• These are characterized by the accumulation of ALA or PBG, because of relative or absolute inhibition of the enzymes ALA dehydratase or uroporphyrinogen I synthase, together with increased activity of the enzyme ALA synthase.<br>• <b>ALA and PBG are neurotoxic (Decrease ATPase activity in nerve cells)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They cause injury to sympathetic nerves (Abdominal pain)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Also to somatic nerves (Peripheral neuritis, skeletal muscle paralysis &amp; neuropsychiatric symptoms).<br>• This explains the neuropsychiatric symptoms that occur in acute porphyria.<br>• <b>E.g.:</b> Acute intermittent porphyria (Uroporphyrinogen I synthase deficiency).", "p": 42}, {"ch": "c5", "f": "05 METABOLISM OF HEME · B PHOTOSENSITIVITY", "b": "• Any enzyme defect after synthesis of the porphyrinogen ring will lead to the accumulation of porphyrinogens in the skin, which will be spontaneously oxidized to porphyrins.<br>• Porphyrins absorb light, particularly at a wavelength of 400 nm.<br>• This activates porphyrins to release free radicals that cause damage to lysosomes which release lysosomal enzymes thatdestroy skin cells.<br>• Thus, exposure to light leads to skin damage and scarring.<br>• <b>E.g</b>.: Porphyria cutanea tarda (uroporphyrinogen decarboxylase deficiency).", "p": 42}, {"ch": "c5", "f": "B PHOTOSENSITIVITY · Note !!", "b": "• Many drugs can precipitate acute attacks of porphyria as they induce ALA synthase<br>• <b>E.g.:</b> Barbiturates, estrogens and sulfonamides<br>• A Human turns over approximately 6 g of hemoglobin per day.<br>• It is estimated that 1 g of hemoglobin yields 35 mg of bilirubin.<br>• <b>The formation of the bilirubin occurs subsequently in:</b>", "p": 42}, {"ch": "c5", "f": "B PHOTOSENSITIVITY · 1 Reticuloendothelial System (1/2)", "b": "• After approximately 120 days in the circulation, the erythrocytes are taken up by the reticuloendothelial cells, Where the hemoglobin becomes liberated.<br>• Globin is removed and undergoes proteolysis into amino acids.<br>• The first step in the degradation of heme is catalyzed by the<b> heme oxygenase system</b> of the RE cells in the presence of<b> NADPH and O</b><sub>2</sub><b>.</b><br>• Ferric iron &amp; carbon monoxide are released, resulting in production of green pigment biliverdin.<br>• <b>Biliverdin</b> (Green) becomes reduced to<b> bilirubin</b> (Yellow) by<b> biliverdin reductase.</b><br>• Bilirubin is slightly soluble in plasma; therefore, it is transported in blood carried on albumin.", "p": 43}, {"ch": "c5", "f": "B PHOTOSENSITIVITY · 1 Reticuloendothelial System (2/2)", "b": "• It is the chief bilirubin in the blood, hence the name<b> (Hemobilirubin)</b>, which is also called <b>“Unconjugated bilirubin”</b>. It cannot be excreted in urine.<br>• If the plasma level of this bilirubin exceeds the carrying capacity of albumin (About 20 mg/dL), it passes the blood brain barrier (Due to its hydrophobic nature) &amp; produces brain damage or<b> “Kernicterus”</b>.", "p": 43}, {"ch": "c5", "f": "B PHOTOSENSITIVITY · 2 Liver", "b": "• <b>Unconjugated bilirubin</b> is taken up by liver cells, where bilirubin dissociates from albumin.<br>• Conjugation of bilirubin with glucuronic acid is catalyzed by enzyme glucuronyltransferase.<br>• This type of bilirubin is called<b> “Conjugated bilirubin”.</b><br>• Conjugation increases polarity and water-solubility of bilirubin.<br>• <b>Glucuronylansferase</b> is induced by certain drugs, e.g., phenobarbital, and by glucose.<br>• Excretion of conjugated bilirubin is principally through bile &amp; hence name<b> “Cholebilirubin”.</b><br>• Only traces go back to the blood.<br>• Being water-soluble, conjugated bilirubin is not bound to plasma proteins; thus, it can be excreted in urine but does not pass the blood brain barrier.", "p": 43}, {"ch": "c5", "f": "B PHOTOSENSITIVITY · 3 Intestines", "b": "• In the large intestine, by action of enzymes derived from intestinal bacterial flora, bilirubin is released from glucuronic acid &amp; undergoes successive reductions ending in the formation of stercobilinogen.<br>• <b>The colorless stercobilinogen may have several fates:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The majority are excreted in stools and spontaneously oxidized by the oxygen of air to brown stercobilin, which gives stool its brown color.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– About 10% is absorbed from the intestines and returned, via portal blood, to the liver to be excreted again in bile “Enterohepatic circulation”.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Very little amount normally escapes to the systemic circulation then to the kidneys as colorless urobilinogen where it is converted to yellowurobilin on exposure to air, which gives urine its normal color.", "p": 43}, {"ch": "c5", "f": "06 BLOOD BILIRUBIN (1/2)", "b": "• <b>Serum bilirubin</b> can be estimated by the<b> Van den Bergh reaction</b>, in which the bilirubin is coupled with a certain reagent to yield a violet dye.<br>• The water-soluble<b> conjugated bilirubin</b> (As it is not bound to proteins) reacts rapidly with the reagent (Within one minute) and is said to be<b> “Direct reacting.”</b><br>• The less soluble<b> unconjugated bilirubin</b> (It is bound to albumin) reacts after the addition of solvent like methanol.<br>• Unconjugated bilirubin becomes soluble, and both conjugated and unconjugated bilirubin react with the reagent, providing the<b> “Total bilirubin”</b> value.<br>• <b>The indirect-reacting bilirubin,</b> which corresponds to the unconjugated bilirubin, is obtained by subtracting the direct-reacting bilirubin from the total bilirubin.<br>• <b>Normally</b>:<br>&nbsp;&nbsp;&nbsp;– Total serum bilirubin range 0.2-1.2 mg/dL<br>&nbsp;&nbsp;&nbsp;– Indirect bilirubin range 0.2-0.9 mg/dL<br>&nbsp;&nbsp;&nbsp;– Direct bilirubin &lt; 0.3 mg/dL", "p": 44}, {"ch": "c5", "f": "06 BLOOD BILIRUBIN (2/2)", "b": "• <b class=\"rd\">Definition:</b><br>&nbsp;&nbsp;&nbsp;– Jaundice refers to the yellow discoloration of skin, nails, and sclerae due to elevation of serum bilirubin above 2 mg/dL.<br>• <b class=\"rd\">Classification:</b><br>&nbsp;&nbsp;&nbsp;– <b>According to the predominant form of bilirubin in serum, jaundice is classified into:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Unconjugated hyperbilirubinemia.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Conjugated hyperbilirubinemia.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Both unconjugated and conjugated hyperbilirubinemia (mixed type).", "p": 44}, {"ch": "c5", "f": "A UNCONJUGATEDHYPERBILIRUBINEMIA · 1 Hemolytic jaundice", "b": "&nbsp;&nbsp;&nbsp;– In hemolytic jaundice, there is increased hemolysis, leading to increased production of bilirubin beyond the excretory capacity of the liver.<br>&nbsp;&nbsp;&nbsp;– Serum bilirubin increases,<b> mainly unconjugated bilirubin.</b><br>&nbsp;&nbsp;&nbsp;– Stercobilin increases in feces, which becomes dark brown.<br>&nbsp;&nbsp;&nbsp;– Since unconjugated bilirubin is bound to the plasma albumin, it cannot be excreted in the urine, and hence the name<b> “Acholuric jaundice”.</b><br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Some causes of hemolytic jaundice include:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Abnormal hemoglobin:</b> Sickle cell anemia and thalassemias.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Red cell enzymes deficiency:</b> Glucose-6-P dehydrogenase (G6PD) &amp; pyruvate kinase.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Red cell antibodies:</b> Incompatible blood transfusion &amp; erythroblastosis fetalis.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Some infections</b> e.g., malaria.", "p": 45}, {"ch": "c5", "f": "A UNCONJUGATEDHYPERBILIRUBINEMIA · 2 Physiological neonatal jaundice", "b": "&nbsp;&nbsp;&nbsp;– It is a transient condition that occurs in the first few days of life.<br>&nbsp;&nbsp;&nbsp;– It results partly from increased hemolysis and partly from immaturity of the enzyme UDP-glucuronyltransferase.<br>&nbsp;&nbsp;&nbsp;– Serum bilirubin usually does not reach 13 mg/dL.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Treatment:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Exposure to blue, fluorescent light (Phototherapy)</b> helps conversion of insoluble form of unconjugated bilirubin to the more soluble photoisomers that can be excreted into the bile without conjugation to glucuronic acid.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Phenobarbital</b> may also be used in the treatment of these cases to induce the synthesis of the enzyme glucuronyltransferase", "p": 45}, {"ch": "c5", "f": "A UNCONJUGATEDHYPERBILIRUBINEMIA · 3 Gilbert Syndrome", "b": "&nbsp;&nbsp;&nbsp;– A benign condition caused by a defect in the uptake of unconjugated bilirubin by the liver and conjugation pathways.<br>&nbsp;&nbsp;&nbsp;– Newborns have mildhyperbilirubinemia.", "p": 45}, {"ch": "c5", "f": "06 BLOOD BILIRUBIN · B CONJUGATED HYPERBILIRUBINEMIA (OBSTRUCTIVE JAUNDICE)", "b": "&nbsp;&nbsp;&nbsp;– This is caused by obstruction of the biliary passages, e.g., by gallstones, cancer head of pancreas or inflammation of the pancreas or of the biliary passages.<br>&nbsp;&nbsp;&nbsp;– This leads to regurgitation of conjugated bilirubin to the blood.<br>&nbsp;&nbsp;&nbsp;– Serum bilirubin increases<b> mainly conjugated bilirubin.</b><br>&nbsp;&nbsp;&nbsp;– Stercobilin disappears from the feces leading to clay colored stool.<br>&nbsp;&nbsp;&nbsp;– Conjugated bilirubin becomes excreted in the urine, which becomes<b> dark brown in color.</b><br>&nbsp;&nbsp;&nbsp;– The urine also contains bile salts.<br>&nbsp;&nbsp;&nbsp;– Due to biliary obstruction, serum level of the enzyme<b> alkaline phosphatase (ALP) is</b> <b>elevated.</b>", "p": 46}, {"ch": "c5", "f": "06 BLOOD BILIRUBIN · C BOTH CONJUGATED & UNCONJUGATED HYPERBILIRUBINEMIA", "b": "&nbsp;&nbsp;&nbsp;– This is also called toxic hyperbilirubinemia or hepatocellular jaundice.<br>&nbsp;&nbsp;&nbsp;– <b>It is usually due to:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Viral hepatitis<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– May also be caused by some toxins as paracetamol and chloroform.<br>&nbsp;&nbsp;&nbsp;– Liver capacity to conjugate bilirubin decreases, leading to unconjugated hyperbilirubinemia.<br>&nbsp;&nbsp;&nbsp;– In addition, liver cells usually swell and block the biliary canaliculi, leading to<b> conjugated</b> <b>hyperbilirubinemia.</b><br>&nbsp;&nbsp;&nbsp;– Stercobilin in the feces usually decreases<b> (Faint stool).</b><br>&nbsp;&nbsp;&nbsp;– conjugated bilirubin appears in the urine, which becomes<b> dark brown in color.</b><br>&nbsp;&nbsp;&nbsp;– Due to liver cell damage, the serum levels of the enzymes<b> Alanine Aminotransferase (ALT)</b> and<b> Aspartate Aminotransferase (AST) are elevated.</b>", "p": 46}, {"ch": "c6", "f": "01 INTRO.TO PROTEINS OF EXTRACELLULAR MATRIX", "b": "• The extracellular matrix (ECM) is a major component of the connective tissues(CT) that surround and support the tissues and organs.<br>• <b class=\"rd\">Connective tissue is made up of:</b><br>&nbsp;&nbsp;&nbsp;– <b>Cells:</b> e.g., fibroblasts, macrophages, mesenchymal cells, chondrocytes and osteocytes.<br>&nbsp;&nbsp;&nbsp;– <b>Extracellular matrix:</b> is made up of<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Fibrous proteins: Collagen, elastin, fibrillin, fibronectin and laminin.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Proteoglycans: A core of proteins (5%) attached to glycosaminoglycans (GAGs)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Water<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Minerals", "p": 48}, {"ch": "c6", "f": "02 COLLAGEN", "b": "• It is a fibrous protein &amp; is the most abundant protein in body (Forms 25% of total body proteins).<br>• <b>It is present &amp; has supportive function in:</b><br>&nbsp;&nbsp;&nbsp;– Tendons, skin, cartilage, bones, lungs, liver, vessels, &amp; cornea.<br>• It is synthesized by fibroblasts, mesenchymal cells, chondrocytes, and osteocytes.", "p": 48}, {"ch": "c6", "f": "A STRUCTURE OF COLLAGEN · 1 Tropocollagen molecule", "b": "&nbsp;&nbsp;&nbsp;– It is the building unit of collagen which consists of three coiled α-chains.<br>&nbsp;&nbsp;&nbsp;– Each α-chain is coiled in a left-handed helix.<br>&nbsp;&nbsp;&nbsp;– The presence of prolineprevents right-handed helix formation.<br>&nbsp;&nbsp;&nbsp;– The three left-handed α-chains are tightly twisted to form a right-handed superhelix (Tropocollagen molecule).", "p": 48}, {"ch": "c6", "f": "A STRUCTURE OF COLLAGEN · 2 Amino acid composition", "b": "&nbsp;&nbsp;&nbsp;– Each α-chain contains approximately 1000 amino acids having the repeating triplet sequence Gly-X-Y.<br>&nbsp;&nbsp;&nbsp;– Where Gly is glycine (Present in every third position), X is Proline &amp; Y is hydroxyproline.<br>&nbsp;&nbsp;&nbsp;– The X position is sometimes occupied by lysine<br>&nbsp;&nbsp;&nbsp;– The Y position is sometimes occupied by hydroxylysine.<br>&nbsp;&nbsp;&nbsp;– Different types of collagens vary in number of hydroxylysine residues.<br>&nbsp;&nbsp;&nbsp;– Glucose &amp; galactose molecules are attached to hydroxylysine residues (so collagen is considered as a glycoprotein)", "p": 48}, {"ch": "c6", "f": "02 COLLAGEN · B TYPES OF COLLAGENS", "b": "• The collagen superfamily includes more than twenty collagen types.<br>• <b>The most common types are type I and type II:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Type I contains two identical α1 chains and one α2 chain (α1)<sub>2</sub>(α2)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Type II collagen contains three identical α1 chains (α1)<sub>3</sub>", "p": 49}, {"ch": "c6", "f": "C SYNTHESIS OF COLLAGEN · 1 Intracellular Steps", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Synthesis of preprocollagen α-chain :</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is formed on the rough endoplasmic reticulum .<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Preprocollagen chain has one N-terminal signal peptide &amp; two extension peptides (One at each terminus).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Conversion of preprocollagen α-chain to procollagen α-chain:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Removal of the signal peptide .<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hydroxylation of some proline and lysine residues by hydroxylase enzymes (Require vitamin C as cofactor).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Glycosylation of some hydroxylysine residues by adding glucose or galactose.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Formation of triple helix procollagen molecule :</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>3 procollagen α-chains adhere to form the triple helix procollagen molecule by:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Formation of disulfide bonds in C-terminal extension peptides by oxidation of cysteine residues .<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Folding to form the triple helix.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Secretion:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The procollagen molecules are secreted into extracellular space by exocytosis.", "p": 49}, {"ch": "c6", "f": "C SYNTHESIS OF COLLAGEN · 2 Extracellular Steps", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Formation of tropocollagen molecule:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– By removal of the two extension peptides from the N- &amp; C-terminals by procollagen peptidases.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Formation of collagen fibrils and fibers:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Tropocollagen molecules are assembled in a parallel and staggered array into collagen fibrils that are stabilized by covalent cross-links.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Collagen fibrils are then packed together to form collagen fibers which are further stabilized by the formation of more covalent cross-links", "p": 49}, {"ch": "c6", "f": "2 Extracellular Steps · Note !!", "b": "• The cross-links increase with age and collagen becomes less flexiblebarbiturates, estrogens and sulfonamides).", "p": 49}, {"ch": "c6", "f": "C FACTORS AFFECTING COLLAGEN PRODUCTION · 1 Factors enhancing collagen production", "b": "&nbsp;&nbsp;&nbsp;– <b>Vitamin C:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Essential for the hydroxylation of proline and lysine residues.<br>&nbsp;&nbsp;&nbsp;– <b>Vitamin A</b>:<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Regulates collagen gene expression and promotes collagen synthesis.<br>&nbsp;&nbsp;&nbsp;– <b>Adequate protein intake:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Provides necessary amino acids", "p": 50}, {"ch": "c6", "f": "C FACTORS AFFECTING COLLAGEN PRODUCTION · 2 Factors reducing collagen production", "b": "&nbsp;&nbsp;&nbsp;– <b>Smoking and excessive exposure to UV rays:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Reduce collagen production<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Accelerate collagen degradation<br>&nbsp;&nbsp;&nbsp;– <b>Aging:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– As the body ages, collagen production naturally declines", "p": 50}, {"ch": "c6", "f": "02 COLLAGEN · D COLLAGEN HAS A STRONG STRUCTURE DUE TO", "b": "&nbsp;&nbsp;&nbsp;– Each turn contains 3 amino acid residues (Makes a tight helix), while most of helical proteins contain 3.6 AAs per turn.<br>&nbsp;&nbsp;&nbsp;– The presence of glycine with its short side chain makes polypeptide chains very close to each other.<br>&nbsp;&nbsp;&nbsp;– The 3 left-handed coiled peptide chains form a right-handed superhelix.<br>&nbsp;&nbsp;&nbsp;– High content of hydroxyproline promotes more formation of interchainhydrogen bonds.<br>&nbsp;&nbsp;&nbsp;– The formation of covalent cross linkages between adjacent polypeptide chains is responsible for tensile properties of collagen (Stretched without being broken).<br>&nbsp;&nbsp;&nbsp;– The staggered array (Overhanging) gives marked flexibility to collagen.<br>&nbsp;&nbsp;&nbsp;– The specific arrangement into fibril and fibers.", "p": 51}, {"ch": "c6", "f": "D COLLAGEN HAS A STRONG STRUCTURE DUE TO · Biomedical Correlation", "b": "• <b class=\"rd\">Scurvy:</b><br>&nbsp;&nbsp;&nbsp;– Vitamin C deficiency leads to defective hydroxylation of collagen and thus production of weak collagen bleeding gums, poor wound healing….etc. (see vitamins).<br>• <b class=\"rd\">Ehlers-Danlos syndrome:</b><br>&nbsp;&nbsp;&nbsp;– Defective formation of the covalent cross-links stretchable skin, hypermobile joints, and short stature.<br>• <b class=\"rd\">Osteogenesis imperfecta:</b><br>&nbsp;&nbsp;&nbsp;– Mutation of collagen gene in which glycine residues are replaced by bulky amino acids, preventing the correct folding of the collagen chains into a triple helix and their assembly to form collagen fibrils.<br>&nbsp;&nbsp;&nbsp;– This disease is known as<b> “Brittle bone syndrome”</b> manifested with deformed easily fractured bones, slight spinal curvature, loose joints, and poor muscle tone.", "p": 51}, {"ch": "c6", "f": "03 ELASTIN", "b": "• It is a rubber like protein.<br>• It is present in elastic CT of ligaments, lungs, &amp; walls of blood vessels.<br>• <b class=\"rd\">Structure of Elastin:</b><br>&nbsp;&nbsp;&nbsp;– Tropoelastin is the building unit of elastin.<br>&nbsp;&nbsp;&nbsp;– Tropoelastin is a monomer (One polypeptide chain) rich in lysine.<br>&nbsp;&nbsp;&nbsp;– Some of lysyl residues of tropoelastin are converted by lysyl oxidase enzyme to allysin.<br>&nbsp;&nbsp;&nbsp;– Three allysine plus one unmodified lysine form desmosine cross-link.<br>&nbsp;&nbsp;&nbsp;– This makes elastin extensively interconnected and has rubbery network that can stretch and bend in any direction, giving connective tissue its elasticity.<br>&nbsp;&nbsp;&nbsp;– Elastin is fibrous when stretched, globular when relaxed.", "p": 51}, {"ch": "c6", "f": "03 ELASTIN · Biomedical Correlation", "b": "• <b class=\"rd\">Alpha1- Antitrypsin (AAT) Deficiency</b><br>&nbsp;&nbsp;&nbsp;– AAT protein is produced by the liver, and protects tissues from elastase enzymes produced by inflammatory cells, especially neutrophils.<br>&nbsp;&nbsp;&nbsp;– AAT deficiency is a hereditary disorder causing low levels of this protective protein, thus allowing elastase of neutrophil to break down elastin of the lungs, liver, skin and blood vessels.<br>&nbsp;&nbsp;&nbsp;– Loss of elasticity of the lungs, producing respiratory complications such as emphysema, or COPD (Chronic obstructive pulmonary disease).<br>&nbsp;&nbsp;&nbsp;– The liver produces abnormal, misfolded AAT protein that gets stuck in the liver cells, causing liver damage and cirrhosis", "p": 52}, {"ch": "c7", "f": "01 INTRODUCTION TO CARBOHYDRATES · A DEFINITION", "b": "&nbsp;&nbsp;&nbsp;– Carbohydrates are poly-hydroxy-alcohols with an aldehyde or keto group.<br>&nbsp;&nbsp;&nbsp;– Represented with a general formula Cn(H2O)n &amp; hence are called hydrates of carbon.", "p": 54}, {"ch": "c7", "f": "01 INTRODUCTION TO CARBOHYDRATES · B IMPORTANCE", "b": "&nbsp;&nbsp;&nbsp;– Providing a significant fraction of the dietary calories for energy production.<br>&nbsp;&nbsp;&nbsp;– Acting as a storage form of energy in the body.<br>&nbsp;&nbsp;&nbsp;– Serving as structural components on their own or combined with other molecules.", "p": 54}, {"ch": "c7", "f": "01 INTRODUCTION TO CARBOHYDRATES · C CLASSIFICATION", "b": "&nbsp;&nbsp;&nbsp;– <b class=\"rd\">CHO are classified according to their hydrolysis products into 4 main groups:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Monosaccharides:</b> consist of one monosaccharide unit.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Disaccharides:</b> consist of 2 monosaccharide units per molecule.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Oligosaccharides:</b> consist of 3 to 10 monosaccharide units per molecule.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Polysaccharides:</b> consist of more than 10 monosaccharide units per molecule.", "p": 54}, {"ch": "c7", "f": "02 MONOSACCHARIDES", "b": "• Monosaccharides are the simplest form of carbohydrates (Named simple sugars).<br>• <b class=\"rd\">They are classified according to:</b><br>&nbsp;&nbsp;&nbsp;– <b>Type of carbonyl group</b> which may be an aldehyde group (Aldoses) or a ketone group (ketoses).<br>&nbsp;&nbsp;&nbsp;– <b>Number of carbons in the molecule</b> into trioses (3 carbons), tetroses (4 carbons), pentoses (5 carbons), hexoses (6 carbons) and heptoses (7 carbons).", "p": 54}, {"ch": "c7", "f": "A TYPES · 1 Aldoses", "b": "&nbsp;&nbsp;&nbsp;– Monosaccharides containing aldehyde group (H-C=O) at C1.", "p": 54}, {"ch": "c7", "f": "A TYPES · 2 Ketoses", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Monosaccharides containing ketone group (C=O) at C2.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Cyclization of monosaccharides:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– In solution, the functional group of the monosaccharide (aldehyde or ketone) combines with hydroxyl group of 5<sup>th</sup>carbon atom forming a cyclic (ring) structure.", "p": 55}, {"ch": "c7", "f": "02 MONOSACCHARIDES · B ISOMERISM OF MONOSACCHARIDES", "b": "&nbsp;&nbsp;&nbsp;– <b>Isomers</b> are compounds which have the same molecular formula (the same number and types of atoms) but have different structural or steric formulae.", "p": 55}, {"ch": "c7", "f": "B ISOMERISM OF MONOSACCHARIDES · 1 Enantiomers", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are D- and L- forms of same compounds (mirror images) e.g.,D and L-glucose.", "p": 55}, {"ch": "c7", "f": "B ISOMERISM OF MONOSACCHARIDES · 2 Anomers", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Cyclization creates carbon atoms (C1 in aldose and C2 in ketoses) with two possible orientations of the hydroxyl group around it (α- and β-forms).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The α-form has OH group to right (Down plane of the ring) of carbonyl carbon and the β- form has OH group to left (Above the plane of the ring) of carbonyl carbon.", "p": 55}, {"ch": "c7", "f": "B ISOMERISM OF MONOSACCHARIDES · 3 Aldose-Ketose Isomers (Functional Group Isomerism)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They have the same molecular formulae but differ in their functional groups.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>For example:</b> (Fructose and glucose) and (Dihydroxy acetone and glyceraldehyde).<br>• <b class=\"rd\">Pentoses :</b><br>• <b class=\"rd\">Hexoses :</b><br>&nbsp;&nbsp;&nbsp;– <b>Glucose (Grape sugar):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The main sugar present in blood and is present in all animal and plant cells, honey &amp; fruits.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It enters in the formation of many disaccharides and polysaccharides.<br>&nbsp;&nbsp;&nbsp;– <b>Fructose (Fruit sugar):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is present in honey, fruits, semen, and sucrose.<br>&nbsp;&nbsp;&nbsp;– <b>Galactose:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is a component of lactose (the milk sugar).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is also found in glycosaminoglycans (GAGS), glycolipids and glycoproteins.", "p": 56}, {"ch": "c7", "f": "C MONOSACCHARIDE DERIVATIVES · 1 Sugar acids", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The most important sugar acids are “Uronic acids”, in which primary alcohol group of monosaccharides is oxidized to form corresponding uronic acid.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">For example:</b> <b>Glucose is oxidized to form glucuronic acid which has the following importance:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Glycosaminoglycans (GAGs) synthesis (Aee later).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Conjugation reactions with many compounds to increase their water solubility to facilitate their urinary excretion.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Certain detoxification reactions.", "p": 56}, {"ch": "c7", "f": "C MONOSACCHARIDE DERIVATIVES · 2 Sugar Alcohols", "b": "&nbsp;&nbsp;&nbsp;– These are sugars in which the carbonyl group is reduced to an alcohol group.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Important members of sugar alcohols:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. <b>Glycerol:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is glyceraldehyde or dihydroxyacetone alcohol.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is a component of triacylglycerol and most phospholipids.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. <b>Ribitol:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is ribose alcohol.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is a component of riboflavin (vitamin B2).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. <b>Sorbitol:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is glucose and fructose alcohol.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is a natural product → might be involved in pathogenesis of diabetic complications.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is also used as sweetener.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;4. <b>Mannitol:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is mannose alcohol.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is used as a low-calorie sweetener as it is poorly absorbed by the intestin.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It increases plasma osmolality by drawing water from tissues into blood,<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <span class=\"rn\">So mannitol is used clinically as a:</span><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Diuretic by enhancing urine output and fluid excretion.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Treatment of glaucoma by reducing intraocular pressure.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Treatment of cerebral edema by lowering intracranial pressure.", "p": 57}, {"ch": "c7", "f": "C MONOSACCHARIDE DERIVATIVES · 3 Deoxy sugars", "b": "&nbsp;&nbsp;&nbsp;– These are sugars in which the hydroxyl group at C2 is replaced by a hydrogen atom.<br>&nbsp;&nbsp;&nbsp;– The most important example is the 2-Deoxy ribose which is present in structure of DNA.", "p": 57}, {"ch": "c7", "f": "C MONOSACCHARIDE DERIVATIVES · 4 Amino sugars", "b": "&nbsp;&nbsp;&nbsp;– These are sugars in which the hydroxyl group at C2 is replaced by an amino group (NH<sub>2</sub>)<br>&nbsp;&nbsp;&nbsp;– <b>For example:</b> glucosamine, galactosamine, and mannosamine.<br>&nbsp;&nbsp;&nbsp;– Amino sugars are important constituents of glycosaminoglycans (GAGs) and some types of glycolipids and glycoproteins.", "p": 57}, {"ch": "c7", "f": "03 DISACCHARIDES", "b": "• Disaccharides consist of two monosaccharides linked by glycosidic linkage.<br>• <b>The glycosidic linkage is named according to:</b><br>&nbsp;&nbsp;&nbsp;– The anomeric form (α or β).<br>&nbsp;&nbsp;&nbsp;– The position of the connected carbons.<br>&nbsp;&nbsp;&nbsp;– The sugar providing its anomeric carbon", "p": 58}, {"ch": "c7", "f": "03 DISACCHARIDES · A MALTOSE (MALT SUGAR)", "b": "• It is formed of 2 molecules of glucose united by α 1,4-glucosidic linkage.<br>• Maltose is main product of digestion of starch by amylase.<br>• It is hydrolyzed by maltase enzyme or by acids into two molecules of D-glucose.", "p": 58}, {"ch": "c7", "f": "03 DISACCHARIDES · B LACTOSE (MILK SUGAR)", "b": "• It is formed of galactose and glucose united by β1,4-galactosidic linkage.<br>• It is hydrolyzed by lactase enzyme or by acids into glucose and galactose.", "p": 58}, {"ch": "c7", "f": "03 DISACCHARIDES · C SUCROSE (CANE OR TABLE SUGAR)", "b": "• It is present in plants as sugar cane and beets.<br>• Formed of Fructose &amp; Glucose united by α1,2-glucosidic linkage or β1,2-fructosidic linkage.", "p": 58}, {"ch": "c7", "f": "03 DISACCHARIDES", "b": "• Disaccharides consist of two monosaccharides linked by glycosidic linkage.<br>• <b>The glycosidic linkage is named according to:</b><br>&nbsp;&nbsp;&nbsp;– The anomeric form (α or β).<br>&nbsp;&nbsp;&nbsp;– The position of the connected carbons.<br>&nbsp;&nbsp;&nbsp;– The sugar providing its anomeric carbon", "p": 58}, {"ch": "c7", "f": "03 DISACCHARIDES · A MALTOSE (MALT SUGAR)", "b": "• It is formed of 2 molecules of glucose united by α 1,4-glucosidic linkage.<br>• Maltose is main product of digestion of starch by amylase.<br>• It is hydrolyzed by maltase enzyme or by acids into two molecules of D-glucose.", "p": 59}, {"ch": "c7", "f": "03 DISACCHARIDES · B LACTOSE (MILK SUGAR)", "b": "• It is formed of galactose and glucose united by β1,4-galactosidic linkage.<br>• It is hydrolyzed by lactase enzyme or by acids into glucose and galactose.", "p": 59}, {"ch": "c7", "f": "03 DISACCHARIDES · C SUCROSE (CANE OR TABLE SUGAR)", "b": "• It is present in plants as sugar cane and beets.<br>• Formed of Fructose &amp; Glucose united by α1,2-glucosidic linkage or β1,2-fructosidic linkage.", "p": 59}, {"ch": "c7", "f": "04 POLYSACCHARIDES", "b": "• They are composed of more than 10 monosaccharide units linked by glycosidic bonds.<br>• <b>Polysaccharides are sub-classified into:</b> Homopolysaccharides and Heteropolysaccharides.", "p": 59}, {"ch": "c7", "f": "04 POLYSACCHARIDES · A HOMOPOLYSACCHARIDES", "b": "• They are polysaccharides entirely made up of the same type of monosaccharide units.<br>• <b>For example:</b> starch, glycogen, and cellulose.", "p": 59}, {"ch": "c7", "f": "A HOMOPOLYSACCHARIDES · 1 Starch", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Starch is the chief storage form of carbohydrates in plants.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is present with large amounts in cereals (Rice and wheat), tubers (Potatoes &amp; sweet potatoes) &amp; legumes (Beans).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Starch granules contain 2 forms, both present in same granule with different ratios:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Amylose:</b> (20–30%) A linear polymer where glucose units are linked by α1,4-glucosidic bonds.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Amylopectin:</b> (70–80%) A highly branched polymer containing both α1,4-glucosidic bonds for the main chain &amp; α-1,6 glucosidic bonds at branching points.", "p": 59}, {"ch": "c7", "f": "1 Starch · Note !!", "b": "• The ratio of amylose/amylopectin in starch granules affects digestibility, i.e. the higher the ratio, the slower the digestion and thus healthier effect.<br>• <b>For example:</b> Starch in short-grain rice has low ratio (~20:80 %), while starch in beans show higher ratio (~40:60) leading to slower digestion and healthier benefits.", "p": 59}, {"ch": "c7", "f": "A HOMOPOLYSACCHARIDES · 2 Glycogen", "b": "&nbsp;&nbsp;&nbsp;– Glycogen is the storage form of carbohydrates in animals.<br>&nbsp;&nbsp;&nbsp;– Present in most cells but especially in skeletal muscles &amp; liver (As stores of excess glucose).<br>&nbsp;&nbsp;&nbsp;– It is a highly branched molecule (more branched than starch); glucose units are connected by α-1,4glucosidic bonds within the branches &amp; α-1,6glucosidic bonds at branching points.", "p": 60}, {"ch": "c7", "f": "A HOMOPOLYSACCHARIDES · 3 Cellulose", "b": "&nbsp;&nbsp;&nbsp;– Cellulose forms the principal part of the cell wall of plants.<br>&nbsp;&nbsp;&nbsp;– Formed of a long non-branched chain of β-glucose units connected by β-1,4 glucosidic linkage.", "p": 60}, {"ch": "c7", "f": "3 Cellulose · Biomedical Correlation", "b": "• Cellulose in humans, as a key component of dietary fibers, is non-hydrolysable by amylase digestive enzyme because this enzyme hydrolyzes only α- linkages.<br>• <b>Cellulose in diet is important in:</b><br>&nbsp;&nbsp;&nbsp;– Preventing constipation as it increases bulk of stool → Stimulates intestinal contractions.<br>&nbsp;&nbsp;&nbsp;– Delaying fat absorption.<br>&nbsp;&nbsp;&nbsp;– Protecting against cancer colon.", "p": 60}, {"ch": "c7", "f": "04 POLYSACCHARIDES · B HETEROPOLYSACCHARIDES", "b": "• These are polysaccharides which are formed of more than 1 type of monosaccharide unit.<br>• They include glycosaminoglycans (GAGs) that were formerly called mucopolysaccharides.", "p": 60}, {"ch": "c7", "f": "B HETEROPOLYSACCHARIDES · 1 Glycosaminoglycans (GAGs)", "b": "&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Glycosaminoglycans are:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Unbranched<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Long chains (Usually &gt;50 sugar units) heteropolysaccharides<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Mostly composed of repeating disaccharide units, each of which is made up of an amino sugar and a uronic acid.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Glycosaminoglycans are classified into:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Sulfate free glycosaminoglycans: hyaluronic Acid<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Sulfate containing glycosaminoglycans:</b> chondroitin sulfate, keratan sulfate, dermatan sulfate, heparin and heparan sulfate.<br>• <b class=\"rd\">General properties of GAGs:</b><br>&nbsp;&nbsp;&nbsp;– The negatively charged carboxylate &amp; sulfate groups of GAGs help to trap water molecules<br>&nbsp;&nbsp;&nbsp;– Thereby creating a hydrated gel with<b> the following advantages:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. Provides flexible mechanical support for the extracellular matrix.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. Acts as a lubricant in synovial fluid.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. Acts as shock absorbent:<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– When a GAG solution is compressed, the water squeezed out &amp; GAGs occupy a<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– smaller volume.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– When compression is released,their molecules regain their original hydrated size.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This ex plains their role as shock absorbent in joints and making eyeball resilient.", "p": 60}, {"ch": "c7", "f": "B HETEROPOLYSACCHARIDES · A Hyaluronic acid", "b": "• <b class=\"rd\">It is distributed in many tissues and is abundant mainly in:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Skin:</b> Aging is associated with reduced production of skin hyaluronic acid and collagen, with decrease in the formation of hydrating gel, causing loss of facial volume and the appearance of wrinkles.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Joints:</b> In osteoarthritis, the concentration of hyaluronic acid gradually decreases, lowering the lubricant effect of synovial fluid.", "p": 61}, {"ch": "c7", "f": "A Hyaluronic acid · Hyaluronidase enzyme (Spreading factor)", "b": "• It can hydrolyze hyaluronic acid present in the ground substance of connective tissue.<br>• Hyaluronidase secreted by some bacteria helps spread of bacteria through subcutaneous tissues.<br>• It is present in sperms (heads) to help the process of ovum fertilization.", "p": 61}, {"ch": "c7", "f": "B HETEROPOLYSACCHARIDES · B Chondroitin sulfate", "b": "• It is the prominent component of cartilage, tendons, ligaments, bone, and aorta.<br>• It is commonly used as an oral treatment for osteoarthritis.", "p": 61}, {"ch": "c7", "f": "B HETEROPOLYSACCHARIDES · C Keratan sulfate", "b": "• It is one of the major components of the cornea and suggested to have important roles for corneal development and maintenance of its transparency.", "p": 61}, {"ch": "c7", "f": "B HETEROPOLYSACCHARIDES · D Heparin", "b": "• <b>Proteoglycan is an important anticoagulant</b> (Prevents thrombus formation) by:<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Inactivation of blood clotting factors IX and XI by binding to them.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Activation of antithrombin III by acting as a catalyst for it.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Also, Heparin helps in removal and clearance of blood lipids by binding to lipoprotein lipase enzyme and increasing its release from the capillary wall to the plasma.", "p": 61}, {"ch": "c7", "f": "B HETEROPOLYSACCHARIDES · 2 Proteoglycans (1/2)", "b": "• Most of the<b> GAGs</b> are covalently conjugated to a<b> protein core</b>, the product of which is termed<b> proteoglycans</b>.<br>• They are formed mainly of carbohydrates (%95) and only (%5) proteins.<br>• Proteoglycans are major constituents of extracellular matrix (ECM)<br>• They contribute to matrix organization &amp; interact with structural proteins e.g. collagen &amp; elastin.<br>• <b>Aggrecan</b> is the major proteoglycan present in cartilage.<br>• It has a very complex structure containing several types of GAGs (Hyaluronic acid, chondroitin sulfate &amp; keratan sulfate) attached to a protein core and a link protein.<br>• It has a<b> bottle brush shape.</b><br>• It is formed of a central long chain of hyaluronic acid attached to link proteins, which are attached to core proteins.", "p": 62}, {"ch": "c7", "f": "B HETEROPOLYSACCHARIDES · 2 Proteoglycans (2/2)", "b": "• Different types of GAGs project from these core proteins.<br>• <b class=\"rd\">Structure of aggrecan changes with age:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Keratan sulfate and protein contents increase.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Chondroitin sulfate content decreases.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Hyaluronic acid chain becomes shorter.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The average size decreases.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Thus, with age, cartilage compressibility will decrease, and human stature</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">will shorten.</b>", "p": 62}, {"ch": "c8", "f": "01 INTRODUCTION TO LIPIDS · A DEFINITION", "b": "• Lipids are hydrophobic organic compounds which are insoluble in water but soluble in fat solvents (Nonpolar solvents) e.g., benzene, alcohol, ether, chloroform, and acetone.", "p": 64}, {"ch": "c8", "f": "01 INTRODUCTION TO LIPIDS · B IMPORTANCE", "b": "• Lipids provide the body with energy (9.3 kcal /gm).<br>• Supply body with fat-soluble vitamins and essential fatty acids.<br>• Lipids inside the body have many biological functions (see later).", "p": 64}, {"ch": "c8", "f": "02 FATTY ACIDS", "b": "• <b>Fatty acids</b> are monocarboxylic acids with hydrocarbon chains.<br>• They are the main components of all lipids", "p": 64}, {"ch": "c8", "f": "02 FATTY ACIDS · A NOMENCLATURE", "b": "• <b>The carboxyl carbon</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is carbon No. 1<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The carbon atoms adjacent to it are numbered as 2 ,3 ,4…etc.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are also known as α, β, γ…etc. carbons respectively.<br>• <b>The terminal methyl group:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is known as the ω1 carbon which is used to indicate the site of a double bond.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– For example: ω3 indicates a double bond between 3<sup>rd</sup>&amp; the 4<sup>th</sup>carbons counting from the terminal methyl group.", "p": 64}, {"ch": "c8", "f": "B CLASSIFICATION OF FATTY ACIDS · 1 According to the Length of the Chain", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Short chain fatty acids (from C<sub>2</sub>to C<sub>6</sub>)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Medium chain fatty acids (from C<sub>8</sub>to C<sub>10</sub>)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Long chain fatty acids (from C<sub>12</sub>to C<sub>22</sub>)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Very long chain fatty acids (≥ C<sub>24</sub>)", "p": 64}, {"ch": "c8", "f": "B CLASSIFICATION OF FATTY ACIDS · 2 According to the Number of Carbon Atoms", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Even chain fatty acids<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Odd chain fatty acids<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Most naturally occurring fatty acids (&gt; 95%) have an even number.</b>", "p": 64}, {"ch": "c8", "f": "3 According to the Existence of Double Bonds · A. Saturated Fatty Acids (SFA)", "b": "• They contain no double bonds.<br>• <b>For example:</b><br>• The most important saturated fatty acids are<b> palmitic</b> and<b> stearic acids</b><br>• They are widely distributed in animal fats.<br>• <b>Sources:</b><br>– Whole-milk, whole-milk products (cream, cheese, and butter), and fatty meats.", "p": 65}, {"ch": "c8", "f": "3 According to the Existence of Double Bonds · Biomedical Correlation", "b": "• Increased intake of saturated fatty acids may lead to an increase of plasma cholesterol levels that predispose to atherosclerosis and coronary heart disease.", "p": 65}, {"ch": "c8", "f": "3 According to the Existence of Double Bonds · B. Unsaturated Fatty Acids (USFA)", "b": "• They contain one or more double bonds<br>• Classified according to the orientation of hydrogen atoms around the double bond into<b> cis fatty</b> <b>acids</b> and<b> trans fatty acids</b><br>• <b class=\"rd\">1. Cis Fatty acids:</b><br>• Both hydrogen atoms are on the same side of the double bond.<br>• Fatty acids with cis type are present in natural foods &amp; they are liquid at room temperature.<br>• <b>They are classified according to the number of double bonds in their chains into two main</b> <b>groups:</b><br>&nbsp;&nbsp;&nbsp;– Monoenoic acids: Contain one double bond.<br>&nbsp;&nbsp;&nbsp;– Polyenoic acids:<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They have more than one double bond in their structure<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Thus termed polyunsaturated fatty acids (PUFA).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They include two important families which are ω3 &amp; ω6 PUFA.<br>• <b>Sources:</b><br>&nbsp;&nbsp;&nbsp;– Nuts, plant oils (Olive,sunflower,cottonseed,corn, flaxseed oils)<br>&nbsp;&nbsp;&nbsp;– Fish oil are rich sources.", "p": 65}, {"ch": "c8", "f": "3 According to the Existence of Double Bonds · Biomedical Correlation", "b": "• Intake of cis fatty acids may reduce incidence of atherosclerosis &amp; cardiovascular disease<br>• They lower plasma cholesterol &amp; triacylglycerol levels, lower blood pressure and decrease the tendency to intravascular thrombosis.<br>• <b class=\"rd\">Trans Fatty acids:</b><br>• The two hydrogen atoms exist on opposite sides of the double bond.<br>• Trans fatty acids are solid at room temperature.<br>• <b>Sources:</b><br>&nbsp;&nbsp;&nbsp;– Very small amounts of trans-unsaturated fatty acids are found in butter<br>&nbsp;&nbsp;&nbsp;– The main source in human diet is from partially hydrogenated vegetable oils ( margarine).<br>&nbsp;&nbsp;&nbsp;– They are present in many commercial baked foods like cakes and cookies, frozen pizza and most fried foods.", "p": 66}, {"ch": "c8", "f": "3 According to the Existence of Double Bonds · Biomedical Correlation", "b": "• Trans FAs compete with essential fatty acids &amp; may exacerbate essential FA deficiency.<br>• Also, they are structurally similar to saturated fatty acids, thus they can worsen hypercholesterolemia &amp; atherosclerosis.", "p": 66}, {"ch": "c8", "f": "B CLASSIFICATION OF FATTY ACIDS · 4 NutritionalClassification", "b": "• <b class=\"rd\">A. Essential Fatty Acids:</b><br>&nbsp;&nbsp;&nbsp;– They are not synthesized in our body, so it is essential to take them in diet.<br>&nbsp;&nbsp;&nbsp;– They include α-linolenic and linoleic acids.<br>&nbsp;&nbsp;&nbsp;– Arachidonic acid is synthesized in our bodies from linoleic acid, but in the absence of linoleic acid, it will be considered as an essential fatty acid.<br>&nbsp;&nbsp;&nbsp;– <b>Importance of essential fatty acids:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Formation of healthy cell membrane.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Provide arachidonic acid for synthesis of eicosanoids (discussed later).<br>• <b class=\"rd\">B. Non-Essential Fatty Acids:</b><br>&nbsp;&nbsp;&nbsp;– They include all other fatty acids because they are formed in our body in good amounts mainly from carbohydrates.<br>&nbsp;&nbsp;&nbsp;– It is not essential to take them in diet.", "p": 67}, {"ch": "c8", "f": "03 CLASSIFICATION OF LIPIDS", "b": "• <b class=\"rd\">Lipids are classified into three main groups according to their composition:</b><br>&nbsp;&nbsp;&nbsp;– <b>Simple lipids:</b> Esters of fatty acids with various alcohols.<br>&nbsp;&nbsp;&nbsp;– <b>Compound (Conjugated) lipids:</b> In addition to esters of fatty acids with alcohol, another group is added.<br>&nbsp;&nbsp;&nbsp;– <b>Derived lipids:</b> They are fat soluble products of hydrolysis of the first two groups, or present in association with them in nature.", "p": 67}, {"ch": "c8", "f": "03 CLASSIFICATION OF LIPIDS · A SIMPLE LIPIDS", "b": "&nbsp;&nbsp;&nbsp;– They are esters of fatty acids with alcohol.<br>&nbsp;&nbsp;&nbsp;– <b>According to the types of alcohol, there are two main subgroups:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Neutral fats (Triacylglycerol TAG): They are esters of three fatty acids with glycerol.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Waxes: They are esters of one fatty acid with long chain monohydroxy alcohol higher than glycerol.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Triacylglycerol (Triglyceride):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Glycerol alcohol is liquid and soluble in water.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The fatty acids present in TAG are usually of different types (mixed TAG).<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Triglycerides are classified into:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Oils:</b> They are liquid at room temperature due to their high content of USFA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Solid fats:</b> They are solid at room temperature due to their high content of long chains SFA.", "p": 67}, {"ch": "c8", "f": "03 CLASSIFICATION OF LIPIDS · B COMPOUND (CONJUGATED) LIPIDS", "b": "&nbsp;&nbsp;&nbsp;– They contain fatty acids, alcohol, and other groups.<br>&nbsp;&nbsp;&nbsp;– <b>According to the type of the attached group, They are classified into:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Phospholipids: Containing phosphate group.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Glycolipids: Containing carbohydrate group.<br>• They are classified according to the alcohol present into two main sub-groups:<br>&nbsp;&nbsp;&nbsp;– <b>Glycerophospholipids:</b> Containing glycerol.<br>&nbsp;&nbsp;&nbsp;– <b>Sphingomyelin:</b> Containing sphingol.", "p": 68}, {"ch": "c8", "f": "B COMPOUND (CONJUGATED) LIPIDS · 1 Glycerophospholipids", "b": "• They are phospholipids containing glycerol.<br>• They include phosphatidic acid and its derivatives.<br>&nbsp;&nbsp;&nbsp;1. <b class=\"rd\">Phosphatidic acid (Diacylglycerol phosphate):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is the parent compound of all other glycerophospholipids.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>On hydrolysis It gives:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– One glycerol<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– One saturated FA (At position 1)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– One unsaturated FA (At position 2)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Phosphoric acid (At position 3)<br>&nbsp;&nbsp;&nbsp;2. <b class=\"rd\">Lecithin (Phosphatidylcholine):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is formed of phosphatidic acid and choline.<br>&nbsp;&nbsp;&nbsp;3. <b class=\"rd\">Cephalin (Phosphatidylethanolamine):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Formed of phosphatidic acid and ethanolamine.<br>&nbsp;&nbsp;&nbsp;4. <b class=\"rd\">Phosphatidylinositol:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Formed of phosphatidic acid and inositol.<br>&nbsp;&nbsp;&nbsp;5. <b class=\"rd\">Plasmalogens:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They resemble lecithin and cephalin but contain fatty alcohol instead of fatty acid at position 1 of their phosphatidic acids.", "p": 68}, {"ch": "c8", "f": "1 Glycerophospholipids · Common Functions of Phospholipids", "b": "• Phospholipids are amphipathic molecules that contain non-polar groups of fatty acid side chains and polar groups of glycerol, phosphate, serine, ethanolamine, choline &amp; inositol.<br>• <b>Being amphipathic molecules:</b><br>1. They are good emulsifying factors, that fractionate large fat globules into fine droplets with larger surface area. This is particularly important in digestion and absorption of dietary fats.<br>2. They are good hydrotropic substances, they prevent deposition of cholesterol as cholesterol stones (biliary calculi).<br>3. They are important constituents of plasma lipoproteins.<br>• They provide arachidonic acid and other PUFAs for synthesis of eicosanoids.<br>• They are important constituents of lipid bilayer of cell membranes.", "p": 69}, {"ch": "c8", "f": "1 Glycerophospholipids · Note !!", "b": "• Increased unsaturated fatty acids<b> (USFA)</b> content (at C2 of phospholipids) will increase membrane fluidity, because the<b> kinks</b> of the cis-double bonds prevent the packing of phospholipids closely together.", "p": 69}, {"ch": "c8", "f": "1 Glycerophospholipids · Special Functions of some important Glycerophospholipids (1/2)", "b": "• <b class=\"rd\">1. Cephalin:</b><br>&nbsp;&nbsp;&nbsp;– Increases thrombin formation, thus essential for blood clotting.<br>• <b class=\"rd\">2. Phosphatidylinositol:</b><br>&nbsp;&nbsp;&nbsp;– Acts as second messenger to many chemical transmitters, hormones and growth factors.<br>• <b class=\"rd\">3. Lecithin:</b><br>• It provides choline for synthesis of the neurotransmitter acetylcholine.<br>• <b>Lecithin is important as lung surfactant:</b><br>&nbsp;&nbsp;&nbsp;– Lung surfactant is a naturally secreted material by pneumocytes and is formed mainly of dipalmitoyl-lecithin.<br>&nbsp;&nbsp;&nbsp;– It reduces the tension between air of the alveoli and the alveolar membrane to facilitate trans-membrane passage of O<sub>2</sub>/CO<sub>2</sub>.<br>&nbsp;&nbsp;&nbsp;– Otherwise, the alveolar membrane collapses resulting in respiratory distress syndrome (RDS) which is particularly developed in premature infants.<br>&nbsp;&nbsp;&nbsp;– Lecithin/Sphingomyelin ratio (L/S ratio) is a marker of fetal lung maturity.", "p": 69}, {"ch": "c8", "f": "1 Glycerophospholipids · Special Functions of some important Glycerophospholipids (2/2)", "b": "• <b class=\"rd\">4. Plasmalogens:</b><br>• They provide the platelet activating factor (PAF) that enhances platelet aggregation, thus essential for blood clotting.<br>• They are abundant in the muscles and the nervous system, and their reduced levels have been associated with Alzheimer disease.", "p": 69}, {"ch": "c8", "f": "1 Glycerophospholipids · Hydrolysis of glycerophospholipids", "b": "• They are hydrolyzed by a group of enzymes called phospholipases (PLA1, PLA2, PLC and PLD).<br>• Phospholipase D is not present in humans but present only in plants.", "p": 70}, {"ch": "c8", "f": "1 Glycerophospholipids · Biomedical Correlation", "b": "• Snake venom toxins contain lecithinase enzyme with PLA<sub>2</sub>activity<br>• When injected into blood, it converts phospholipids present in cell membranes of RBCs into lysophospholipids causing cell membrane rupture (Hemolysis).<br>• Therefore, snake venom toxins cause death if not treated with antitoxins", "p": 70}, {"ch": "c8", "f": "B COMPOUND (CONJUGATED) LIPIDS · 2 Sphingomyelin", "b": "• Formed of sphingol (18C amino alcohol) attached to fatty acid and phosphocholine.<br>• <b>Site:</b> cell membranes of the lungs and brain (mainly in the myelin sheath).<br>• They are formed of sphingol, fatty acid and carbohydrate radical (s).<br>• As cerebrosides which are formed of sphingol, FA, and glucose or galactose.<br>• <b class=\"rd\">Importance of glycolipids:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are found mainly in brain tissues, myelin sheath and cell membrane of RBCs.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are components of cell membrane receptors for hormones and other ligands", "p": 70}, {"ch": "c8", "f": "03 CLASSIFICATION OF LIPIDS · C DRIVED LIPID", "b": "&nbsp;&nbsp;&nbsp;– They are products of hydrolysis of either simple or conjugated lipids or associated with lipids in nature.<br>&nbsp;&nbsp;&nbsp;– <b>They include the following:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. Fatty acids<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. Alcohols<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. Steroids<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;4. Fat soluble vitamins: vitamins A, D, E &amp; K (discussed later)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;5. Carotenoids: (Discussed later).<br>• They are compounds containing steroid nucleus.<br>• It is composed of 4 fused rings with 17 carbon atoms.<br>• <b class=\"rd\">Classification of steroids:</b><br>&nbsp;&nbsp;&nbsp;– <b>They include the following groups:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. Sterols<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. Bile acids<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. Steroid hormones", "p": 71}, {"ch": "c8", "f": "C DRIVED LIPID · 1 Sterols", "b": "• Sterols mean solid alcohol.<br>• <b>Cholesterol</b> is the most important sterol in animals.", "p": 71}, {"ch": "c8", "f": "1 Sterols · CHOLESTEROL", "b": "• <b class=\"rd\">Sources:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Exogenous (Dietary):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The richest sources are egg yolk, meat, liver, kidney, butter, and brain.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is the most important animal sterol.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Endogenous:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Every cell, apart from RBCs, can synthesize its own cholesterol (from acetyl CoA).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Plasma cholesterol is synthesized by the liver and intestine.<br>• <b class=\"rd\">Forms:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is present either free (non-esterified) or esterified with fatty acid to form cholesteryl-ester. Free cholesterol contains 27 carbon atoms.<br>• <b class=\"rd\">Plasma level of cholesterol:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Normally it ranges from 120 to 200 mg/dL (Recommended level is &lt; 200 mg/dL).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– About 30% as free cholesterol and 70% as cholesteryl-esters.<br>• <b class=\"rd\">Importance and derivatives of cholesterol:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is an important constituent of cell membranes that controls their fluidity.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is the precursor of all steroid hormones.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is converted to vitamin D<sub>3</sub>under the skin by ultraviolet rays.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is converted into bile acids and bile salts in the liver.", "p": 71}, {"ch": "c8", "f": "C DRIVED LIPID · 2 Steroid Hormones", "b": "• <b class=\"rd\">Sex hormones:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Male sex hormones:</b> e.g., testosterone (C19)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Female sex hormones:</b> e.g., estrogen (C18) and progesterone (C21)<br>• <b class=\"rd\">Corticoids: (C21)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Glucocorticoids:</b> e.g., cortisol<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Mineralocorticoids:</b> e.g., aldosterone", "p": 72}, {"ch": "c8", "f": "04 EICOSANOIDS", "b": "• Eicosanoids are physiologically active compounds formed from polyunsaturated FAs with C20 e.g., arachidonic acid.<br>• Arachidonic acid is liberated from membrane phospholipids by phospholipase A<sub>2</sub>or synthesized from the ω-6 essential fatty acid linoleate.", "p": 72}, {"ch": "c8", "f": "04 EICOSANOIDS · A CLASSIFICATION", "b": "• <b class=\"rd\">Eicosanoids are classified into two main groups:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Cyclic compounds:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– [Prostaglandins (PG), prostacyclins (PGI) and thromboxanes (TX)]<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These are formed from C20 PUFA<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Examples: Arachidonic acid, by action of the enzyme prostaglandin H synthase.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This enzyme has two catalytic activities: cyclooxygenase (COX) and peroxidase.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Acyclic compounds:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– [Leukotrienes (LT) and lipoxins (LX)]<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Formed from C20 PUFA (e.g., arachidonic acid) by action of lipoxygenase.", "p": 72}, {"ch": "c8", "f": "B EFFECTS OF SOME EICOSANOIDS · Biomedical Correlation", "b": "• <b class=\"rd\">Steroidal anti-inflammatory drugs (SAID):</b><br>&nbsp;&nbsp;&nbsp;– They inhibit phospholipase A<sub>2</sub>activity. Thus, decrease availability of arachidonic acid.<br>&nbsp;&nbsp;&nbsp;– <b>For example:</b> hydrocortisone (cortisol).<br>• <b class=\"rd\">Nonsteroidal anti-inflammatory drugs (NSAID):</b><br>&nbsp;&nbsp;&nbsp;– They inhibit cyclooxygenase activity. Thus, inhibit PG synthesis.<br>&nbsp;&nbsp;&nbsp;– They include Aspirin and other NSAIDs (e.g., ibuprofen).<br>&nbsp;&nbsp;&nbsp;– Aspirin produces acetylation of the hydroxyl group of serine at the active site of cyclooxygenase enzyme, explaining the anti-inflammatory and antipyretic actions of aspirin.<br>• <b class=\"rd\">Singulair:</b><br>&nbsp;&nbsp;&nbsp;– It is leukotriene receptor antagonist.<br>&nbsp;&nbsp;&nbsp;– It relieves bronchospasm and inhibits allergic pathway (used to treat severe bronchial asthmatic attacks and allergies).", "p": 73}, {"ch": "c9", "f": "01 NITROGENOUS BASES · A PYRIMIDINES", "b": "• <b class=\"rd\">Major pyrimidines include:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Uracil:</b> Present only in RNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Thymine:</b> Present only in DNA (minor base in tRNA).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Cytosine:</b> Present in both nucleic acids (RNA &amp; DNA).", "p": 75}, {"ch": "c9", "f": "01 NITROGENOUS BASES · B PURINES", "b": "• <b class=\"rd\">Major Purines include:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Adenine &amp; Guanine</b> are the two main purines that present in the structure of RNA &amp;DNA.", "p": 75}, {"ch": "c9", "f": "B PURINES · Oxypurines", "b": "• <b>Hypoxanthine and Xanthine:</b> These are present free or in the form of nucleotides but are rarely present in structure of nucleic acids.<br>• <b>Uric acid:</b> It is end product of purine catabolism &amp; is excreted in urine (see purine catabolism)", "p": 75}, {"ch": "c9", "f": "02 NUCLEOSIDES AND NUCLEOTIDES · A STRUCTURE", "b": "• <b>Each nucleoside</b> is formed of a nitrogenous base and a pentose (Ribose in RNA and deoxyribose in DNA), where C1` of the pentose forms N-linked glycosidic bond with N1 of a pyrimidine or N9 of a purine.<br>• <b>Each nucleotide</b> is formed of a nitrogenous base, pentose, and phosphate<br>• The phosphate group is usually attached by ester bond to the terminal alcohol group of the pentose (Termed 5`hydroxyl group).<br>• Deoxynucleosides or deoxynucleotides contain 2`-deoxyribose as pentose,their name is preceded by the term deoxy (or letter d) e.g., dCMP.", "p": 76}, {"ch": "c9", "f": "02 NUCLEOSIDES AND NUCLEOTIDES · B NOMENCLATURE", "b": "• Nucleosides and nucleotides are named according to their nitrogenous bases", "p": 76}, {"ch": "c9", "f": "C BIOLOGICALIMPORTANCE · 2 EnergyTransduction", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Examples:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Adenosine mono,di and triphosphate (AMP, ADP, ATP)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Guanosine mono,di and triphosphate (GMP, GDP, GTP)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– ATP is used as a source of energy in all mechanical or chemical processes muscular exercise, nerve impulse, cell membrane transport, anabolic reactions, and phosphorylation of compounds).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– When there is a need for energy, ATP is converted to ADP or AMP.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The bonds between α-β and β-γ phosphate groups are high energy bonds (~)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– GTP is also an energy source in some metabolic processes.", "p": 77}, {"ch": "c9", "f": "C BIOLOGICALIMPORTANCE · 3 Signaling Second Messengers", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Examples:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Cyclic 3`,5` Adenosine monophosphate (cAMP)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Cyclic 3`,5` Guanosine monophosphate (cGMP)", "p": 77}, {"ch": "c9", "f": "3 Signaling Second Messengers · cAMP (1/2)", "b": "• It’s is formed from ATP by adenylyl cyclase &amp; it is converted to AMP by phosphodiesterase.<br>• Hormone-receptor interaction produces activation of G proteins, which produce activation of <b>adenylyl cyclase</b>, the latter forms cAMP from ATP.<br>• Cyclic AMP activates protein kinase A → Causes phosphorylationof proteins (e.g enzymes).<br>• Conversion of dephosphorylated enzyme to phosphorylated enzyme causes either its activation e.g., glycogen phosphorylase kinase or its inactivation e.g., glycogen synthase.<br>• <b>Inactive protein kinase</b> is a tetramer formed of<b> 2 regulatory (R)</b> &amp;<b> 2 catalytic subunits (C)</b>.", "p": 77}, {"ch": "c9", "f": "3 Signaling Second Messengers · cAMP (2/2)", "b": "• Binding of 2 molecules of cAMP to each of regulatory subunits causes release of 2 catalytic subunits, which are active and catalyze phosphorylation of its substrate (s) i.e., conversion of dephosphorylated enzyme(s) into phosphorylated enzyme(s).<br>• This process is reversed by a<b> protein phosphatase</b> → Produces enzyme dephosphorylation<br>• Many hormones act through this mechanism e.g.<b> glucagon and epinephrine</b> activate adenylyl cyclase and increase cAMP which in turn inhibits protein phosphatase.<br>• While Insulin activates protein phosphatase and phosphodiesterase enzymes and decreases cAMP level (i.e. reverses the effects of glucagon and epinephrine).", "p": 77}, {"ch": "c9", "f": "3 Signaling Second Messengers · cGMP", "b": "• It is formed from GTP by guanylyl cyclase.<br>• It acts as a second messenger.<br>• Many vasodilators cause smooth muscle relaxation and vasodilation by activating guanylyl cyclase and increasing cGMP e.g., nitric oxide", "p": 78}, {"ch": "c9", "f": "C BIOLOGICALIMPORTANCE · 4 Activated Precursors in Biosynthesis", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">A. S-Adenosyl methionine (Active Methionine) or (SAM)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Active methionine is<b> a nucleoside</b> and is formed in body from methionine&amp;ATP.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is the most important methyl donor in many transmethylation reactions.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">B. 3`phosphoadenosine5-`-phosphosulfate (PAPS)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is used for synthesis of sulfur containing compounds in the body<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– e.g.,sulfate containing GAGs and sulfolipids<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">C. Cytidine diphosphate choline (CDP-choline) ,CDP-ethanolamine or CDP-diacylglycerol</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– R is choline, ethanolamine or diacylglycerol,They are used for phospholipid synthesis.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">D. Uridine diphosphate (UDP)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– R is glucose, galactose, or glucuronic acid.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– UDP-Glc is used for synthesis of glycogen, glycoproteins, andglycolipids.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– UDP-Gal is used for synthesis of lactose, glycoproteins, and glycolipids.", "p": 78}, {"ch": "c9", "f": "C BIOLOGICALIMPORTANCE · 5 Coenzymes Components", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">A. Nicotinamide Adenine Dinucleotide (NAD</b><sup>+</sup><b class=\"rd\">)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">B. Nicotinamide Adenine Dinucleotide Phosphate (NADP</b><sup>+</sup><b class=\"rd\">)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">C. Flavin Mono Nucleotide (FMN not containing adenine)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">D. Flavin Adenine Dinucleotide (FAD)</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Which is an acyl group carrier (R-CO~S-CoA) e.g., acetyl-CoA.", "p": 79}, {"ch": "c9", "f": "5 Coenzymes Components · Biomedical Correlation", "b": "• <b class=\"rd\">Synthetic base analogs</b><br>&nbsp;&nbsp;&nbsp;– They are chemical compounds that are structurally similar to naturally occurring purines and pyrimidines.<br>&nbsp;&nbsp;&nbsp;– They can be incorporated into DNA or RNA during replication or transcription, so they are powerful tool in medicine and molecular biology.<br>&nbsp;&nbsp;&nbsp;– They are used as anti-cancer or anti-viral agents.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Anti-cancer drugs:</b> 6-Mercaptopurine (6-MP) inhibits purine &amp; nucleic acid synthesis.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Antiviral Drugs:</b> Acycloguanosine (Acyclovir) → Inhibits viral DNA synthesis only with no effect on host cells .", "p": 80}, {"ch": "c9", "f": "03 METABOLISM OF PURINES & PYRIMIDINES · A DIETARY PURINES AND PYRIMIDINES", "b": "• They are mainly present in the form of nucleic acids.<br>• Nucleic acids are found mostly in the liver and meat.<br>• Little amounts are present in legumes, cereals, and vegetables.", "p": 80}, {"ch": "c9", "f": "03 METABOLISM OF PURINES & PYRIMIDINES · C FATE", "b": "• Absorbed purines are<b> oxidized</b> (In the liver) to<b> uric acid</b> which is excreted in urine.<br>• Absorbed pyrimidines are catabolized (In the liver) to<b> CO</b><sub>2</sub><b>, NH</b><sub>3</sub><b>, and β-amino acids.</b><br>• Little or no dietary purines or pyrimidines are incorporated into the body’s nucleic acids<br>• Therefore, nucleic acids and nucleotides obtained from the diet are not considered essential, as the human body can synthesize them endogenously.", "p": 80}, {"ch": "c9", "f": "BIOSYNTHESIS OF PURINE NUCLEOTIDES · A DE NOVO SYNTHESIS", "b": "• In de novo synthesis, the purine ring is synthesized stepwise from simple precursor molecules on a ribose phosphate backbone to form inosine monophosphate (IMP), the precursor of AMP and GMP.<br>• <b class=\"rd\">Main Steps of De Novo Synthesis:</b>", "p": 81}, {"ch": "c9", "f": "A DE NOVO SYNTHESIS · 1 Synthesis of -5phosphoribosyl-1-pyrophosphate (PRPP)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– PRPP is the activated form of ribose phosphate and is an essential precursor in purine and pyrimidine synthesis.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is synthesized from ribose-5-phosphate, which is produced through the hexose monophosphate pathway (Pathway of glucose oxidation).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This reaction is catalyzed by<b> PRPP synthetase enzyme.</b>", "p": 81}, {"ch": "c9", "f": "A DE NOVO SYNTHESIS · 2 Synthesis of phosphoribosylamine", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– N<sub>9</sub>of the purine ring is provided by the amide group of glutamine forming 5-phosphoribosylamine.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This reaction is catalyzed by an enzyme termed<b> glutamine: PRPP amidotransferase.</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This is the key step in de novo purine nucleotide synthesis.", "p": 81}, {"ch": "c9", "f": "A DE NOVO SYNTHESIS · 3 Synthesis of Inosine monophosphate (IMP)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is formed by the addition of different atoms to the NH<sub>2</sub>group of phosphoribosylamine using specific intermediates or precursors till the first purine is formed by ring closure which is inosine-monophosphate (IMP).", "p": 81}, {"ch": "c9", "f": "3 Synthesis of Inosine monophosphate (IMP) · Note !!", "b": "• Folic acid is important in the biosynthesis of purines (C-2 and C-8).<br>• Thus, folate antagonists (e.g., methotrexate) inhibit purine and nucleic acid synthesis, leading to inhibition of cell division, and hence their use in the treatment of some cancers.", "p": 81}, {"ch": "c9", "f": "A DE NOVO SYNTHESIS · 4 Conversion of IMP AMP and GMP", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>IMP acts as a precursor of other purine nucleotides:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– IMP → XMP → GMP<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– IMP → Adenylosuccinate → AMP", "p": 82}, {"ch": "c9", "f": "A DE NOVO SYNTHESIS · 6 Synthesis of Deoxyribonucleotides", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This is catalyzed by an enzyme complex termed<b> ribonucleotide reductase</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– which is active only during DNA synthesis and<b> inhibited mainly by dATP</b>.", "p": 82}, {"ch": "c9", "f": "BIOSYNTHESIS OF PURINE NUCLEOTIDES · B PURINE SALVAGE SYSTEM", "b": "• The significance of the purine salvage system is<b> to supply purine nucleotides to tissues</b> <b>where the de novo synthesis is not active</b> e.g., brain and precursors of red blood cells.<br>• <b class=\"rd\">There are 2 systems for purine salvage:</b>", "p": 82}, {"ch": "c9", "f": "C REGULATION OF BIOSYNTHESIS OF PURINE NUCLEOTIDES · 1 Feedback regulation", "b": "&nbsp;&nbsp;&nbsp;– De novo purine nucleotide synthesis is a good example for multiple loops feedback inhibition.<br>&nbsp;&nbsp;&nbsp;– High concentration of IMP, AMP, ADP, GMP and GDP produce<b> feedback inhibition of</b> <b>conversion of ribose-5-phosphate to IMP at two sites:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– PRPP synthetase<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Glutamine:PRPP- amidotransferase.", "p": 82}, {"ch": "c9", "f": "C REGULATION OF BIOSYNTHESIS OF PURINE NUCLEOTIDES · 2 Availability of the substrates", "b": "&nbsp;&nbsp;&nbsp;– The rate of the reaction catalyzed by glutamine: PRPP-amidotransferase is controlled by the intracellular concentration of PRPP and glutamine.", "p": 82}, {"ch": "c9", "f": "03 METABOLISM OF PURINES & PYRIMIDINES · CATABOLISM OF PURINE NUCLEOTIDES", "b": "• Purine nucleotides are degraded through a series of enzymatic reactions to form uric acid<br>• Uric acid the end product of purine catabolism in humans<b>.</b><br>• Uric acid is the main end product of purine catabolism in the human liver.<br>• Plasma uric acid (Urate) levels are 4-7 mg/dL for males &amp; 3-6 mg/dL for females during fasting.<br>• <b>Excretion of Uric acid:</b><br>&nbsp;&nbsp;&nbsp;– In normal adult humans, the daily excretion of uric acid is about 400-600 mg.<br>&nbsp;&nbsp;&nbsp;– Urate salts are more soluble than uric acid.<br>&nbsp;&nbsp;&nbsp;– So, the pH of urine influences the solubility of uric acid e.g., urine at pH 5 can dissolve only about one-tenth as much as urine at pH 7.<br>• Therefore, alkalization of urine markedly increases solubility of uric acid &amp; promotes its excretion.", "p": 83}, {"ch": "c9", "f": "03 METABOLISM OF PURINES & PYRIMIDINES · I. Hyperuricemia", "b": "• Hyperuricemia or elevated serum urate levels results from over production (metabolic) or decreased excretion (Renal).", "p": 83}, {"ch": "c9", "f": "A CAUSES OF GOUT · 1 Increased Production of uric acid", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">1. Dietary causes:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Excess intake of nucleoprotein rich diet (cellular proteins) e.g., meat, liver &amp; kidney.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">2. Metabolic Gout:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Primary Metabolic Gout:</b> This is due to genetic disorders as follows:<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Defects of PRPP synthetase: Due to genetic mutation, the enzyme is either superactive or resistant to feedback inhibition.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Partial deficiency of HGPRTase of purine salvage system.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Lesch-Nyhan Syndrome: Complete deficiency of HGPRTase.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Von Gierke’s disease (Glucose 6-phosphatase deficiency) due to enhanced synthesis &amp; degradation of purine &amp; decreased excretion of uric acid<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Secondary Metabolic Gout:</b> It is due to diseases which cause increase in purine catabolism e.g., cancer, leukemia, and psoriasis.", "p": 84}, {"ch": "c9", "f": "A CAUSES OF GOUT · 2 Decreased Excretion of uric acid (Renal Gout)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Primary Renal Gout:</b> It is due to primary or congenital renal disease.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Secondary Renal Gout:</b> It is due to acquired renal disease.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Alcohol intake:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Alcohol metabolism increases lactate production, resulting in lactic acidosis.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Lactate competes with uric acid for renal tubular secretion.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Because lactate is present in higher concentration, it reduces uric acid excretion leading to hyperuricemia and gout.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– In addition, alcohol intake causes dehydration → Decreases uric acid excretion.", "p": 84}, {"ch": "c9", "f": "B TREATMENT OF GOUT · 1 Diet", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Restriction of nucleoprotein rich diet</b> (Cellular proteins) e.g., meat, liver and kidney, the best are non-cellular proteins as milk and its products.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Maintaining adequate fluid intake</b> helps to decrease the risk of kidney stone formation.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Avoid alcohol intake.</b>", "p": 84}, {"ch": "c9", "f": "B TREATMENT OF GOUT · 2 Drugs", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">1. Anti-inflammatory agents:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are used to decrease joint inflammation and to relief pain.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">2. Drugs decreasing the production of uric acid:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Allopurinol is the drug of choice:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It competitively inhibits xanthine oxidase as it has a structural similarity to hypoxanthine (see competitive enzyme inhibitors).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Allopurinol is oxidized by xanthine oxidase to oxypurinol.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The latter binds tightly to xanthine oxidase, inhibiting its ability to oxidize hypoxanthine and xanthine and decreases uric acid formation.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Also, the reaction of allopurinol with PRPP results in a decrease in PRPP levels and thus decreases de novo purine synthesis.", "p": 84}, {"ch": "c9", "f": "03 METABOLISM OF PURINES & PYRIMIDINES · II. Hypouricemia", "b": "• It is caused mainly by adenosine deaminase (ADA) deficiency.<br>• The high levels of dATP inhibit ribonucleotide reductase, which inhibits DNA synthesis.<br>• Therefore, white blood cells can’t proliferate resulting in impairment of T-cell &amp; B-cell functions.<br>• The main end products of pyrimidine catabolism are<b> CO</b><sub>2</sub><b>, NH</b><sub>3</sub><b>, β-alanine</b> (uracil&amp; cytosine) or <b>β-aminoisobutyrate</b> (thymine) which are highly water soluble and easily excreted.", "p": 85}, {"ch": "c10", "f": "01 INTRODUCTION TO NUCLEIC ACIDS AND GENETIC STRUCTURE", "b": "• <b>Nucleic acids</b> are polymers of nucleotides.<br>• <b>There are 2 main types of nucleic acids:</b> Deoxyribonucleic acid (DNA) &amp; Ribonucleic acid (RNA).<br>• Responsible mainly for storage &amp; transfer of information needed for production of proteins.", "p": 87}, {"ch": "c10", "f": "02 DEOXYRIBONUCLEIC ACID (DNA)", "b": "• It consists of two strands of polynucleotides<br>• <b class=\"rd\">It has the following primary, secondary, and tertiary structures:</b>", "p": 87}, {"ch": "c10", "f": "02 DEOXYRIBONUCLEIC ACID (DNA) · A DNA PRIMARY STRUCTURE (1/2)", "b": "• <b>The nucleotides that form DNA primary structure are mainly 4:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– dAMP,dGMP,dCMP&amp; dTMP.<br>• <b>In each strand, nucleotides are linked together by phosphodiester bonds between:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The 3`-hydroxyl group of the pentose sugar of one nucleotide<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The 5`-hydroxyl group of the pentose sugar of the next nucleotide<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Joind through a phosphate group.<br>• This forms an alternating sugar phosphate backbone of each DNA strand (5`-P-S-P-S3-`).<br>• The nitrogenous bases, which are linked to the pentoses, are projecting to the inside of the two strands of DNA at right angles.<br>• The sequence of bases determines the coding structure of DNA (Genetic information).<br>• Each polynucleotide strand has two terminals.", "p": 87}, {"ch": "c10", "f": "02 DEOXYRIBONUCLEIC ACID (DNA) · A DNA PRIMARY STRUCTURE (2/2)", "b": "• One end has a free phosphate group attached to the 5`-hydroxyl group of the first pentose and the other end has a free 3`- hydroxyl group of the terminal pentose.<br>• The order of nucleotides in any DNA strand is always written in the 5` to 3`direction which is the direction of synthesis, e.g., AGCT in the figure below.", "p": 87}, {"ch": "c10", "f": "02 DEOXYRIBONUCLEIC ACID (DNA) · B DNA SECONDARY STRUCTURE, DOUBLE HELIX (dsDNA)", "b": "• Watson and Crick proposed a structure for DNA in the form of a double helix.<br>• <b class=\"rd\">It has the following characteristics:</b>", "p": 88}, {"ch": "c10", "f": "B DNA SECONDARY STRUCTURE, DOUBLE HELIX (dsDNA) · 1 Two antiparallel strands form a right-handed double helix", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The two strands of DNA run antiparallel and are paired to each other and coil around a common axis to form a right-handed helix (see figure).", "p": 88}, {"ch": "c10", "f": "B DNA SECONDARY STRUCTURE, DOUBLE HELIX (dsDNA) · 2 Complementary base pairing", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The two strands are held together by complementary base pairing through specific hydrogen bonds.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Adenine pairs with thymine through two hydrogen bonds, and guanine pairs with cytosine through three hydrogen bonds.", "p": 88}, {"ch": "c10", "f": "B DNA SECONDARY STRUCTURE, DOUBLE HELIX (dsDNA) · 3 Base stacking", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The base pairs inside the helix are stacked above each other by<b> Van der Waals</b> forces and<b> hydrophobic interactions</b>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These forces provide thestability of the double helix.", "p": 88}, {"ch": "c10", "f": "B DNA SECONDARY STRUCTURE, DOUBLE HELIX (dsDNA) · 4 Spiral staircase", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The double helix of DNA appears much like spiral staircase, in which base pairs form the steps and the phosphate sugar backbones form thehandrails.", "p": 88}, {"ch": "c10", "f": "B DNA SECONDARY STRUCTURE, DOUBLE HELIX (dsDNA) · 5 Dimensions", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The DNA is<b> 2 nm in width</b>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– From outside of helix, 2 grooves are apparent,<b> a major groove (2.2 nm in length)</b> and<b> a minor groove (1.2nm in length)</b>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Through these grooves many drugs and proteins can contact the nitrogenous bases without any need to open the helix.", "p": 88}, {"ch": "c10", "f": "5 Dimensions · Denaturation of DNA", "b": "• Heating DNA produces rupture of hydrogen bondsand separation of the two strands of DNA or<b> DNA denaturation</b>.<br>• Cooling of denatured DNA results in reformation of the double helix or<b> renaturation or reannealing</b><br>• Denaturation of DNA is the first step in the in-vitro amplification technique<b> “Polymerase Reaction (PCR)”.</b>", "p": 89}, {"ch": "c10", "f": "02 DEOXYRIBONUCLEIC ACID (DNA) · C DNA TERTIARY STRUCTURES", "b": "• The length of human DNA per cell is approximately 2 meters, and the diameter of the nucleus is 10 microns.<br>• Supercoiling of DNA is important for its packing within the small nucleus.<br>• Each DNA molecule is condensed into a compact structure about 10 μm long and 1 μm in diameter through differentlevels of supercoiling<br>• special proteins.<br>• The protein/DNA complex is called chromatin<br>• <b class=\"rd\">Each chromatid contains:</b>", "p": 89}, {"ch": "c10", "f": "C DNA TERTIARY STRUCTURES · 2 Histone proteins", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are basic proteins rich in<b> lysine</b> and<b> arginine</b> (Positively charged), that are united to DNA which is acidic (Negatively charged due to the presence of phosphate groups).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Five major types of histones<b> (H1, H2A, H2B, H3 and H4)</b> are present in eukaryotic chromosomes.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They interact with the minor grooves of DNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The main function of the histone proteins is to condense the DNA intostructural units called<b> “Nucleosomes”.</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Each nucleosome is formed of eight histones<b> (Histone octamer or histone core)</b>, i.e., two copies of each of H2A, H2B, H3 and H4.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Around the histone octamer, one and three quarters of<b> supercoiled DNA</b> segment is wrapped (Contains an average of 140 bp).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Linker or spacer DNA (Contains an average of 60 bp) connects different nucleosomes.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>H1</b> is attached to linker DNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Connection of nucleosomes by linker DNA makes chromatin looks like beads on a string.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Nucleosomes are further arranged into<b> more complex structures</b> that organize and condense the long DNA molecule into chromatids.", "p": 89}, {"ch": "c10", "f": "C DNA TERTIARY STRUCTURES · 3 Non-histone proteins", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They interact with the major grooves.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They share in the packing of DNA and are important for regulation of gene expression and involved in replication and transcription.", "p": 90}, {"ch": "c10", "f": "3 Non-histone proteins · Mitochondrial DNA (mt-DNA)", "b": "• DNA is mainly<b> linear</b> but sometimes it is<b> circular</b> as in DNA of mitochondria,chloroplasts (In plants) and bacteria.<br>• Mitochondrial DNA represents<b> 0.3 to 1% of the total cellular DNA</b>.<br>• Human mt-DNA is present in the form of a small double stranded circular supercoil.<br>• It is responsible for controlling synthesis of<b> 2 rRNA, 22 tRNA and 13 proteins</b>, most of these mitochondrial proteins are involved in oxidative phosphorylation (Electron transport chain and ATP synthesis).<br>• Mitochondria are provided by the ovum, thus mt-DNA molecules are<b> maternally inherited</b> and are used as maternal lineage.<br>• Mutations of mt-DNA are associated with certain types of<b> myopathies.</b>", "p": 90}, {"ch": "c10", "f": "03 RIBONUCLEIC ACID (RNA)", "b": "• <b>There are three major types of RNAs that participate in the process of protein synthesis:</b><br>&nbsp;&nbsp;&nbsp;– Ribosomal RNA (rRNA)<br>&nbsp;&nbsp;&nbsp;– Transfer RNA (tRNA)<br>&nbsp;&nbsp;&nbsp;– Messenger RNA (mRNA)", "p": 90}, {"ch": "c10", "f": "03 RIBONUCLEIC ACID (RNA) · A TRANSFER RNAs(tRNAs)", "b": "&nbsp;&nbsp;&nbsp;– RNAs represent about 15% of the total RNA in the cell.<br>&nbsp;&nbsp;&nbsp;– Each tRNA serves as a carrier to its specific amino acid during translation.<br>&nbsp;&nbsp;&nbsp;– There is at least one specific type of tRNA molecule for each of the twenty amino acids commonly found in proteins.<br>&nbsp;&nbsp;&nbsp;– tRNA molecule is a single strand folded to form a cloverleaf appearancestabilized by hydrogen bonds.<br>• <b class=\"rd\">tRNA molecule has 4 main arms and one extra arm:</b>", "p": 90}, {"ch": "c10", "f": "A TRANSFER RNAs(tRNAs) · 1 The acceptor arm", "b": "&nbsp;&nbsp;&nbsp;– It terminates at its 3` OH end by a specific sequence formed of CCA.<br>&nbsp;&nbsp;&nbsp;– Amino acids are carried in the form of aminoacyl group connected to the 3`-hydroxyl group of the acceptor arm.", "p": 91}, {"ch": "c10", "f": "A TRANSFER RNAs(tRNAs) · 2 D-arm", "b": "&nbsp;&nbsp;&nbsp;– Contains an unusual base<b> dihydrouracil</b>.<br>&nbsp;&nbsp;&nbsp;– D-arm is important for recognition of tRNA by aminoacyl-tRNA synthetase enzyme which catalyzes the binding of a specific amino acid to its specific tRNA", "p": 91}, {"ch": "c10", "f": "A TRANSFER RNAs(tRNAs) · 3 Anticodon arm", "b": "&nbsp;&nbsp;&nbsp;– Contains 3 specific bases known as anticodon.<br>&nbsp;&nbsp;&nbsp;– This portion of tRNA plays a key role in translation<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– by pairing with complementary codon of mRNA.", "p": 91}, {"ch": "c10", "f": "A TRANSFER RNAs(tRNAs) · 4 Ψ", "b": "&nbsp;&nbsp;&nbsp;– Contains the unusual specific sequence of thymine and pseudouridine bases.<br>&nbsp;&nbsp;&nbsp;– This arm is important for binding tRNA to ribosome during the process of protein synthesis.", "p": 91}, {"ch": "c10", "f": "A TRANSFER RNAs(tRNAs) · 5 Extra arm", "b": "&nbsp;&nbsp;&nbsp;– Contains from 3 to 12 bases (with no base pairing) &amp; the major site for variation in tRNA", "p": 91}, {"ch": "c10", "f": "03 RIBONUCLEIC ACID (RNA) · B MESSENGER RNAs (mRNAs) (1/2)", "b": "• Messenger RNAs represent only about 5% of the RNA in the cell.<br>• The coding region of mRNA carries genetic information from nuclear DNA to the cytosol, where it is used as the template for protein synthesis (Each 3 bases or codon, designate an amino acid).<br>• <b>The coding region</b> of mRNA starts with a specific initiation codon and ends with a specific termination codon.<br>• <b>Untranslated regions (UTRs)</b> are sections of the mRNA before the initiationcodon and after the termination codon that are not translated, termed the five prime untranslated regions <b>(5’ UTRs)</b> and the three prime untranslated regions<b> (3’ UTRs)</b>, respectively.<br>• These regions are transcribed with coding region &amp; they are present in the mature mRNA.", "p": 91}, {"ch": "c10", "f": "03 RIBONUCLEIC ACID (RNA) · B MESSENGER RNAs (mRNAs) (2/2)", "b": "• Several functionsin gene expression have been attributed to the untranslated regions, including<b> mRNA stability, translational efficiency and regulation of gene expression.</b>", "p": 91}, {"ch": "c10", "f": "03 RIBONUCLEIC ACID (RNA) · C RIBOSOMAL RNAs (rRNAs)", "b": "• The rRNAs represent about<b> 80%</b> of the total RNA of the cell.<br>• They are found in association with several proteins as components of theribosomes and serve as the<b> sites for</b> <b>protein synthesis.</b><br>• The fully active 80S ribosomes are formed mainly of two main nucleoprotein subunits of unequal size, the<b> 60S</b> <b>subunit</b> and the<b> 40S subunit.</b><br>• <b>The Svedberg unit</b> (Sedimentation or Sunit) is a measure of the sedimentation velocity by high-speed centrifuge, which depends on the molecular weight as well as the size of the particles i.e., particle density.", "p": 92}, {"ch": "c10", "f": "03 RIBONUCLEIC ACID (RNA) · D OTHER FORMS OF RNAs (NON-CODING RNAs)", "b": "• <b class=\"rd\">Required for regulation of transcription &amp; translation</b>", "p": 92}, {"ch": "c10", "f": "D OTHER FORMS OF RNAs (NON-CODING RNAs) · 1 Nuclear non-coding RNAs", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Small nuclear RNAs (snRNAs):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Involved in mRNA processing as components of spliceosomes (See transcription)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Small nucleolar RNAs (snoRNAs):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They modify rRNAs to ensure proper ribosome assembly during protein synthesis", "p": 92}, {"ch": "c10", "f": "D OTHER FORMS OF RNAs (NON-CODING RNAs) · 2 Regulatory non-coding RNAs", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Including many types, some of which are:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>MicroRNAs (miRNAs):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They have important role in regulating gene expression by many mechanisms, mainly by targeting mRNA molecules and degrading them.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Circular RNA (circRNA):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are present in the form of closed loop molecules that act as miRNA sponges (i.e. they bind to miRNAs, preventing them from targeting mRNA, thus acting as inhibitors).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>long non-coding RNAs (lncRNAs):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Important in epigenetic regulationgene expression (See later).", "p": 92}, {"ch": "c10", "f": "04 GENETIC TERMINOLOGY · A GENES", "b": "• A gene is an element of heredity, transmitted from parents to offspring in reproduction.<br>• Chemically, a gene is a sequence of nucleotides along a DNA molecule.<br>• Most eukaryotic genes are discontinuous i.e., coding sequences<b> (Exons)</b> separated by noncoding sequences<b> (Introns).</b><br>• Coding sequences are unique &amp; non-repetitive while noncoding sequences are repetitive.", "p": 93}, {"ch": "c10", "f": "04 GENETIC TERMINOLOGY · B CHROMOSOME", "b": "• A thread-like structure of DNA and proteins found in the nucleus of most living cells<br>• Carry genetic information in the form of genes<br>• Divides longitudinally during cell division into two chromatids.", "p": 93}, {"ch": "c10", "f": "04 GENETIC TERMINOLOGY · C GENOME", "b": "• It is the total genetic information presented by the group of chromosomes in any cell.", "p": 93}, {"ch": "c10", "f": "04 GENETIC TERMINOLOGY · D GENOTYPE", "b": "• If the two genes<b> (Alleles)</b> in an individual are similar, the genotype is<b> homozygous</b> for these genes, if 2 genes are different from each other, the genotype is said to be<b> heterozygous.</b>", "p": 93}, {"ch": "c10", "f": "04 GENETIC TERMINOLOGY · E PHENOTYPE", "b": "• It is the outside or the observable traits depending on the genotype of the individual.", "p": 93}, {"ch": "c11", "f": "01 INTRODUCTION TO DNA REPLICATION", "b": "• <b>Central dogma of molecular biology:</b><br>– It is the process in which genetic information flows from DNA to RNA, to make a functional product protein.<br>• <b>DNA replication</b> is the process by which a double strand DNA molecule is copied to produce two identical daughter DNA molecules catalyzed mainly by DNA polymerases.<br>• Each parental strand of the DNA molecule acts as a template for the formation of a complementary new DNA strand.<br>• Therefore, each of the daughter DNA molecules is composed of one original (conserved) strand and one newly synthesized strand → This is called<span class=\"rn\"> semi-conservative replication.</span><br>• The major function of replication is<b> “Genetic continuity”</b>, i.e. ensuring that daughter cells receive identical genetic material during cell division.", "p": 95}, {"ch": "c11", "f": "A SEPARATION OF THE TWO DNA STRANDS · 1 Opening of DNA at multiple Origins of replication", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Many origins across the chromosomes (rich in AT base pairs) serve as starting points for replication.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are recognized by origin recognition complex (ORC) proteins.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– ORC proteins bind to the replication origins &amp; produce local opening &amp; unwinding of DNA double helix.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Presence of multiple replication origins markedly decreases time needed for replication.", "p": 95}, {"ch": "c11", "f": "A SEPARATION OF THE TWO DNA STRANDS · 2 Formation of Two Replication Forks in each replication origin", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Helicase</b> enzyme molecules are attached to each origin and unwind the DNA by breaking the hydrogen bonds between the nitrogenous base pairs forming <span class=\"rn\">“Replication bubbles”</span>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Single strand binding (SSB) proteins:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They bind to the single strands of unwound parts of DNA &amp; stabilize the single strands.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– In the absence of SSB proteins, the two strands can rewind again.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Also, they protect single strand from nucleases that cleave single strand DNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– By the action of helicase and SSB proteins, a replication fork is created.", "p": 96}, {"ch": "c11", "f": "02 STEPS OF EUKARYOTIC REPLICATION · B INITIATION OF DNA SYNTHESIS: FORMATION OF RNA PRIMERS", "b": "• At the replication fork, both strands of parental DNA serve as templates for DNA synthesis.<br>• DNA polymerases cannot initiate DNA synthesis without the presence of RNA primers.<br>• <b>RNA primers</b> are short segments of RNA used as a binding sites for DNA polymerase.<br>• <b>They are formed by the action of:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– DNA polymerase α-primase complex &amp; base-paired to the parental strand.<br>• The 5`- end of the primer is attached to the 3’- end of the parental strand, and the 3`- end of the primer will accept the first deoxynucleotide.", "p": 96}, {"ch": "c11", "f": "02 STEPS OF EUKARYOTIC REPLICATION · C ELONGATION (SYNTHESIS OF DNA LEADING AND LAGGING STRANDS)", "b": "• <b>DNA polymerases</b> are template-directed enzymes<br>• They are only able to read the parental nucleotide sequence in 3` to 5` direction<br>• Thus synthesize the new strands in 5` to 3` direction.<br>• <b>DNA polymerases</b> catalyze the formation of polynucleotide chains through the addition of free deoxy-ribonucleoside triphosphates &amp; the removal of pyrophosphates forming phosphodiester bonds.<br>• Hydrogen bonds are then formed with complementary nucleotides on parental strands.", "p": 96}, {"ch": "c11", "f": "C ELONGATION (SYNTHESIS OF DNA LEADING AND LAGGING STRANDS) · 1 Synthesis of the leading strand", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>DNA polymerase ε</b> synthesizes the leading strand of DNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Only one RNA primer is required by DNA polymerase ε.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The leading strand is copied in the direction of the advancing replication fork.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The leading strand is synthesized in a continuous manner in the 5` to 3` direction.", "p": 96}, {"ch": "c11", "f": "C ELONGATION (SYNTHESIS OF DNA LEADING AND LAGGING STRANDS) · 2 Synthesis of the lagging strand", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– DNA-polymerase δ synthesizes the lagging strand of DNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Multiple RNA primers are required by DNA polymerase δ.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The lagging strand is copied in the opposite direction of the advancing replication fork.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The lagging strand is synthesized discontinuously in the form of short Okazaki fragments that are produced in a 5` to 3` direction.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The length of these Okazaki fragments ranges from 100 to 200 bases.", "p": 96}, {"ch": "c11", "f": "C ELONGATION (SYNTHESIS OF DNA LEADING AND LAGGING STRANDS) · 3 Proofreading of newly synthesized DNA strands", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Misreading of the template sequence may result in permanent mutations.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– To avoid this, polymerases ε and δ have proof-reading activity.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They remove the misplaced nucleotide (act as exonuclease) &amp; replace it with the correct nucleotide.", "p": 97}, {"ch": "c11", "f": "C ELONGATION (SYNTHESIS OF DNA LEADING AND LAGGING STRANDS) · 4 Removal of DNA supercoiling", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– When DNA unwinds, supercoils are formed during DNA replication.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are removed by DNA topoisomerases.", "p": 97}, {"ch": "c11", "f": "D TERMINATION: REMOVAL OF PRIMERS AND JOINING OF FRAGMENTS · 1 Synthesis of the leading strand", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– RNase H removes the RNA primers by its exonuclease activity.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– DNA polymerase δ fills the gaps between Okazaki fragments.", "p": 97}, {"ch": "c11", "f": "D TERMINATION: REMOVAL OF PRIMERS AND JOINING OF FRAGMENTS · 2 Joining of DNA fragments", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– DNA ligase joins the ends of adjacent fragments using ATP.", "p": 97}, {"ch": "c11", "f": "03 PRESERVATION OF CHROMOSOMAL ENDS BY TELOMERES", "b": "• The ends of the eukaryotic linear chromosomes are called<b> telomeres</b>.<br>• The 3`end strand of the telomere contains a non-coding region with specific sequence (5`-TTAGGG3-`) that is repeated thousands of times.<br>• The 3`end strand is longer than the complementary 5`end strand by a few hundred nucleotides.<br>• This part of the 3`end single strand is folded back on itself forming<b> a loop like structure</b> stabilized by protein.<br>• This loop structure<b> prevents the stacking</b> of chromosomes.<br>• <b>Also, Protects the ends</b> of chromosomes from being attacked &amp; hydrolyzed by nuclease enzymes.<br>• <b>During the process of replication,</b> the leading strand can be synthesized to the end of the parent strand<b> while the lagging strand cannot because:</b><br>&nbsp;&nbsp;&nbsp;– Primase cannot act at the 3`end of the strand due to the narrow space.<br>&nbsp;&nbsp;&nbsp;– If primase acts, the removal of the RNA primer would leave a short gap<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– As a result, telomeres shorten with each cell division.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– If shortening continues → Affect important genes → Cells stop dividing &amp; undergo aging.", "p": 97}, {"ch": "c11", "f": "03 PRESERVATION OF CHROMOSOMAL ENDS BY TELOMERES · A ROLE OF TELOMERASE IN RESTORATION OF TELOMERES", "b": "&nbsp;&nbsp;&nbsp;– Telomerase is an enzyme with reverse transcriptase activity.<br>&nbsp;&nbsp;&nbsp;– <b>A reverse transcriptase</b> synthesizes DNA from RNA.<br>&nbsp;&nbsp;&nbsp;– Telomerase also contains a short internal RNA template complementary to the DNA sequence on 3` end strand of the telomere.<br>&nbsp;&nbsp;&nbsp;– Telomerase recognizes and binds to the single-strand 3` terminus.<br>&nbsp;&nbsp;&nbsp;– It elongates the 3`end by synthesizing DNA complementary to its internal RNA template.<br>&nbsp;&nbsp;&nbsp;– Telomerase repeats the process of elongation till the length of the 3` strand becomes suitable (about 100 nucleotides)<br>&nbsp;&nbsp;&nbsp;– <b>It allows,</b> Binding of a primer &amp; the completion of synthesis of lagging DNA strand till end.", "p": 98}, {"ch": "c11", "f": "04 SUMMARY OF ENZYMES REQUIRED FOR EUKARYOTIC REPLICATION", "b": "• <b class=\"rd\">DNA helicases:</b> for unwinding and separation of the two DNA strands.<br>• <b class=\"rd\">DNA polymerases:</b><br>&nbsp;&nbsp;&nbsp;– <b>DNA polymerase α-primase complex:</b> for synthesis of RNA primers &amp; short DNA connected to the RNA primers.<br>&nbsp;&nbsp;&nbsp;– <b>DNA polymerase β:</b> for DNA repair.<br>&nbsp;&nbsp;&nbsp;– <b>DNA polymerase γ:</b> for mitochondrial DNA synthesis.<br>&nbsp;&nbsp;&nbsp;– <b>DNA polymerase δ:</b> for synthesis of the lagging strand.<br>&nbsp;&nbsp;&nbsp;– <b>DNA polymerase ε:</b> for synthesis of the leading strand.<br>• <b class=\"rd\">Topoisomerases:</b> for removal of supercoils formed during DNA replication.<br>• <b class=\"rd\">RNase H:</b> for removal of RNA primers.<br>• <b class=\"rd\">DNA ligase:</b> to join the ends of adjacent DNA segments (ATP is required).<br>• <b class=\"rd\">Telomerase:</b> for elongation of the 3`- end of telomeres of DNA.", "p": 99}, {"ch": "c11", "f": "05 DNA REPAIR", "b": "• Replication process takes place at high accuracy, but an error can occur forevery 30,000bases.<br>• DNA is constantly subjected to environmental factors e.g., radiation and chemicals, that cause alteration or removal of nucleotide bases.<br>• Bases are also altered or lost spontaneously or during replication.<br>• If damage is not repaired, a permanent mutation occurs → May result in a hereditary disorder.<br>• <b class=\"rd\">The broad steps of repair are as follows:</b>", "p": 100}, {"ch": "c11", "f": "05 DNA REPAIR · 1 Recognition of the lesion", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This is the function of an<b> endonuclease</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It cleaves damaged strand to form a cut (Nick).", "p": 100}, {"ch": "c11", "f": "05 DNA REPAIR · 2 Excision of damaged DNA", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The damaged part is removed by an<b> exonuclease</b>.", "p": 100}, {"ch": "c11", "f": "05 DNA REPAIR · 3 Filling the gap", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This is catalyzed by a repair<b> DNA polymerase β</b>.", "p": 100}, {"ch": "c11", "f": "05 DNA REPAIR · 4 Ligation", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This is catalyzed by<b> DNA ligase</b>.", "p": 100}, {"ch": "c12", "f": "01 INTRODUCTION TO GENE EXPRESSION", "b": "• <b>Gene expression</b> is the process by which the information contained within a gene becomes a functional product (RNA or protein).<br>• It generally happens in two main steps: Transcription and translation.", "p": 102}, {"ch": "c12", "f": "02 RNA SYNTHESIS (TRANSCRIPTION)", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Synthesis of RNA from DNA is known as transcription.</b>", "p": 102}, {"ch": "c12", "f": "02 RNA SYNTHESIS (TRANSCRIPTION) · A PRINCIPLES OF TRANSCRIPTION AND TERMINOLOGY (1/2)", "b": "• Only one strand of DNA is transcribed.<br>• The strand of DNA that is transcribed into RNA is known as the<b> template strand</b> whereas the other strand is known as the<b> coding strand</b>.<br>• The sequence of RNA is complementary to the sequence of template strand, and it is the same as that of coding strand except for U replacing T.<br>• <b>RNA synthesis includes four main phases:</b> Preinitiation, Initiation, Elongation &amp; Termination.<br>• <b>Start site:</b> The first nucleotide at the 3’ end of the transcription region of the template strand is designated as +1.<br>• <b>Upstream:</b> The 3’ direction of the template strand before the start site (+1) takes negative numbers -1 ,-2 ,-3 …. etc.<br>• <b>Downstream:</b> The5’direction of the template strand afterthestartsite(+1) takes positive numbers", "p": 102}, {"ch": "c12", "f": "02 RNA SYNTHESIS (TRANSCRIPTION) · A PRINCIPLES OF TRANSCRIPTION AND TERMINOLOGY (2/2)", "b": "• <b>Promoter:</b> The nucleotide sequence in the template strand at which the RNA polymerase begins attachment. It lies upstream the transcription region and marks the beginning.<br>• <b>Terminator:</b> The nucleotide sequence in the template strand lies downstream the transcription region and marks the end.<br>• <b>Transcription region:</b> The nucleotide sequence transcribed by RNA polymerase.<br>• <b>Transcription unit:</b> It includes the promoter, the transcription region, and the terminator.<br>• <b>The basic mechanism of RNA synthesis is the same for all types of RNAs:</b><br>&nbsp;&nbsp;&nbsp;– Messenger (mRNAs), ribosomal (rRNAs) and transfer (tRNAs).<br>• The synthesis of RNA is catalysed by a group of enzymes termed RNA polymerases.", "p": 102}, {"ch": "c12", "f": "02 RNA SYNTHESIS (TRANSCRIPTION) · A TYPES OF RNA POLYMERASES", "b": "• <b class=\"rd\">There are three types of nuclear RNA polymerases:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>RNA polymerase I and III:</b> For synthesis of rRNAs and tRNAs mainly.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>RNA polymerase II:</b> For synthesis of mRNAs, most small nuclear RNAs (snRNAs) and micro RNAs (miRNAs).", "p": 103}, {"ch": "c12", "f": "02 RNA SYNTHESIS (TRANSCRIPTION) · RNA", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– m<br>• <b>RNA polymerase II</b> is responsible for synthesis of mRNAs.<br>• <b>The promoter :</b> Two types of sequence elements are present in eukaryotic promoter and are called the<span class=\"rn\"> “Basal expression elements”</span>.", "p": 103}, {"ch": "c12", "f": "RNA · 1 TATA box", "b": "&nbsp;&nbsp;&nbsp;– It defines where transcription is to start along the DNA.<br>&nbsp;&nbsp;&nbsp;– It has the sequence of TATAAA.<br>&nbsp;&nbsp;&nbsp;– It is usually located (-20-30 bp) upstream of the transcription start site.", "p": 103}, {"ch": "c12", "f": "RNA · 2 CAAT box and GC box", "b": "&nbsp;&nbsp;&nbsp;– They define when transcription is to start<br>&nbsp;&nbsp;&nbsp;– They control how frequently this event occurs<br>&nbsp;&nbsp;&nbsp;– They are located (-40-200 bp) upstream of the transcription start site.", "p": 103}, {"ch": "c12", "f": "C STEPS OF TRANSCRIPTION · 1 Pre-initiation", "b": "&nbsp;&nbsp;&nbsp;– Transcriptional factors involved in this step are<b> TFII A, B, D, E, F and H</b><br>&nbsp;&nbsp;&nbsp;– <b>TFIID</b> binds to the TATA box promoter element.<br>&nbsp;&nbsp;&nbsp;– It is the only one of these factors that is independently capable of specific high affinity binding to promoter.<br>&nbsp;&nbsp;&nbsp;– This is followed by the binding of the other transcriptional factors<b> (TFII A B, F, E and H)</b> and<b> RNA polymerase II.</b><br>&nbsp;&nbsp;&nbsp;– <b>Preinitiation complex (PIC)</b> is now formed of the TATA, RNA polymerase II, and the transcriptional factors.", "p": 103}, {"ch": "c12", "f": "C STEPS OF TRANSCRIPTION · 2 Initiation", "b": "&nbsp;&nbsp;&nbsp;– <b>TFIIH has a helicase activity</b> that separates the two strands of DNA for initiation.<br>&nbsp;&nbsp;&nbsp;– Also, it activates RNA polymerase II.<br>&nbsp;&nbsp;&nbsp;– This is followed by the release of TFII A, B, E &amp; H.<br>&nbsp;&nbsp;&nbsp;– RNA polymerase II-TFIIF complex leaves the promoter region and moves towards the +1 nucleotide (Transcription start site).", "p": 103}, {"ch": "c12", "f": "C STEPS OF TRANSCRIPTION · 3 Elongation", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>RNA polymerase II -TFIIF complex</b> starts to synthesize a complementary transcript of the template DNA strand using ribonucleoside triphosphates (ATP, GTP, CTP and UTP) as substrates and releases pyrophosphate each time a nucleoside monophosphate is added to the growing chain.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The process of elongation of the RNA chain continues until a termination signal is reached.", "p": 104}, {"ch": "c12", "f": "C STEPS OF TRANSCRIPTION · 4 Termination", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Transcription is terminated<b> when RNA polymerase II reaches a special termination</b> <b>sequence</b> on the template strand of DNA", "p": 104}, {"ch": "c12", "f": "03 POST-TRANSCRIPTIONAL MODIFICATIONS OF mRNA", "b": "• Messenger RNA is synthesized as a primary transcript (Immature) known as<b> heterogeneous</b> <b>nuclear RNA (hnRNA)</b>.<br>• <b>In the nucleus, post transcriptional modifications occur</b> including capping, polyadenylation, splicing and mRNA editing.<br>• The mature functioning mRNA then combines with a protein to form<b> mRNA-protein complex,</b> which comes out through a nuclear pore to the cytoplasm.", "p": 105}, {"ch": "c12", "f": "03 POST-TRANSCRIPTIONAL MODIFICATIONS OF mRNA · A CAPPING AT 5`END", "b": "• Methyl-guanosine cap is added at the 5`end<br>• <b class=\"rd\">Importance of capping:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It stabilizes the mRNA and protects it against the attack by ribonucleases.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It facilitates protein synthesis through helping the transport of mRNA to the cytoplasm and allows its recognition by the ribosomes (see later).", "p": 105}, {"ch": "c12", "f": "03 POST-TRANSCRIPTIONAL MODIFICATIONS OF mRNA · B POLYADENYLATION AT 3` END", "b": "• Poly (A) polymerase (PAP) is responsible for the addition of poly(A) tail (Up to 200 adenine residues) at the 3`end of pre-mRNA.<br>• <b class=\"rd\">Importance of polyadenylation:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It stabilizes the mRNA and protects it against the attack by ribonucleases.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The length of poly (A) tail determines the half-life time of mRNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It increases the efficiency of protein synthesis through binding with specific poly A tail-binding proteins.", "p": 105}, {"ch": "c12", "f": "03 POST-TRANSCRIPTIONAL MODIFICATIONS OF mRNA · C SPLICING", "b": "• In the primary RNA transcript, parts of mRNA do not code for amino acids.<br>• These sequences are known as<b> introns</b>.<br>• They lie between amino acid coding regions known as<b> exons</b>.<br>• Splicing removes introns (Non-expressed regions) &amp; joins exons (Expressed regions) to form functional mRNA.<br>• Splicing requires a<b> spliceosome</b> which is small nuclear ribonucleoproteins (snRNPs) formed of special proteins and small nuclear RNAs (snRNAs).", "p": 105}, {"ch": "c12", "f": "C SPLICING · Biomedical correlations", "b": "• <b class=\"rd\">Systemic Lupus erythematosus (SLE):</b><br>– An autoimmune disease characterized by autoantibodies against many cellular components.<br>– Small nuclear ribonucleoproteins (snRNPs) are one of the targets of these antibodies.<br>• <b>Alternative splicing:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The primary transcript of some genes may be spliced differently to yield different proteins from the same gene.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This explains why the estimated number of proteins much exceeds the number of genes (e.g., antibody genes).", "p": 106}, {"ch": "c12", "f": "03 POST-TRANSCRIPTIONAL MODIFICATIONS OF mRNA · D mRNA EDITING", "b": "• Coding information of mRNA can be changed by RNA editing.<br>• <b class=\"rd\">For example:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>In the liver:</b> the single apolipoprotein gene (Apo-B gene) is transcribed into an mRNA that directs the synthesis of apoB-100protein (100-kDa).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>In the intestine:</b> the same gene directs the synthesis of a primary transcript, then by the action of a cytidine deaminase, a CAA codon in mRNA is converted to UAA which is a termination codon.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>ApoB-48 protein</b> (48-kDa) is the result of translating this edited form of mRNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>ApoB-100 and ApoB-48 proteins</b> have different functions.", "p": 106}, {"ch": "c12", "f": "04 PROTEIN SYNTHESIS (TRANSLATION) · A GENETIC CODE", "b": "• It is the nucleotide sequence of mRNA representing the code words for amino acids.<br>• Since the code words on mRNA originate from DNA genes, they are called<b> «Genetic code»</b>.<br>• Each 3 successive nitrogenous bases in mRNA represents a codon.<br>• Since each codon is formed of 3 of the 4 bases (U, C, A, G), therefore there are<b> 4</b><sup>3</sup><b>=64</b> <b>possible codons as follows:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– One codon acts as initiation codon for protein synthesis i.e. AUG.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Three codons (UAA, UAG or UGA) do not code for any amino acid, and they are called termination codons (stop codons).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The remaining codons code for amino acids.<br>• <b class=\"rd\">Characteristics of genetic code</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Specificity:</b> A particular codon always codes for only one amino acid, e.g., UUU codes only for phenylalanine.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Degeneracy:</b> An amino acid may be coded by more than one codon known as synonym codons (phenylalanine is coded by two synonym codons).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Universality:</b> Genetic code is nearly universal (same in all organisms).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Reading frame:</b> the codons are read from specific starting point (initiating codon) on the mRNA as a continuous uninterrupted sequence of bases taken 3 at a time.", "p": 107}, {"ch": "c12", "f": "04 PROTEIN SYNTHESIS (TRANSLATION) · B CODON RECOGNITION BY tRNA", "b": "• Correct pairing of the codon of the mRNA with the anticodon of the tRNA is essential for accurate translation.<br>• Some tRNAs recognize more than one codon for a given amino acid.<br>• For a given codon on mRNA, an anti-codon is present on tRNA.<br>• Codon and anti-codon always read from 5` to 3` direction.<br>• Moreover, codon and anticodon are antiparallel and complementary in base composition. They interact with each other through base pairing.", "p": 108}, {"ch": "c12", "f": "04 PROTEIN SYNTHESIS (TRANSLATION) · CC WOBBLE HYPOTHESIS", "b": "• The mechanism by which tRNAs can recognize more than one codon for a specific amino acid is described by the<b> “Wobble” hypothesis.</b><br>• The first two nucleotides in the codon are essential, the third nucleotide is flexible, i.e., even if the third nucleotide is changed, that codon may indicate the same amino acid.<br>• Thus, the base pairing of the third nucleotide of codon with the first nucleotide of anti-codon is less specific.<br>• <b>Translation</b> is a process by which a cell makes protein using genetic information carried on mRNA.<br>• <b class=\"rd\">This process requires:</b><br>&nbsp;&nbsp;&nbsp;– <b>All three classes of RNA :</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The mRNA which is the template for the correct addition of individual amino acids during synthesis of protein.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The tRNAs carry activated amino acids (in the form of aminoacyl-tRNA) into the ribosomes.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The ribosomes are associated with the mRNA and contain peptidyl transferase activity to catalyze peptide bond formation.<br>&nbsp;&nbsp;&nbsp;– <b>Amino acids:</b> activated and carried on tRNA<br>&nbsp;&nbsp;&nbsp;– <b>A source of energy</b> (ATP and GTP)<br>&nbsp;&nbsp;&nbsp;– <b>Different protein factors</b> required for the process to be completed.", "p": 108}, {"ch": "c12", "f": "04 PROTEIN SYNTHESIS (TRANSLATION) · A STEPS OF PROTEIN SYNTHESIS", "b": "• Rough endoplasmic reticulum is the site of formation of proteins in eukaryotes.<br>• After formation of aminoacyl-tRNA, the mechanism of translation involves three main phases: initiation, elongation, and termination.", "p": 109}, {"ch": "c12", "f": "A STEPS OF PROTEIN SYNTHESIS · 1 Formation of Aminoacyl-tRNA", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– In the cytosol, the 20 different amino acids are carried on their corresponding tRNAs by 20 different amino-acyl-tRNA synthetases<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Each of which is specific for one amino acid and its corresponding tRNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>The formation of aminoacyl-tRNA occurs in two steps:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– First, is the formation of enzyme-AMP-amino acid complex, with hydrolysis of ATP into AMP and PPi.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Second, is formation of aminoacyl-tRNA complex &amp; release of the enzyme &amp; AMP.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Aminoacyl-tRNA is said to be<b> “Charged tRNA&quot;</b>.", "p": 109}, {"ch": "c12", "f": "A STEPS OF PROTEIN SYNTHESIS · 2 Synthesis of the Polypeptide Chain in Eukaryotes", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>The process of translation is classified into three main phases:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Initiation<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Elongation<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Termination.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Special protein factors for initiation (initiation factors, IFs), elongation (EFs) and termination (release factors) are required for each stage respectively.", "p": 109}, {"ch": "c12", "f": "2 Synthesis of the Polypeptide Chain in Eukaryotes · A. Initiation (1/2)", "b": "• <b>It involves the assembly of the components of protein synthesis at the initiation codon.</b><br>• IF-4 binds to 5`- cap of mRNA.<br>• IF-4 facilitates the binding of mRNA to 40S ribosomal subunit.<br>• The 40S subunit moves on the mRNA to reach the first codon (AUG).<br>• The initiating methionyl tRNA (Met-tRNAi) becomes bound to the AUG start codon on the mRNA.<br>• The 60S subunit of the ribosome binds to the 40S subunit forming the completed 80S initiation complex, with release of IF-4.<br>• Two important binding sites on 80S ribosome are the P and A sites.<br>&nbsp;&nbsp;&nbsp;– <b>The peptidyl site (P site):</b> It is the site on the ribosome where the initiator methionine tRNA (Met-tRNAi) initially binds.<br>&nbsp;&nbsp;&nbsp;– <b>The aminoacyl site (A site):</b> It binds the new coming tRNA molecule carrying an activated amino acid.", "p": 110}, {"ch": "c12", "f": "2 Synthesis of the Polypeptide Chain in Eukaryotes · A. Initiation (2/2)", "b": "• At the end of initiation, met-tRNAi is on the P-site, while the A-site remains vacant and ready to accept the next aminoacyl-tRNA during elongation.", "p": 110}, {"ch": "c12", "f": "2 Synthesis of the Polypeptide Chain in Eukaryotes · B. Elongation", "b": "• <b>Elongation is a 3-step cycle that is repeated for each amino acid added to the protein after</b> <b>the initiator methionine.</b><br>• During elongation, the ribosome moves from the 5ˋ to 3ˋdirection along the mRNA, synthesizing the protein from amino to carboxyl terminus.<br>• <b>The 3 steps are:</b><br>&nbsp;&nbsp;&nbsp;– <span class=\"rn\">Binding of aminoacyl-tRNA to the A-site:</span><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The charged tRNA binds to the A-site.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The aminoacyl-tRNA is determined by the mRNA codon aligned with the A-site.<br>&nbsp;&nbsp;&nbsp;– <span class=\"rn\">Peptide bond formation:</span><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Peptidyl transferase, an enzyme which is part of the 60S subunit, forms the peptide bond between the amino group of the new aminoacyl-tRNA in the A-site with carboxylic group of the peptidyl chain carried by tRNA occupying the P-site.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This results in attachment of the growing peptide to tRNA in the A-site (i.e., now peptidyl-tRNA is in the A-site).<br>&nbsp;&nbsp;&nbsp;– <span class=\"rn\">Translocation:</span><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The ribosome moves exactly 3 nucleotides (One codon) along the mRNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This moves the growing peptidyl-tRNA from A-site to the P-site.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Which frees the A-site to accept a new aminoacyl-tRNA according to the next codon present.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The new cycle of elongation restarts.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The process of polypeptide chain synthesis continues until<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– termination codon is reached.", "p": 111}, {"ch": "c12", "f": "2 Synthesis of the Polypeptide Chain in Eukaryotes · C. Termination", "b": "• <b>The elongation steps are repeated until a termination (Stop) codon appears in the A-site</b> <b>of the ribosome.</b><br>• Since there is no tRNA with anticodon that can pair with the stop codon, a releasing factor binds to the ribosome instead, causing peptidyl transferase to hydrolyze the bond between the peptide chain and tRNA.<br>• The mRNA, ribosome, tRNA and the different protein factors can all be reused for additional protein synthesis<br>• Many ribosomes can work on the same mRNA molecule<br>• These aggregates are called<b> polyribosomes or polysomes</b> and are<b> attached to the wall of the</b> <b>endoplasmic reticulum to form rough ER.</b><br>• In such cases each ribosome is about 80-100 nucleotide apart on mRNA.", "p": 111}, {"ch": "c12", "f": "05 POST-TRANSLATIONAL MODIFICATIONS", "b": "• Most proteins, which emerge from ribosomes, are biologically inactive.<br>• Post-translational modifications convert them into functional proteins.<br>• Usually, protein may attain proper conformation by the time it is released from the ribosome.<br>• <b class=\"rd\">Post-translational modifications include mainly the following:</b>", "p": 112}, {"ch": "c12", "f": "05 POST-TRANSLATIONAL MODIFICATIONS · A TRIMMING", "b": "• Many proteins secreted from cell are initially made as large, precursor molecules that are not functionally active.<br>• Portions of the protein chain must be removed by specialized endoproteases, which results in the release of an active molecule.<br>• <b>For example:</b><br>&nbsp;&nbsp;&nbsp;– Insulin is formed as pre-proinsulin which is converted to proinsulin then to insulin.<br>&nbsp;&nbsp;&nbsp;– Zymogens are inactive precursors of secreted enzymes, e.g., trypsinogen becomes activated to trypsin in the small intestine.", "p": 112}, {"ch": "c12", "f": "05 POST-TRANSLATIONAL MODIFICATIONS · B COVALENTMODIFICATION", "b": "• Amino acid residues within the peptide chain can be modified enzymatically<br>• <b class=\"rd\">Modification is to achieve one or more of the following functions:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Alter the activity or stability of the proteins.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Direct it to a subcellular compartment.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Prepare it for secretion from the cell.<br>• Amino acid residues are modified enzymatically by the addition of various types of functional groups.<br>• <b class=\"rd\">For example:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Phosphorylation / Dephosphorylation:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The addition and removal of phosphate groups (Which bind covalently to serine, threonine, or tyrosine residues)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Serve to regulate the activity of many proteins (e.g., the enzymes of glycogen metabolism and regulators of gene transcription).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Glycosylation:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The addition of carbohydrate groups is a common modification that occurs mainly on proteins that are destined to be secreted or incorporated into lysosomes or cellular membranes.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Acetylation or methylation:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The N-terminal amino acid is sometimes acetylated or methylated.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These changes alter the charge on the protein<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– E.g., chromatin remodeling by histone acetylation (explained later).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Hydroxylation:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– In collagen, hydroxylation of prolyl &amp; lysyl residues leads to stabilization of protein.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Carboxylation:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Formation of γ-carboxyglutamate of some blood coagulation proteins allows them to bind Ca<sup>+2</sup>, a step occurs in clot formation.", "p": 113}, {"ch": "c12", "f": "06 GENE MUTATIONS", "b": "• Mutations are defined as permanent changes in a DNA sequence.<br>• <b class=\"rd\">Causes of Mutations:</b>", "p": 113}, {"ch": "c12", "f": "06 GENE MUTATIONS · A ERRORS IN REPLICATION", "b": "• If a non-complementary base to the template base is added during replication, this leads to mutation if the error is not repaired.", "p": 113}, {"ch": "c12", "f": "B DAMAGE OF THE NUCLEOTIDES OF DNA · 1 Chemical mutagens", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Chemical mutagens are chemicals inhaled or absorbed from the environment that cause mutations. e.g., cigarette smoke contains carcinogens.", "p": 113}, {"ch": "c12", "f": "B DAMAGE OF THE NUCLEOTIDES OF DNA · 2 Irradiation", "b": "&nbsp;&nbsp;&nbsp;– Ultraviolet light (UV) or ionizing radiation (x-rays and gamma rays) can alter the structure of DNA.", "p": 114}, {"ch": "c12", "f": "B DAMAGE OF THE NUCLEOTIDES OF DNA · 3 Oxidative damage", "b": "&nbsp;&nbsp;&nbsp;– Oxidative DNA damage is implicated in several diseases.<br>&nbsp;&nbsp;&nbsp;– Diseases range from neurological disorders such as Alzheimer&#x27;s disease to cancer.<br>&nbsp;&nbsp;&nbsp;– Also, DNA oxidative damage has been shown to play a part in the aging process.<br>&nbsp;&nbsp;&nbsp;– <span class=\"rn\">Regardless of the method of formation, there are only limited types of gene mutations.</span>", "p": 114}, {"ch": "c12", "f": "06 GENE MUTATIONS · A BASE SUBSTITUTION (POINT MUTATIONS)", "b": "• Base substitutions<b> are the most common type of mutation</b>.<br>• They may occur in the coding region of a gene<br>• <b>They can produce one of the following effects:</b> Missense, nonsense, or silent mutation.", "p": 114}, {"ch": "c12", "f": "A BASE SUBSTITUTION (POINT MUTATIONS) · 1 Missense mutation", "b": "&nbsp;&nbsp;&nbsp;– Leads to a changed codon &amp; results in an amino acid change in protein product of it.<br>&nbsp;&nbsp;&nbsp;– Depending on the amino acid changed, missense mutations can have either no effect or very serious changes e.g., sickle cell anemia.", "p": 114}, {"ch": "c12", "f": "A BASE SUBSTITUTION (POINT MUTATIONS) · 2 Nonsense mutation", "b": "&nbsp;&nbsp;&nbsp;– Leads to the conversion of an amino acid codon to a stop or non-sense codon.<br>&nbsp;&nbsp;&nbsp;– Translation of the mRNA from that gene is prematurely terminated and the protein product is usually non-functional e.g., thalassemia.", "p": 114}, {"ch": "c12", "f": "A BASE SUBSTITUTION (POINT MUTATIONS) · 3 Silent mutation", "b": "&nbsp;&nbsp;&nbsp;– Leads to formation of a synonym codon that codes for the same amino acid and no change occurs in the amino acid sequence of the gene products.", "p": 114}, {"ch": "c12", "f": "B DELETION OR INSERTION OF ONE OR MORE BASES · 1 Frameshift mutation", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It occurs if a deletion or insertion of bases in a gene is not a multiple of three e.g., one or two bases.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The reading frame of the translated mRNA is changed.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This usually results in the production of a nonfunctional gene product.", "p": 115}, {"ch": "c12", "f": "B DELETION OR INSERTION OF ONE OR MORE BASES · 2 Deletion or insertion of three or multiple of three bases", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This produces no changes in the reading frame and only a deletion or insertion of one or more amino acids from the encoded protein.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Such mutation is less severe than the frameshift mutation.", "p": 115}, {"ch": "c13", "f": "01 INTRODUCTION TO REGULATION OF GENE EXPRESSION", "b": "• The process of gene expression needs to be strictly regulated to ensure that cells produce the correct number of proteins when they need them.<br>• Any disruption to this regulation can lead to serious consequences.<br>• <b class=\"rd\">There are two types of genes:</b><br>&nbsp;&nbsp;&nbsp;– <b>Unregulated genes (Constitutive or housekeeping):</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These genes are continually expressed at fixed rate &amp; are not subjected to regulation<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They encode proteins that are continuously required for basic cellular functions, such as β-actin gene.<br>&nbsp;&nbsp;&nbsp;– <b>Regulated genes:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These genes represent the majority and are expressed only under certain conditions.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They encode proteins only when they are required, such as globin genes.", "p": 117}, {"ch": "c13", "f": "02 REGULATION OF EUKARYOTIC GENE EXPRESSION", "b": "• Regulation of gene expression occurs at multiple levels, mainly at level of transcription.", "p": 117}, {"ch": "c13", "f": "A PRE-TRANSCRIPTIONAL REGULATION · 1 Epigenetic Mechanisms", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Epigenetic</b> means “Around the gene”, it refers to the changes that occur to the DNA and the histone proteins.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These changes do not alter the sequence of DNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>DNA Methylation</b>:<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Methylation of a specific cytosine to form 5`methylcytosine by DNA methyltransferase.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The target cytosine is usually located next to a guanine residue, forming a CpG island, which is often near or in the promoter region of a gene.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is associated with the silencing of the activities of certain genes.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is a mechanism for regulating gene expression during cell differentiation, particularly in fetal development.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Demethylation reverses the process.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Chromatin Remodeling</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The cellular genome is packaged together with histones into chromatin structures.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Activation of a gene for transcription requires changes in the state of the chromatin, to make the desired region accessible to RNAP and other proteins (e.g., transcriptional factors).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This is called<b> chromatin remodeling</b>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This occurs through different mechanisms, for example,<b> histone acetylation</b>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Histone acetyltransferases (HATs)</b> transfer an acetyl group from acetyl coenzyme A (acetyl-CoA) to lysine residues in the tail of the histone octamer.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This reaction<b> removes</b> a positive charge from the<b> ε-amino group of the</b> <b>lysine</b>, thereby<b> reducing</b> the electrostatic interactions between the histones and the negatively charged DNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This makes it easier for DNA to<b> unwind</b> from the histones with<b> simultaneous</b> <b>activation of the gene and initiation of its transcription</b>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The acetyl groups can be removed by<b> histone deacetylases (HDACs)</b> to form inactive chromatin.", "p": 118}, {"ch": "c13", "f": "A PRE-TRANSCRIPTIONAL REGULATION · 2 Epigenetic Mechanisms", "b": "&nbsp;&nbsp;&nbsp;– A change in the number of copies of a gene can affect amount of gene product produced<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">This include:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Gene amplification (Increase the number)</b>: This is seen in response to certain chemotherapeutic drugs such as methotrexate, an inhibitor of the enzyme <b>dihydrofolate reductase (DHFR)</b>, required for the synthesis of DNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Malignant cells can develop resistance to methotrexate by amplification of the gene for this enzyme.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Gene diminution (Decrease the number)</b>: This occurs during development of RBCs as all genes disappear during maturation.", "p": 119}, {"ch": "c13", "f": "A PRE-TRANSCRIPTIONAL REGULATION · 3 Gene Rearrangement", "b": "&nbsp;&nbsp;&nbsp;– Heavy &amp; light chains of Igs are encoded by several hundred gene segments.<br>&nbsp;&nbsp;&nbsp;– Their rearrangement or recombination allows generation of several million different immunoglobulins, providing the antibody diversity needed for the recognition of an enormous number of antigens.", "p": 119}, {"ch": "c13", "f": "02 REGULATION OF EUKARYOTIC GENE EXPRESSION · B TRANSCRIPTIONAL REGULATION", "b": "&nbsp;&nbsp;&nbsp;– Regulation of gene expression at the level of transcription occurs through interaction between cis- and trans-acting elements.", "p": 120}, {"ch": "c13", "f": "B TRANSCRIPTIONAL REGULATION · 1 Cis-acting elements", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These are<b> DNA regulatory sequences flanking a gene</b>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are usually embedded in the non-coding regions of the genome.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They influence expression of genes only on the same chromosome.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The interaction between these DNA segments &amp; regulatory molecules, such as transcription factors, can<b> induce or repress</b> the transcriptional machinery, influencing the kinds and amounts of products.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Cis- acting elements include:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. <b>Promoter :</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Two types of sequence elements are present in promoter<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The TATA box &amp; the CAAT box &amp; GC box regions (Discussed in transcription).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. <b>Enhancers and silencers:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <span class=\"rn\">Enhancers</span> are special elements in DNA → Facilitate initiation of transcription.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They act by binding certain proteins that facilitate the binding of transcription factors to the promoter.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– However, they can be close to or thousands of base pairs away from promoter (Upstream or downstream) &amp; they can occur on either strand of DNA.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <span class=\"rn\">Silencers</span> are special elements in DNA that inhibit initiation of transcription.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They act by binding certain proteins that produce inhibition of transcription.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3. <b>Hormone-Response Elements:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These are elements in DNA that permit hormones to regulate transcription<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– When the hormone receptor complex binds the specific element in DNA<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– e.g., steroid and thyroid hormones.", "p": 120}, {"ch": "c13", "f": "B TRANSCRIPTIONAL REGULATION · 2 Trans-acting elements", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are the regulatory molecules which can diffuse from their site of synthesis in the cell to the DNA-binding site.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">For example:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Trans-acting molecule</b> is transcribed from a gene on<b> chromosome 11</b> and regulates another gene on<b> chromosome 6.</b>", "p": 120}, {"ch": "c13", "f": "02 REGULATION OF EUKARYOTIC GENE EXPRESSION · C POST-TRANSCRIPTIONALREGULATION", "b": "&nbsp;&nbsp;&nbsp;– <b>Capping, poly-A tailing, and splicing:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Discussed in transcription.<br>&nbsp;&nbsp;&nbsp;– <b>miRNAs:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– They are non-coding RNAs that reduce expression of the target mRNA either by inducing its degradation or blocking its translation.", "p": 121}, {"ch": "c13", "f": "02 REGULATION OF EUKARYOTIC GENE EXPRESSION · D TRANSLATIONAL REGULATION", "b": "&nbsp;&nbsp;&nbsp;– Phosphorylation of some IFs<b> blocks protein synthesis.</b><br>&nbsp;&nbsp;&nbsp;– They are phosphorylated by protein kinases that are activated when the cell is under stress and when energy utilization for protein synthesis is deleterious e.g.<b> starvation.</b>", "p": 121}, {"ch": "c13", "f": "02 REGULATION OF EUKARYOTIC GENE EXPRESSION · E POST-TRANSLATIONAL MODIFICATION OF PROTEINS", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">(See translation)</b><br>&nbsp;&nbsp;&nbsp;1. Trimming<br>&nbsp;&nbsp;&nbsp;2. Covalent Modification", "p": 121}, {"ch": "c14", "f": "01 CELL CYCLE", "b": "• <b class=\"rd\">Cell cycle is a series of events that take place in a cell as it grows &amp; divides into 2 daughter cells</b>", "p": 123}, {"ch": "c14", "f": "01 CELL CYCLE · A PHASES OF CELL CYCLE", "b": "&nbsp;&nbsp;&nbsp;– The cell cycle is divided into two main phases: the<b> mitotic phase</b> (M) &amp; the<b> interphase (I)</b><br>&nbsp;&nbsp;&nbsp;– Interphase is further divided into three phases (G1, S and G2).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>G1:</b> Growth<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>S:</b> Synthesis of DNA<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>G2:</b> Growth &amp; preparation for mitosis<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>M:</b> Mitosis<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>G0:</b> Resting<br>&nbsp;&nbsp;&nbsp;– The cell spends most of its time in the<b> interphase</b>, during which it grows, replicates its chromosomes, and prepares itself for cell division.<br>&nbsp;&nbsp;&nbsp;– The cell then leaves the interphase, undergoes mitosis, and completes its division.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">G1 phase:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The stage where the cell grows by increasing in size, and checks DNA to repair any damage by replication.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">S phase:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The stage where the cell<b> replicates</b> its DNA (S stands for synthesis of DNA).<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">G2 phase:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The stage where the cell<b> grows</b> more and prepares itself to divide.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">M phase:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The stage of mitosis where the cell<b> separates</b> the 2 copies of the genetic material into two identical<b> daughter cells</b>.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">G0 phase:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– After passing through mitosis and into G1, the cell either continues through another division or stops dividing (entering a quiescent phase G0).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– In G0, the cell is said to be in the resting state performing its function without dividing.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– G0 is a permanent state for some cells, e.g., most<b> adult neuronal cells</b>.", "p": 123}, {"ch": "c14", "f": "01 CELL CYCLE · B REGULATION OF CELL CYCLE (1/2)", "b": "&nbsp;&nbsp;&nbsp;– <b>The cell cycle is mainly controlled by:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Regulatory proteins (Cyclins and cyclin-dependent kinases)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Checkpoints at different stages<br>• <b>The cell cycle is controlled by a group of regulatory proteins called:</b><br>&nbsp;&nbsp;&nbsp;– Cyclins and Cyclin Dependent Kinases (CDK).<br>• The cell cycle is initiated by binding of a growth factor to a growth factor receptor on the plasma membrane of the cell.<br>• This mediates an intracellular signaling cascade that induces cyclins genes.<br>• Cyclins complex with and activate certain CDKs that produce regulatory effects essential for the passage of the cell from one phase to another.<br>• There are at least 10 different cyclins (Designated A, B, and so forth) &amp; at least 8 CDKs", "p": 123}, {"ch": "c14", "f": "01 CELL CYCLE · B REGULATION OF CELL CYCLE (2/2)", "b": "• <b>They act in various combinations at specific points in the cell cycle as follows:</b><br>&nbsp;&nbsp;&nbsp;– Progression past restriction point at G1/S boundary.<br>&nbsp;&nbsp;&nbsp;– Initiation of DNA synthesis in early S phase.<br>&nbsp;&nbsp;&nbsp;– Transition from G2 to M phase.", "p": 123}, {"ch": "c14", "f": "B REGULATION OF CELL CYCLE · Restriction point", "b": "• The restriction point (R) is located at the late G1 stage.<br>• The cells that pass through the R point will enter the S phase and complete the entire cycle independently on the presence of the growth factors.", "p": 124}, {"ch": "c14", "f": "B REGULATION OF CELL CYCLE · 2 Cell Cycle Checkpoints", "b": "&nbsp;&nbsp;&nbsp;– There are<b> three</b> check points to ensure that DNA and chromosomal structure are intact before the cell cycle is completed as explained by the following diagram.<br>&nbsp;&nbsp;&nbsp;– If there is a defect in any of the cell cycle regulatory proteins or checkpoints, or if the cell suffers from irreparable damage to DNA prior to S phase, it may destroy itself in response to programmed steps.<br>&nbsp;&nbsp;&nbsp;– This is called “<b>apoptosis</b>”.", "p": 124}, {"ch": "c14", "f": "02 APOPTOSIS", "b": "• Apoptosis is programmed genetically directed cell death (physiological cell suicide program).<br>• Many cells can precisely control the time of their own death by apoptosis (app›-a-toe›-sis from the Greek for «dropping off,» as in leaves dropping in the fall).", "p": 124}, {"ch": "c14", "f": "02 APOPTOSIS · A BIOLOGICAL SIGNIFICANCE", "b": "&nbsp;&nbsp;&nbsp;– <b>Eliminating</b> individual cells whose survival would be harmful to the organism.<br>&nbsp;&nbsp;&nbsp;– When a cell is damaged beyond repair, infected with a virus, experiencing starvation or under the effects of ionizing radiation or toxins (causing irreparable damage to DNA), apoptosis is stimulated.<br>&nbsp;&nbsp;&nbsp;– <b>Development</b>: Apoptosis is used during development of the embryo.<br>&nbsp;&nbsp;&nbsp;– <b>Homeostasis</b>: In normal, healthy adults, the number of cells is kept relatively constant owing to a balance between cell division and cell death.<br>&nbsp;&nbsp;&nbsp;– If the equilibrium is disturbed, then abnormal growth &amp; tumors or abnormal cell loss can result.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">There are two main pathways for apoptosis:</b>", "p": 125}, {"ch": "c14", "f": "B MECHANISMS OF APOPTOSIS · 1 Extrinsic pathway", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is initiated through binding of a certain<b> ligand</b> to the tumor necrosis factor (<b>TNF</b>) or <b>FAS receptors</b>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This binding leads to activation of several<b> caspases</b> (Caspases are intracellular cysteine proteases).<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Activated Caspases activate caspase-activated DNase (<b>CADase</b>)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– The enzyme that cuts genomic DNA between nucleosomes generating DNA fragments of approximately 200 bp or its multiples.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Responsible for characteristic<b> DNA ladder pattern</b> observed after DNA electrophoresis.", "p": 125}, {"ch": "c14", "f": "B MECHANISMS OF APOPTOSIS · 2 Intrinsic (mitochondrial) pathway", "b": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– It is used extensively in response to different forms of cellular stress.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– These stressors promote the release of<b> cytochrome C</b> from mitochondria into cytosol.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Released cytochrome C activates<b> caspases</b>, leading to activation of CADase and induction of the apoptotic process.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b class=\"rd\">Regulation of intrinsic pathway:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Bcl2- family members are important regulators of the mitochondrial apoptotic pathway. These members include two main functional groups:<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Anti-apoptotic modulators</b>: (Bcl2-, Bcl-x, etc.) possess anti-apoptotic activity.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– <b>Apoptotic modulators</b>: (Bax, Bak, Bok) exert their apoptosis-modulating effects by controlling the release of cytochrome c from mitochondria to cytosol.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Under physiological conditions, there is balance between the two groups.", "p": 125}, {"ch": "c14", "f": "2 Intrinsic (mitochondrial) pathway · Apoptosis and Cancer", "b": "• Cancer arises when the homeostatic balance between cell division and apoptosis is altered. Decreased apoptosis in cancer cells may result from altered expression of apoptosis regulatory proteins.", "p": 126}, {"ch": "c14", "f": "03 TUMOR SUPPRESSOR GENES", "b": "• <b class=\"rd\">Tumor suppressor genes encode proteins that have at least one of these functions:</b><br>&nbsp;&nbsp;&nbsp;– Proteins that are activated in response to DNA damage, e.g. p53.<br>&nbsp;&nbsp;&nbsp;– Proteins that inhibit progression through a specific stage of the cell cycle and give it time to repair, e.g. p21.<br>&nbsp;&nbsp;&nbsp;– Proteins that promote apoptosis e.g. protein Bax.<br>&nbsp;&nbsp;&nbsp;– <b>DNA repair enzymes:</b> They are termed anti-oncogenes; &amp; their mutations remove certain control on growth &amp; proliferation which play a major role in the development of cancer.", "p": 126}, {"ch": "c14", "f": "03 TUMOR SUPPRESSOR GENES · B HETEROPOLYSACCHARIDES [printed heading — the text below is about the p53 gene]", "b": "&nbsp;&nbsp;&nbsp;– This gene encodes a nuclear phosphoprotein called p53.<br>&nbsp;&nbsp;&nbsp;– It has a molecular weight of 53 kDa.<br>&nbsp;&nbsp;&nbsp;– p53 is called the “<b>Molecular Policeman</b>” or “<b>Guardian of the Genome</b>”.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">In Moderate DNA Damage:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Certain protein kinases phosphorylate p53 and make it active.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Active phosphorylated p53 serves as a transcription factor that induces the synthesis of the protein p21.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Protein p21 inhibits the protein kinase activity of a specific CDK-cyclin complex, &amp; the cell cycle is arrested in Gl.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– This gives the cell time to repair its DNA before entering the<b> S phase</b>,<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– thereby avoiding the potentially disastrous transfer of a defective genome to one or both daughter cells.<br>&nbsp;&nbsp;&nbsp;– <b class=\"rd\">In Severe DNA Damage:</b><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Certain protein kinases<b> phosphorylate p53</b> and make it active.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Active phosphorylated p53 induces<b> Bax gene transcription</b>.<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;– Bax protein triggers apoptosis. So, this will lead to the death of the cell.", "p": 126}, {"ch": "c14", "f": "B HETEROPOLYSACCHARIDES [printed heading — the text below is about the p53 gene] · Biomedical Correlation", "b": "• Mutation in the p53 gene leads to genomic instability.<br>• decreased apoptosis and leads to cancer.<br>• About<b> 50%</b> of human cancers have a mutated p53 gene.<br>• <b>Aflatoxin</b> (Fungal toxin) causes mutation of p53 and may lead to<b> hepatic</b> cancer.<br>• <b>Benzopyrene</b> (Smoking) causes mutation of p53 and may lead to<b> lung</b> cancer.", "p": 126}], "pairs": [{"t": "What Is Biochemistry?", "d": "Biochemistry is the study of the chemistry of biological organisms.", "ch": "c1"}, {"t": "Covalent Bonds", "d": "Covalent bond is formed by sharing of a pair of electrons or more between adjacent atoms.", "ch": "c1"}, {"t": "Nonpolar Covalent Bond", "d": "Bond between 2 atoms that have the same electronegativity (Power to attract electrons)", "ch": "c1"}, {"t": "Polar Covalent Bond", "d": "Bond between 2 atoms that have different electronegativity", "ch": "c1"}, {"t": "Noncovalent Bonds Or Forces", "d": "These are weaker than covalent bonds.", "ch": "c1"}, {"t": "Hydrogen Bonds", "d": "They are weak noncovalent interaction between the hydrogen (δ+) of one molecule & the more electronegative atom (δ-) of an acceptor molecule.", "ch": "c1"}, {"t": "Van der Waals Forces", "d": "They are transient attraction between molecules at a distance → Van der Waals distance.", "ch": "c1"}, {"t": "Hydrophobic Interactions", "d": "Hydrophobic interaction refers to the tendency of non polar compounds to cluster together in an aqueous medium, as in case of oil and water.", "ch": "c1"}, {"t": "Chemical classification", "d": "According to their chemical structure.", "ch": "c2"}, {"t": "Polar or non-polar", "d": "According to the polarity of the side chain.", "ch": "c2"}, {"t": "Nutritional classification", "d": "According to their nutritional importance.", "ch": "c2"}, {"t": "Metabolic classification", "d": "According to their metabolic fate.", "ch": "c2"}, {"t": "Amino Acids With Uncharged Polar (R) Groups", "d": "These are more soluble in water than the first group.", "ch": "c2"}, {"t": "Essential Amino Acids", "d": "They are not formed in the body, and they are essential to be supplied in diet.", "ch": "c2"}, {"t": "Half-Essential Or Semi-Essential Amino Acids", "d": "They are formed in the body at a rate enough for adults but not for growing children & adolescents.", "ch": "c2"}, {"t": "Non-Essential Amino Acids", "d": "These include the rest of the amino acids", "ch": "c2"}, {"t": "Pure Glucogenic Amino Acids", "d": "These are amino acids which can give glucose inside the body", "ch": "c2"}, {"t": "Pure Ketogenic Amino Acids", "d": "Amino acids that can give ketone bodies inside body & include leucine & lysine.", "ch": "c2"}, {"t": "Glucogenic And Ketogenic (Mixed) Amino Acids", "d": "These are amino acids which can give glucose & ketone bodies inside the body", "ch": "c2"}, {"t": "Amphoteric Property", "d": "Amino acids can react both with acids and bases, so they are ampholytes.", "ch": "c2"}, {"t": "In acidic medium", "d": "They are positively charged (R-NH+3).", "ch": "c2"}, {"t": "In alkaline medium", "d": "They are negatively charged (R-COO-).", "ch": "c2"}, {"t": "Biological Importance And Functions Of Proteins", "d": "Provide the body with essential amino acids, nitrogen, and sulfur.", "ch": "c3"}, {"t": "Helix", "d": "It is the folding of the polypeptide chain along its longitudinal axis, into a specific coiled structure stabilized by hydrogen bonds.", "ch": "c3"}, {"t": "β -Pleated Sheet", "d": "If two or more segments of the single polypeptide chain are arranged side by side, β-pleated sheet will be formed and is stabilized by hydrogen bonds.", "ch": "c3"}, {"t": "Tertiary Structure", "d": "It is folding of polypeptide chain of a protein into a specific three-dimensional globular structure.", "ch": "c3"}, {"t": "Hydrophobic interactions", "d": "Refer to the tendency of nonpolar compounds to cluster together in an aqueous medium.", "ch": "c3"}, {"t": "Van der Waals interactions", "d": "They are transient attractions between molecules at a distance called the Van der Waals distance.", "ch": "c3"}, {"t": "Quaternary Structure", "d": "This order is shown only by certain types of proteins which have two or more polypeptide chains (Several subunits or polymers).", "ch": "c3"}, {"t": "Denaturation Of Proteins", "d": "Denaturation is a specific property of proteins.", "ch": "c3"}, {"t": "Conformational Classification Of Proteins", "d": "Depending on their conformation, proteins are classified into 2 major classes", "ch": "c3"}, {"t": "Chemical Classification Of Proteins", "d": "Depending on their chemical composition & structural complexity,", "ch": "c3"}, {"t": "Conjugated Proteins", "d": "On hydrolysis, they produce amino acids & other groups (Prosthetic groups) as hemoproteins are formed of protein part attached to heme.", "ch": "c3"}, {"t": "Derived Proteins", "d": "These are derived from the above mentioned groups by hydrolysis or denaturation.", "ch": "c3"}, {"t": "Enzyme Specificity", "d": "Enzymes are highly specific in their action.", "ch": "c4"}, {"t": "Chemical Nature", "d": "Enzymes are either simple or conjugated proteins (Holoenzymes)", "ch": "c4"}, {"t": "Lowering Of The Activation Energy", "d": "For the reactants to be converted into products, a minimum amount of energy called “Activation energy” is required.", "ch": "c4"}, {"t": "Factors Affecting The Rate (Velocity)", "d": "When studying effect of any factor on enzyme catalysis, only one factor should be varied at a time, while all other factors are kept constant.", "ch": "c4"}, {"t": "Covalent modification", "d": "Reversible phosphorylation/ dephosphorylation", "ch": "c4"}, {"t": "Enzyme Inhibition", "d": "Any substance that can diminish the velocity of enzyme-catalyzed reaction is called an inhibitor.", "ch": "c4"}, {"t": "No effect on Vmax", "d": "The effect of a competitive inhibitor is reversed by increasing [S] At a sufficiently high substrate concentration.", "ch": "c4"}, {"t": "Kmincreases", "d": "A competitive inhibitor increases apparent Kmfor a given substrate.", "ch": "c4"}, {"t": "Allosteric Inhibitors", "d": "They are small organic molecules that bind to a specific site away from the active site.", "ch": "c4"}, {"t": "Inhibitors of the apoenzyme (Protein part)", "d": "These are inhibitors that either denature proteins or block chemical groups which are important for substrate binding and/ or catalysis.", "ch": "c4"}, {"t": "Activation Of Proenzymes (Zymogens)", "d": "Many enzymes are formed as proenzymes which are inactive.", "ch": "c4"}, {"t": "Hemoproteins", "d": "These are conjugated proteins, containing heme as a “prosthetic group”.", "ch": "c5"}, {"t": "Chemistry Of Heme", "d": "Heme is a ferrous (Fe+2) protoporphyrin IX.", "ch": "c5"}, {"t": "Polar groups", "d": "Two propionate groups (P).", "ch": "c5"}, {"t": "The Heme ring", "d": "It is present inside the hydrophobic core of apomyoglobin polypeptide chain in a pocket between E and F helices.", "ch": "c5"}, {"t": "Embryonic and Fetal Hemoglobin", "d": "Embryonic Hemoglobin (Hb Gower)", "ch": "c5"}, {"t": "AdultHemoglobin", "d": "It is formed at the end of the late month of pregnancy and continues throughout life.", "ch": "c5"}, {"t": "Heme Rings", "d": "Each globin polypeptide chain binds with one heme ring in a similar manner to that described for myoglobin.", "ch": "c5"}, {"t": "Affinity Of Hemoglobin To Oxygen", "d": "2 forms of Hb exist depending on presence or absence of oxygen", "ch": "c5"}, {"t": "T form", "d": "The deoxy form of hemoglobin is called the \"T\" (tense) form.", "ch": "c5"}, {"t": "Binding to oxygen (heme-heme interaction)", "d": "Although it is more difficult for the first oxygen molecule to bind to hemoglobin", "ch": "c5"}, {"t": "Binding to carbon monoxide (Carboxyhemoglobin)", "d": "Carbon monoxide (CO) binds tightly (but reversibly) to hemoglobin iron, forming carboxyhemoglobin.", "ch": "c5"}, {"t": "Binding to carbon dioxide (carbamino-hemoglobin)", "d": "Most of the carbon dioxide molecules produced in metabolism are hydrated by carbonic anhydrase enzyme and transported as “Bicarbonate ions”.", "ch": "c5"}, {"t": "Sickle Cell Anemia", "d": "It is a genetic disorder common among black populations all over the world.", "ch": "c5"}, {"t": "Formation of porphobilinogen (PBG) (In cytosol)", "d": "Two molecules of ALA condense forming porphobilinogen (PBG) catalyzed by δ-aminolevulinate dehydratase (ALA dehydratase).", "ch": "c5"}, {"t": "Formation of hydroxymethylbilane (In cytosol)", "d": "Four PBG molecules condense to form a linear tetrapyrrole (hydroxymethylbilane), by the enzyme uroporphyrinogen I synthase.", "ch": "c5"}, {"t": "Formation of uroporphyrinogen III (In cytosol)", "d": "Hydroxymethylbilane cyclizes to form uroporphyrinogen III by uroporphyrinogen III synthase.", "ch": "c5"}, {"t": "Formation of coproporphyrinogen III (In cytosol)", "d": "The 4 acetate side chains (A) of uroporphyrinogen III are converted to 4 methyl groups (M) by uroporphyrinogen decarboxylase.", "ch": "c5"}, {"t": "Formation of heme (In mitochondria)", "d": "Subsequent reactions by specific oxidases lead to formation of protoporphyrin IX.", "ch": "c5"}, {"t": "Blood Bilirubin", "d": "Serum bilirubin can be estimated by the Van den Bergh reaction, in which the bilirubin is coupled with a certain reagent to yield a violet dye.", "ch": "c5"}, {"t": "Abnormal hemoglobin", "d": "Sickle cell anemia and thalassemias.", "ch": "c5"}, {"t": "Red cell enzymes deficiency", "d": "Glucose-6-P dehydrogenase (G6PD) & pyruvate kinase.", "ch": "c5"}, {"t": "Red cell antibodies", "d": "Incompatible blood transfusion & erythroblastosis fetalis.", "ch": "c5"}, {"t": "Physiological neonatal jaundice", "d": "It is a transient condition that occurs in the first few days of life.", "ch": "c5"}, {"t": "Gilbert Syndrome", "d": "A benign condition caused by a defect in the uptake of unconjugated bilirubin by the liver and conjugation pathways.", "ch": "c5"}, {"t": "Intro.To Proteins Of Extracellular Matrix", "d": "The extracellular matrix (ECM) is a major component of the connective tissues(CT) that surround and support the tissues and organs.", "ch": "c6"}, {"t": "Fibrous proteins", "d": "Collagen, elastin, fibrillin, fibronectin and laminin.", "ch": "c6"}, {"t": "Proteoglycans", "d": "A core of proteins (5%) attached to glycosaminoglycans (GAGs)", "ch": "c6"}, {"t": "Collagen", "d": "It is a fibrous protein & is the most abundant protein in body (Forms 25% of total body proteins).", "ch": "c6"}, {"t": "Tropocollagen molecule", "d": "It is the building unit of collagen which consists of three coiled α-chains.", "ch": "c6"}, {"t": "Amino acid composition", "d": "Each α-chain contains approximately 1000 amino acids having the repeating triplet sequence Gly-X-Y.", "ch": "c6"}, {"t": "Elastin", "d": "It is a rubber like protein.", "ch": "c6"}, {"t": "Aldoses", "d": "Monosaccharides containing aldehyde group (H-C=O) at C1.", "ch": "c7"}, {"t": "Ketoses", "d": "Monosaccharides containing ketone group (C=O) at C2.", "ch": "c7"}, {"t": "Isomerism Of Monosaccharides", "d": "Isomers are compounds which have the same molecular formula (the same number and types of atoms) but have different structural or steric formulae.", "ch": "c7"}, {"t": "Anomers", "d": "Cyclization creates carbon atoms (C1 in aldose and C2 in ketoses) with two possible orientations of the hydroxyl group around it (α- and β-forms).", "ch": "c7"}, {"t": "Sugar Alcohols", "d": "These are sugars in which the carbonyl group is reduced to an alcohol group.", "ch": "c7"}, {"t": "Deoxy sugars", "d": "These are sugars in which the hydroxyl group at C2 is replaced by a hydrogen atom.", "ch": "c7"}, {"t": "Amino sugars", "d": "These are sugars in which the hydroxyl group at C2 is replaced by an amino group (NH2)", "ch": "c7"}, {"t": "Maltose (Malt Sugar)", "d": "It is formed of 2 molecules of glucose united by α 1,4-glucosidic linkage.", "ch": "c7"}, {"t": "Lactose (Milk Sugar)", "d": "It is formed of galactose and glucose united by β1,4-galactosidic linkage.", "ch": "c7"}, {"t": "Sucrose (Cane Or Table Sugar)", "d": "It is present in plants as sugar cane and beets.", "ch": "c7"}, {"t": "Polysaccharides", "d": "They are composed of more than 10 monosaccharide units linked by glycosidic bonds.", "ch": "c7"}, {"t": "Homopolysaccharides", "d": "They are polysaccharides entirely made up of the same type of monosaccharide units.", "ch": "c7"}, {"t": "Amylose", "d": "(20–30%) A linear polymer where glucose units are linked by α1,4-glucosidic bonds.", "ch": "c7"}, {"t": "Amylopectin", "d": "(70–80%) A highly branched polymer containing both α1,4-glucosidic bonds for the main chain & α-1,6 glucosidic bonds at branching points.", "ch": "c7"}, {"t": "Joints", "d": "In osteoarthritis, the concentration of hyaluronic acid gradually decreases, lowering the lubricant effect of synovial fluid.", "ch": "c7"}, {"t": "Hyaluronidase enzyme (Spreading factor)", "d": "It can hydrolyze hyaluronic acid present in the ground substance of connective tissue.", "ch": "c7"}, {"t": "Chondroitin sulfate", "d": "It is the prominent component of cartilage, tendons, ligaments, bone, and aorta.", "ch": "c7"}, {"t": "Keratan sulfate", "d": "It is one of the major components of the cornea and suggested to have important roles for corneal development and maintenance of its transparency.", "ch": "c7"}, {"t": "According to the Length of the Chain", "d": "Short chain fatty acids (from C2to C6)", "ch": "c8"}, {"t": "Saturated Fatty Acids (SFA)", "d": "They contain no double bonds.", "ch": "c8"}, {"t": "Unsaturated Fatty Acids (USFA)", "d": "They contain one or more double bonds", "ch": "c8"}, {"t": "Simple lipids", "d": "Esters of fatty acids with various alcohols.", "ch": "c8"}, {"t": "Compound (Conjugated) lipids", "d": "In addition to esters of fatty acids with alcohol, another group is added.", "ch": "c8"}, {"t": "Derived lipids", "d": "They are fat soluble products of hydrolysis of the first two groups, or present in association with them in nature.", "ch": "c8"}, {"t": "Simple Lipids", "d": "They are esters of fatty acids with alcohol.", "ch": "c8"}, {"t": "Neutral fats (Triacylglycerol TAG)", "d": "They are esters of three fatty acids with glycerol.", "ch": "c8"}, {"t": "Waxes", "d": "They are esters of one fatty acid with long chain monohydroxy alcohol higher than glycerol.", "ch": "c8"}, {"t": "Oils", "d": "They are liquid at room temperature due to their high content of USFA.", "ch": "c8"}, {"t": "Solid fats", "d": "They are solid at room temperature due to their high content of long chains SFA.", "ch": "c8"}, {"t": "Compound (Conjugated) Lipids", "d": "They contain fatty acids, alcohol, and other groups.", "ch": "c8"}, {"t": "Phospholipids", "d": "Containing phosphate group.", "ch": "c8"}, {"t": "Glycolipids", "d": "Containing carbohydrate group.", "ch": "c8"}, {"t": "Glycerophospholipids", "d": "They are phospholipids containing glycerol.", "ch": "c8"}, {"t": "Hydrolysis of glycerophospholipids", "d": "They are hydrolyzed by a group of enzymes called phospholipases (PLA1, PLA2, PLC and PLD).", "ch": "c8"}, {"t": "Sphingomyelin", "d": "Formed of sphingol (18C amino alcohol) attached to fatty acid and phosphocholine.", "ch": "c8"}, {"t": "Drived Lipid", "d": "They are products of hydrolysis of either simple or conjugated lipids or associated with lipids in nature.", "ch": "c8"}, {"t": "Thymine", "d": "Present only in DNA (minor base in tRNA).", "ch": "c9"}, {"t": "Cytosine", "d": "Present in both nucleic acids (RNA & DNA).", "ch": "c9"}, {"t": "Oxypurines", "d": "Hypoxanthine and Xanthine: These are present free or in the form of nucleotides but are rarely present in structure of nucleic acids.", "ch": "c9"}, {"t": "Hypoxanthine and Xanthine", "d": "These are present free or in the form of nucleotides but are rarely present in structure of nucleic acids.", "ch": "c9"}, {"t": "Uric acid", "d": "It is end product of purine catabolism & is excreted in urine (see purine catabolism)", "ch": "c9"}, {"t": "Nomenclature", "d": "Nucleosides and nucleotides are named according to their nitrogenous bases", "ch": "c9"}, {"t": "cAMP", "d": "It’s is formed from ATP by adenylyl cyclase & it is converted to AMP by phosphodiesterase.", "ch": "c9"}, {"t": "cGMP", "d": "It is formed from GTP by guanylyl cyclase.", "ch": "c9"}, {"t": "Activated Precursors in Biosynthesis", "d": "A. S-Adenosyl methionine (Active Methionine) or (SAM)", "ch": "c9"}, {"t": "Coenzymes Components", "d": "A. Nicotinamide Adenine Dinucleotide (NAD+)", "ch": "c9"}, {"t": "Antiviral Drugs", "d": "Acycloguanosine (Acyclovir) → Inhibits viral DNA synthesis only with no effect on host cells .", "ch": "c9"}, {"t": "Dietary Purines And Pyrimidines", "d": "They are mainly present in the form of nucleic acids.", "ch": "c9"}, {"t": "Fate", "d": "Absorbed purines are oxidized (In the liver) to uric acid which is excreted in urine.", "ch": "c9"}, {"t": "Synthesis of phosphoribosylamine", "d": "N9of the purine ring is provided by the amide group of glutamine forming 5-phosphoribosylamine.", "ch": "c9"}, {"t": "Synthesis of Deoxyribonucleotides", "d": "This is catalyzed by an enzyme complex termed ribonucleotide reductase", "ch": "c9"}, {"t": "Feedback regulation", "d": "De novo purine nucleotide synthesis is a good example for multiple loops feedback inhibition.", "ch": "c9"}, {"t": "Availability of the substrates", "d": "The rate of the reaction catalyzed by glutamine: PRPP-amidotransferase is controlled by the intracellular concentration of PRPP and glutamine.", "ch": "c9"}, {"t": "Catabolism Of Purine Nucleotides", "d": "Purine nucleotides are degraded through a series of enzymatic reactions to form uric acid", "ch": "c9"}, {"t": "Defects of PRPP synthetase", "d": "Due to genetic mutation, the enzyme is either superactive or resistant to feedback inhibition.", "ch": "c9"}, {"t": "Lesch-Nyhan Syndrome", "d": "Complete deficiency of HGPRTase.", "ch": "c9"}, {"t": "Secondary Metabolic Gout", "d": "It is due to diseases which cause increase in purine catabolism e.g., cancer, leukemia, and psoriasis.", "ch": "c9"}, {"t": "Decreased Excretion of uric acid (Renal Gout)", "d": "Primary Renal Gout: It is due to primary or congenital renal disease.", "ch": "c9"}, {"t": "Primary Renal Gout", "d": "It is due to primary or congenital renal disease.", "ch": "c9"}, {"t": "Secondary Renal Gout", "d": "It is due to acquired renal disease.", "ch": "c9"}, {"t": "II. Hypouricemia", "d": "It is caused mainly by adenosine deaminase (ADA) deficiency.", "ch": "c9"}, {"t": "Deoxyribonucleic Acid (Dna)", "d": "It consists of two strands of polynucleotides", "ch": "c10"}, {"t": "DNA SECONDARY STRUCTURE, DOUBLE HELIX (dsDNA)", "d": "Watson and Crick proposed a structure for DNA in the form of a double helix.", "ch": "c10"}, {"t": "Base stacking", "d": "The base pairs inside the helix are stacked above each other by Van der Waals forces and hydrophobic interactions.", "ch": "c10"}, {"t": "Dimensions", "d": "The DNA is 2 nm in width.", "ch": "c10"}, {"t": "Denaturation of DNA", "d": "Heating DNA produces rupture of hydrogen bondsand separation of the two strands of DNA or DNA denaturation.", "ch": "c10"}, {"t": "Dna Tertiary Structures", "d": "The length of human DNA per cell is approximately 2 meters, and the diameter of the nucleus is 10 microns.", "ch": "c10"}, {"t": "Non-histone proteins", "d": "They interact with the major grooves.", "ch": "c10"}, {"t": "Mitochondrial DNA (mt-DNA)", "d": "DNA is mainly linear but sometimes it is circular as in DNA of mitochondria,chloroplasts (In plants) and bacteria.", "ch": "c10"}, {"t": "TRANSFER RNAs(tRNAs)", "d": "RNAs represent about 15% of the total RNA in the cell.", "ch": "c10"}, {"t": "The acceptor arm", "d": "It terminates at its 3` OH end by a specific sequence formed of CCA.", "ch": "c10"}, {"t": "D-arm", "d": "Contains an unusual base dihydrouracil.", "ch": "c10"}, {"t": "Anticodon arm", "d": "Contains 3 specific bases known as anticodon.", "ch": "c10"}, {"t": "Extra arm", "d": "Contains from 3 to 12 bases (with no base pairing) & the major site for variation in tRNA", "ch": "c10"}, {"t": "MESSENGER RNAs (mRNAs)", "d": "Messenger RNAs represent only about 5% of the RNA in the cell.", "ch": "c10"}, {"t": "RIBOSOMAL RNAs (rRNAs)", "d": "The rRNAs represent about 80% of the total RNA of the cell.", "ch": "c10"}, {"t": "OTHER FORMS OF RNAs (NON-CODING RNAs)", "d": "Required for regulation of transcription & translation", "ch": "c10"}, {"t": "Genes", "d": "A gene is an element of heredity, transmitted from parents to offspring in reproduction.", "ch": "c10"}, {"t": "Chromosome", "d": "A thread-like structure of DNA and proteins found in the nucleus of most living cells", "ch": "c10"}, {"t": "Genome", "d": "It is the total genetic information presented by the group of chromosomes in any cell.", "ch": "c10"}, {"t": "Phenotype", "d": "It is the outside or the observable traits depending on the genotype of the individual.", "ch": "c10"}, {"t": "Synthesis of the leading strand", "d": "DNA polymerase ε synthesizes the leading strand of DNA.", "ch": "c11"}, {"t": "Synthesis of the lagging strand", "d": "DNA-polymerase δ synthesizes the lagging strand of DNA.", "ch": "c11"}, {"t": "Proofreading of newly synthesized DNA strands", "d": "Misreading of the template sequence may result in permanent mutations.", "ch": "c11"}, {"t": "Removal of DNA supercoiling", "d": "When DNA unwinds, supercoils are formed during DNA replication.", "ch": "c11"}, {"t": "Synthesis of the leading strand", "d": "RNase H removes the RNA primers by its exonuclease activity.", "ch": "c11"}, {"t": "Joining of DNA fragments", "d": "DNA ligase joins the ends of adjacent fragments using ATP.", "ch": "c11"}, {"t": "Preservation Of Chromosomal Ends By Telomeres", "d": "The ends of the eukaryotic linear chromosomes are called telomeres.", "ch": "c11"}, {"t": "Role Of Telomerase In Restoration Of Telomeres", "d": "Telomerase is an enzyme with reverse transcriptase activity.", "ch": "c11"}, {"t": "Dna Repair", "d": "Replication process takes place at high accuracy, but an error can occur forevery 30,000bases.", "ch": "c11"}, {"t": "Recognition of the lesion", "d": "This is the function of an endonuclease", "ch": "c11"}, {"t": "Excision of damaged DNA", "d": "The damaged part is removed by an exonuclease.", "ch": "c11"}, {"t": "Filling the gap", "d": "This is catalyzed by a repair DNA polymerase β.", "ch": "c11"}, {"t": "Ligation", "d": "This is catalyzed by DNA ligase.", "ch": "c11"}, {"t": "Rna Synthesis (Transcription)", "d": "Synthesis of RNA from DNA is known as transcription.", "ch": "c12"}, {"t": "Principles Of Transcription And Terminology", "d": "Only one strand of DNA is transcribed.", "ch": "c12"}, {"t": "RNA synthesis includes four main phases", "d": "Preinitiation, Initiation, Elongation & Termination.", "ch": "c12"}, {"t": "Start site", "d": "The first nucleotide at the 3’ end of the transcription region of the template strand is designated as +1.", "ch": "c12"}, {"t": "Upstream", "d": "The 3’ direction of the template strand before the start site (+1) takes negative numbers -1 ,-2 ,-3 …. etc.", "ch": "c12"}, {"t": "Downstream", "d": "The5’direction of the template strand afterthestartsite(+1) takes positive numbers", "ch": "c12"}, {"t": "Promoter", "d": "The nucleotide sequence in the template strand at which the RNA polymerase begins attachment. It lies upstream the transcription region and marks the beginning.", "ch": "c12"}, {"t": "Terminator", "d": "The nucleotide sequence in the template strand lies downstream the transcription region and marks the end.", "ch": "c12"}, {"t": "Transcription region", "d": "The nucleotide sequence transcribed by RNA polymerase.", "ch": "c12"}, {"t": "Transcription unit", "d": "It includes the promoter, the transcription region, and the terminator.", "ch": "c12"}, {"t": "RNA polymerase I and III", "d": "For synthesis of rRNAs and tRNAs mainly.", "ch": "c12"}, {"t": "RNA polymerase II", "d": "For synthesis of mRNAs, most small nuclear RNAs (snRNAs) and micro RNAs (miRNAs).", "ch": "c12"}, {"t": "TATA box", "d": "It defines where transcription is to start along the DNA.", "ch": "c12"}, {"t": "CAAT box and GC box", "d": "They define when transcription is to start", "ch": "c12"}, {"t": "Pre-initiation", "d": "Transcriptional factors involved in this step are TFII A, B, D, E, F and H", "ch": "c12"}, {"t": "POST-TRANSCRIPTIONAL MODIFICATIONS OF mRNA", "d": "Messenger RNA is synthesized as a primary transcript (Immature) known as heterogeneous nuclear RNA (hnRNA).", "ch": "c12"}, {"t": "Capping At 5`End", "d": "Methyl-guanosine cap is added at the 5`end", "ch": "c12"}, {"t": "Polyadenylation At 3` End", "d": "Poly (A) polymerase (PAP) is responsible for the addition of poly(A) tail (Up to 200 adenine residues) at the 3`end of pre-mRNA.", "ch": "c12"}, {"t": "Splicing", "d": "In the primary RNA transcript, parts of mRNA do not code for amino acids.", "ch": "c12"}, {"t": "mRNA EDITING", "d": "Coding information of mRNA can be changed by RNA editing.", "ch": "c12"}, {"t": "Genetic Code", "d": "It is the nucleotide sequence of mRNA representing the code words for amino acids.", "ch": "c12"}, {"t": "Specificity", "d": "A particular codon always codes for only one amino acid, e.g., UUU codes only for phenylalanine.", "ch": "c12"}, {"t": "Degeneracy", "d": "An amino acid may be coded by more than one codon known as synonym codons (phenylalanine is coded by two synonym codons).", "ch": "c12"}, {"t": "Universality", "d": "Genetic code is nearly universal (same in all organisms).", "ch": "c12"}, {"t": "CODON RECOGNITION BY tRNA", "d": "Correct pairing of the codon of the mRNA with the anticodon of the tRNA is essential for accurate translation.", "ch": "c12"}, {"t": "Cc Wobble Hypothesis", "d": "The mechanism by which tRNAs can recognize more than one codon for a specific amino acid is described by the “Wobble” hypothesis.", "ch": "c12"}, {"t": "Formation of Aminoacyl-tRNA", "d": "In the cytosol, the 20 different amino acids are carried on their corresponding tRNAs by 20 different amino-acyl-tRNA synthetases", "ch": "c12"}, {"t": "Post-Translational Modifications", "d": "Most proteins, which emerge from ribosomes, are biologically inactive.", "ch": "c12"}, {"t": "Trimming", "d": "Many proteins secreted from cell are initially made as large, precursor molecules that are not functionally active.", "ch": "c12"}, {"t": "Covalentmodification", "d": "Amino acid residues within the peptide chain can be modified enzymatically", "ch": "c12"}, {"t": "Gene Mutations", "d": "Mutations are defined as permanent changes in a DNA sequence.", "ch": "c12"}, {"t": "Errors In Replication", "d": "If a non-complementary base to the template base is added during replication, this leads to mutation if the error is not repaired.", "ch": "c12"}, {"t": "Irradiation", "d": "Ultraviolet light (UV) or ionizing radiation (x-rays and gamma rays) can alter the structure of DNA.", "ch": "c12"}, {"t": "Oxidative damage", "d": "Oxidative DNA damage is implicated in several diseases.", "ch": "c12"}, {"t": "Base Substitution (Point Mutations)", "d": "Base substitutions are the most common type of mutation.", "ch": "c12"}, {"t": "Missense mutation", "d": "Leads to a changed codon & results in an amino acid change in protein product of it.", "ch": "c12"}, {"t": "Nonsense mutation", "d": "Leads to the conversion of an amino acid codon to a stop or non-sense codon.", "ch": "c12"}, {"t": "Silent mutation", "d": "Leads to formation of a synonym codon that codes for the same amino acid and no change occurs in the amino acid sequence of the gene products.", "ch": "c12"}, {"t": "Regulation Of Eukaryotic Gene Expression", "d": "Regulation of gene expression occurs at multiple levels, mainly at level of transcription.", "ch": "c13"}, {"t": "Epigenetic Mechanisms", "d": "Epigenetic means “Around the gene”, it refers to the changes that occur to the DNA and the histone proteins.", "ch": "c13"}, {"t": "Epigenetic Mechanisms", "d": "A change in the number of copies of a gene can affect amount of gene product produced", "ch": "c13"}, {"t": "Gene diminution (Decrease the number)", "d": "This occurs during development of RBCs as all genes disappear during maturation.", "ch": "c13"}, {"t": "Gene Rearrangement", "d": "Heavy & light chains of Igs are encoded by several hundred gene segments.", "ch": "c13"}, {"t": "Transcriptional Regulation", "d": "Regulation of gene expression at the level of transcription occurs through interaction between cis- and trans-acting elements.", "ch": "c13"}, {"t": "Cis-acting elements", "d": "These are DNA regulatory sequences flanking a gene.", "ch": "c13"}, {"t": "Trans-acting elements", "d": "They are the regulatory molecules which can diffuse from their site of synthesis in the cell to the DNA-binding site.", "ch": "c13"}, {"t": "Translational Regulation", "d": "Phosphorylation of some IFs blocks protein synthesis.", "ch": "c13"}, {"t": "Phases Of Cell Cycle", "d": "The cell cycle is divided into two main phases: the mitotic phase (M) & the interphase (I)", "ch": "c14"}, {"t": "Biological Significance", "d": "Eliminating individual cells whose survival would be harmful to the organism.", "ch": "c14"}, {"t": "Homeostasis", "d": "In normal, healthy adults, the number of cells is kept relatively constant owing to a balance between cell division and cell death.", "ch": "c14"}, {"t": "Extrinsic pathway", "d": "It is initiated through binding of a certain ligand to the tumor necrosis factor (TNF) or FAS receptors.", "ch": "c14"}, {"t": "Intrinsic (mitochondrial) pathway", "d": "It is used extensively in response to different forms of cellular stress.", "ch": "c14"}, {"t": "Anti-apoptotic modulators", "d": "(Bcl2-, Bcl-x, etc.) possess anti-apoptotic activity.", "ch": "c14"}, {"t": "Apoptotic modulators", "d": "(Bax, Bak, Bok) exert their apoptosis-modulating effects by controlling the release of cytochrome c from mitochondria to cytosol.", "ch": "c14"}, {"t": "DNA repair enzymes", "d": "They are termed anti-oncogenes; & their mutations remove certain control on growth & proliferation which play a major role in the development of cancer.", "ch": "c14"}]};
